\begin{prop}\ollabel{prop:stricttopartial}
Als $R$ een strikte ordening op~$A$ is, is $R^+ = R \cup \Id{A}$ een partiële
ordening. Als $R$ ook een strikte lineaire ordening is, is $R^+$ een lineaire
ordening.
\end{prop}

