\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
Als $<$ een strikte lineaire ordening op $A$ is, dan geldt:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

source_text:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
If $<$ is a strict linear order on $A$, then:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:extensionality-strictlinearorders}
Als $<$ een strikte lineaire ordening op $A$ is, dan geldt:
\[
  (\forall a, b \in A)((\forall x \in A)(x < a \liff x < b) \lif a = b).
\]
\end{prop}

ordinary_text:
\begin{proof}
Neem aan dat $(\forall x \in A)(x < a \liff x < b)$. Als $a < b$, dan zou
$a < a$ gelden. Dat kan niet, want $<$ is irreflexief. Dus $a \nless b$.
Om precies dezelfde reden geldt $b \nless a$. Dan moet $a = b$, want $<$ is
samenhangend.
\end{proof}

source_text:
\begin{proof}
Suppose $(\forall x \in A)(x < a \liff x < b)$. If $a < b$, then $a <
a$, contradicting the fact that $<$ is irreflexive; so $a \nless b$.
Exactly similarly, $b \nless a$. So $a = b$, as $<$ is connected.
\end{proof}

standard_text:
\begin{proof}
Stel $(\forall x \in A)(x < a \liff x < b)$. Als $a < b$, dan $a <
a$, in tegenspraak met de irreflexiviteit van $<$; dus $a \nless b$.
Geheel analoog geldt $b \nless a$. Dan volgt $a = b$ uit de samenhangendheid
van~$<$.
\end{proof}

