ordinary_text:
\begin{ex}
De functie $f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ gebruikt
$\lceil x \rceil$, de \emph{plafondfunctie}. Die geeft het kleinste
gehele getal dat groter is dan of gelijk is aan $x$. De functie somt
de gehele getallen~$\Int$ op. Je ziet hoe $f$ de getallen uit $\Int$
achtereenvolgens geeft door heen en weer te ``springen'' tussen positieve en negatieve
gehele getallen:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & \dots
\end{array}
\]
Je kunt $f$ ook zo per geval beschrijven:
\[
f(n) = \begin{cases}
  0 & \text{als $n = 1$}\\
  n/2 & \text{als $n$ even is}\\
  -(n-1)/2 & \text{als $n$ oneven en $>1$ is}
  \end{cases}
\]
\end{ex}

source_text:
\begin{ex}
The function $f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ (where
$\lceil x \rceil$ denotes the \emph{ceiling} function, which rounds
$x$ up to the nearest integer) enumerates the set of
integers~$\Int$. Notice how $f$ generates the values of $\Int$ by
``hopping'' back and forth between positive and negative integers:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & \dots
\end{array}
\]
You can also think of $f$ as defined by cases as follows:
\[
f(n) = \begin{cases}
  0 & \text{if $n = 1$}\\
  n/2 & \text{if $n$ is even}\\
  -(n-1)/2 & \text{if $n$ is odd and $>1$}
  \end{cases}
\]
\end{ex}

standard_text:
\begin{ex}
De functie $f(n) = (-1)^{n} \lceil \frac{(n-1)}{2}\rceil$ (waarbij
$\lceil x \rceil$ de \emph{plafondfunctie} voorstelt, die het kleinste
gehele getal groter dan of gelijk aan $x$ oplevert) somt de verzameling
gehele getallen~$\Int$ op. Merk op hoe $f$ de getallen uit $\Int$
opsomt door heen en weer te ``springen'' tussen positieve en
negatieve gehele getallen:
\[
\begin{array}{c c c c c c c c}
f(1) & f(2) & f(3) & f(4) & f(5) & f(6) & f(7) & \dots \\ \\
- \lceil \tfrac{0}{2} \rceil & \lceil \tfrac{1}{2}\rceil & - \lceil \tfrac{2}{2} \rceil & \lceil \tfrac{3}{2} \rceil & - \lceil \tfrac{4}{2} \rceil  & \lceil \tfrac{5}{2}
\rceil & - \lceil \tfrac{6}{2} \rceil & \dots \\ \\
0 & 1 & -1 & 2 & -2 & 3 & \dots
\end{array}
\]
We kunnen $f$ ook als volgt per geval definiëren:
\[
f(n) = \begin{cases}
  0 & \text{als $n = 1$}\\
  n/2 & \text{als $n$ even is}\\
  -(n-1)/2 & \text{als $n$ oneven en $>1$ is}
  \end{cases}
\]
\end{ex}

source_text:
\begin{prob}
  Show that if $A$ and $B$ are !!{enumerable}, so is $A \cup B$. To do
  this, suppose there are !!{surjective} functions $f\colon \PosInt \to
  A$ and $g\colon \PosInt \to B$, and define !!a{surjective}
  function~$h\colon \PosInt \to A \cup B$ and prove that it is
  !!{surjective}. Also consider the cases where $A$ or~$B = \emptyset$.
\end{prob}

standard_text:
\begin{prob}
  Toon aan dat als $A$ en $B$ !!{enumerable} zijn, ook $A \cup B$ dat is.
  Neem daartoe aan dat er !!{surjective} functies $f\colon \PosInt \to
  A$ en $g\colon \PosInt \to B$ bestaan. Definieer een !!a{surjective}
  functie~$h\colon \PosInt \to A \cup B$ en bewijs dat deze
  !!{surjective} is. Beschouw ook de gevallen waarin $A$ leeg is
  of~$B = \emptyset$.
\end{prob}

source_text:
\begin{prob}
  Show that if $B \subseteq A$ and $A$ is !!{enumerable}, so is~$B$. To
  do this, suppose there is !!a{surjective} function $f\colon \PosInt \to
  A$. Define !!a{surjective} function~$g\colon \PosInt \to B$ and prove
  that it is !!{surjective}. What happens if $B = \emptyset$?
\end{prob}

ordinary_text:
\begin{prob}
  Laat met inductie naar $n$ zien dat als $A_1$, $A_2$, \dots, $A_n$
  allemaal !!{enumerable} zijn, ook $A_1 \cup \dots \cup A_n$ dat is.
  Je mag aannemen dat als twee verzamelingen $A$ en~$B$ !!{enumerable}
  zijn, ook~$A \cup B$ dat is. 
\end{prob}

source_text:
\begin{prob}
  Show by induction on $n$ that if $A_1$, $A_2$, \dots, $A_n$ are all
  !!{enumerable}, so is $A_1 \cup \dots \cup A_n$. You may assume the
  fact that if two sets $A$ and~$B$ are !!{enumerable}, so is~$A \cup
  B$. 
\end{prob}

standard_text:
\begin{prob}
  Toon met inductie naar $n$ aan dat als $A_1$, $A_2$, \dots, $A_n$
  allemaal !!{enumerable} zijn, ook $A_1 \cup \dots \cup A_n$ dat is.
  Je mag gebruiken dat als twee verzamelingen $A$ en~$B$ !!{enumerable}
  zijn, ook~$A \cup B$ dat is. 
\end{prob}

ordinary_text:
\begin{prop}\ollabel{prop:enum-shift}
  Er bestaat een !!a{surjection} $f\colon \PosInt \to A$ precies
  wanneer er een !!a{surjection} $g\colon \Nat \to A$ bestaat.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:enum-shift}
  There is !!a{surjection} $f\colon \PosInt \to A$ iff there is
  !!a{surjection} $g\colon \Nat \to A$.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:enum-shift}
  Er bestaat een !!a{surjection} $f\colon \PosInt \to A$ precies dan
  als er een !!a{surjection} $g\colon \Nat \to A$ bestaat.
\end{prop}

ordinary_text:
\begin{proof}
  Begin met een !!a{surjection} $f\colon \PosInt \to A$. Definieer
  $g(n) = f(n+1)$ voor elke $n \in \Nat$. Dan is $g\colon \Nat \to A$
  !!{surjective}. Omgekeerd beginnen we met een !!a{surjection}
  $g\colon \Nat \to A$ en definiëren we $f(n) = g(n-1)$.
\end{proof}

source_text:
\begin{proof}
  Given !!a{surjection} $f\colon \PosInt \to A$, we can define $g(n) =
  f(n+1)$ for all $n \in \Nat$. It is easy to see that $g\colon \Nat
  \to A$ is !!{surjective}. Conversely, given !!a{surjection} $g\colon
  \Nat \to A$, define $f(n) = g(n-1)$.
\end{proof}

ordinary_text:
\begin{cor}\ollabel{cor:enum-nat}
Een verzameling $A$ is !!{enumerable} als zij leeg is of als er een
!!a{surjective} functie $f\colon \Nat \to A$ bestaat, en alleen dan.
\end{cor}

source_text:
\begin{cor}\ollabel{cor:enum-nat}
A set $A$ is !!{enumerable} iff it is empty or there is
!!a{surjective} function $f\colon \Nat \to A$.
\end{cor}

standard_text:
\begin{cor}\ollabel{cor:enum-nat}
Een verzameling $A$ is !!{enumerable} precies dan als zij leeg is of er
een !!a{surjective} functie $f\colon \Nat \to A$ bestaat.
\end{cor}

ordinary_text:
\begin{prop}\ollabel{prop:enum-bij}
Als $f\colon \PosInt \to A$ !!{surjective} is en dus een opsomming
van~$A$ is, bestaat er een !!a{bijection} $g\colon Z \to A$. Daarbij
is $Z$ gelijk aan~$\PosInt$ of aan $\{1, \dots, n\}$ voor een
$n \in \PosInt$.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:enum-bij}
Als $f\colon \PosInt \to A$ !!{surjective} is (dus een opsomming
van~$A$), bestaat er een !!a{bijection} $g\colon Z \to A$, waarbij $Z$
gelijk is aan~$\PosInt$ of aan $\{1, \dots, n\}$ voor een zekere
$n \in \PosInt$.
\end{prop}

ordinary_text:
\begin{cor}\ollabel{cor:enum-nat-bij}
Een verzameling $A$ is !!{enumerable} als zij leeg is of als er een
!!a{bijection} $f\colon N \to A$ bestaat, waarbij $N = \Nat$ of
$N = \{0, \dots, n\}$ voor een $n \in \Nat$, en alleen dan.
\end{cor}

source_text:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

standard_text:
\begin{cor}\ollabel{cor:enum-nat-bij}
Een verzameling $A$ is !!{enumerable} precies dan als zij leeg is of er
een !!a{bijection} $f\colon N \to A$ bestaat, waarbij $N = \Nat$ of
$N = \{0, \dots, n\}$ voor een zekere $n \in \Nat$.
\end{cor}

ordinary_text:
\begin{proof}
$A$ is !!{enumerable} als $A$ leeg is of als er een !!a{surjective}
$f\colon \PosInt \to A$ bestaat, en alleen dan. Uit
\olref{prop:enum-bij} volgt dat dit precies het geval is als er een
!!a{bijective} functie~$f\colon Z \to A$ bestaat waarvoor $Z =
\PosInt$ of $Z = \{1, \dots, n\}$ voor een $n \in \PosInt$. Hetzelfde
argument als in het bewijs van \olref{prop:enum-shift} laat zien dat
dit weer precies het geval is als er een !!a{bijection}
$g\colon N \to A$ bestaat, waarbij $N = \Nat$ of
$N = \{0, \dots, n-1\}$.
\end{proof}

source_text:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

standard_text:
\begin{proof}
$A$ is !!{enumerable} precies dan als $A$ leeg is of er een
!!a{surjective} $f\colon \PosInt \to A$ bestaat. Volgens
\olref{prop:enum-bij} geldt die laatste voorwaarde precies dan als er
een !!a{bijective} functie~$f\colon Z \to A$ bestaat, waarbij $Z =
\PosInt$ of $Z = \{1, \dots, n\}$ voor een zekere $n \in \PosInt$.
Met hetzelfde argument als in het bewijs van \olref{prop:enum-shift}
geldt dat op zijn beurt precies dan als er een !!a{bijection}
$g\colon N \to A$ bestaat, waarbij $N = \Nat$ of
$N = \{0, \dots, n-1\}$.
\end{proof}

ordinary_text:
\begin{prob}
  Volgens \olref[sfr][siz][enm]{defn:enumerable} is een verzameling $A$
  aftelbaar als $A = \emptyset$ of als er een !!a{surjective}
  $f\colon \PosInt \to A$ bestaat, en alleen dan. Je kunt een
  ``!!{enumerable} verzameling'' ook op een andere, even precieze manier definiëren: een
  verzameling is aftelbaar als er een !!a{injective} functie
  $g\colon A \to \PosInt$ bestaat, en alleen dan. Laat zien dat beide
  definities hetzelfde zeggen. Laat dus zien dat er een !!a{injective}
  functie $g\colon A \to \PosInt$ bestaat precies wanneer
  $A = \emptyset$ of er een !!a{surjective} $f\colon \PosInt \to A$
  bestaat.
\end{prob}

source_text:
\begin{prob}
  According to \olref[sfr][siz][enm]{defn:enumerable}, a set $A$ is
  enumerable iff $A = \emptyset$ or there is !!a{surjective} $f\colon
  \PosInt \to A$.  It is also possible to define ``!!{enumerable} set''
  precisely by: a set is enumerable iff there is !!a{injective}
  function $g\colon A \to \PosInt$.  Show that the definitions are
  equivalent, i.e., show that there is !!a{injective} function
  $g\colon A \to \PosInt$ iff either $A = \emptyset$ or there is
  !!a{surjective} $f\colon \PosInt \to A$.
\end{prob}

standard_text:
\begin{prob}
  Volgens \olref[sfr][siz][enm]{defn:enumerable} is een verzameling $A$
  aftelbaar precies dan als $A = \emptyset$ of er een !!a{surjective}
  $f\colon \PosInt \to A$ bestaat. We kunnen ``!!{enumerable}
  verzameling'' ook nauwkeurig definiëren door te zeggen dat een
  verzameling aftelbaar is precies dan als er een !!a{injective} functie
  $g\colon A \to \PosInt$ bestaat. Toon aan dat de definities
  gelijkwaardig zijn. Toon dus aan dat er een !!a{injective} functie
  $g\colon A \to \PosInt$ bestaat precies dan als $A = \emptyset$ of er
  een !!a{surjective} $f\colon \PosInt \to A$ bestaat.
\end{prob}

ordinary_text:
\begin{prop}\ollabel{natsquaredenumerable}
De verzameling $\Nat \times \Nat$ is !!{enumerable}.
\end{prop}

source_text:
\begin{prop}\ollabel{natsquaredenumerable}
$\Nat \times \Nat$ is !!{enumerable}.
\end{prop}

standard_text:
\begin{prop}\ollabel{natsquaredenumerable}
De verzameling $\Nat \times \Nat$ is !!{enumerable}.
\end{prop}

ordinary_text:
\begin{proof}
Neem de functie $f \colon \Nat \to \Nat\times\Nat$. Die koppelt elk getal
$k \in \Nat$ aan het paar $\tuple{n,m} \in \Nat \times \Nat$ waarvoor $k$ in
Cantors zigzagtabel op rij $n$ en in kolom $m$ staat. 
\end{proof}

source_text:
\begin{proof}
Let $f \colon \Nat \to \Nat\times\Nat$ take each $k \in \Nat$ to the
tuple $\tuple{n,m} \in \Nat \times \Nat$ such that $k$ is the value of
the $n$th row and $m$th column in Cantor's zig-zag array. 
\end{proof}

standard_text:
\begin{proof}
Zij $f \colon \Nat \to \Nat\times\Nat$ de functie die elke $k \in \Nat$
afbeeldt op het paar $\tuple{n,m} \in \Nat \times \Nat$ waarvoor $k$ de
waarde in rij $n$ en kolom $m$ van Cantors zigzagtabel is. 
\end{proof}

ordinary_text:
\begin{prop}
$\Nat^n$ is !!{enumerable} voor elke $n \in \Nat$.
\end{prop}

source_text:
\begin{prop}
$\Nat^n$ is !!{enumerable}, for every $n \in \Nat$.
\end{prop}

standard_text:
\begin{prop}
$\Nat^n$ is !!{enumerable} voor elke $n \in \Nat$.
\end{prop}

ordinary_text:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
Laat zien dat $(\PosInt)^n$ !!{enumerable} is voor elke $n \in \Nat$.
\end{prob}

source_text:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
Show that $(\PosInt)^n$ is !!{enumerable}, for every $n \in \Nat$.
\end{prob}

standard_text:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-n}
Bewijs dat $(\PosInt)^n$ !!{enumerable} is voor elke $n \in \Nat$.
\end{prob}

ordinary_text:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  Laat zien dat $(\PosInt)^*$ !!{enumerable} is. Je mag
  \cref{sfr:siz:zigzag:prob:posint-n} gebruiken.
\end{prob}

source_text:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  Show that $(\PosInt)^*$ is !!{enumerable}. You may assume \cref{sfr:siz:zigzag:prob:posint-n}.
\end{prob}

standard_text:
\begin{prob}\label{sfr:siz:zigzag:prob:posint-star}
  Bewijs dat $(\PosInt)^*$ !!{enumerable} is. Hierbij mag
  \cref{sfr:siz:zigzag:prob:posint-n} worden aangenomen.
\end{prob}

source_text:
This function $g$ is the \emph{inverse} of an enumeration of a set of
pairs. Such functions are called \emph{pairing functions}.
\end{explain}

standard_text:
Deze functie $g$ is de \emph{inverse} van een opsomming van een
verzameling paren. Zulke functies heten \emph{paarfuncties}.
\end{explain}

ordinary_text:
\begin{explain}
Met paarfuncties kunnen we bijvoorbeeld paren van natuurlijke getallen
coderen. Elk \emph{paar} krijgt dan \emph{één} getal. Met de
inverse van de paarfunctie gaan we de andere kant op: we vinden uit welk
paar bij het getal hoort. Dat heet het getal \emph{decoderen}.
\end{explain}

source_text:
\begin{explain}
We can use pairing functions to encode, e.g., pairs of natural numbers;
or, in other words, we can represent each \emph{pair} of elements
using a \emph{single} number. Using the inverse of the pairing
function, we can \emph{decode} the number, i.e., find out which
pair it represents.
\end{explain}

ordinary_text:
\begin{prob}
Geef een manier om alle niet-negatieve rationale getallen in één lijst
te zetten.
\end{prob}

source_text:
\begin{prob}
Give an enumeration of the set of all non-negative rational numbers. 
\end{prob}

standard_text:
\begin{prob}
Geef een opsomming van de verzameling van alle niet-negatieve rationale
getallen.
\end{prob}

ordinary_text:
\begin{prob}
Laat zien dat $\Rat$ !!{enumerable} is. Bedenk daarbij dat je elk
rationaal getal kunt schrijven als een breuk $z/m$ met $z \in \Int$,
$m \in \Nat^+$.
\end{prob}

source_text:
\begin{prob}
Show that $\Rat$ is !!{enumerable}. Recall that any rational number 
can be written as a fraction $z/m$ with $z \in \Int$, $m \in \Nat^+$.
\end{prob}

standard_text:
\begin{prob}
Toon aan dat $\Rat$ !!{enumerable} is. Bedenk dat elk rationaal getal
kan worden geschreven als een breuk $z/m$ met $z \in \Int$, $m \in \Nat^+$.
\end{prob}

ordinary_text:
\begin{prob}
Beschrijf hoe je alle elementen van $\Bin^*$ in één lijst zet.
\end{prob}

source_text:
\begin{prob}
Define an enumeration of $\Bin^*$.
\end{prob}

standard_text:
\begin{prob}
Definieer een opsomming van $\Bin^*$.
\end{prob}

source_text:
\begin{prob}
Recall from your introductory logic course that each possible truth
table expresses a truth function. In other words, the truth functions
are all functions from $\Bin^k \to \Bin$ for some~$k$. Prove that the
set of all truth functions is enumerable.
\end{prob}

standard_text:
\begin{prob}
Uit de inleidende cursus logica weten we dat elke mogelijke waarheidstafel een
waarheidsfunctie weergeeft. De waarheidsfuncties zijn dus precies alle functies
$\Bin^k \to \Bin$ voor een zekere~$k$. Bewijs dat de verzameling van alle
waarheidsfuncties kan worden opgesomd.
\end{prob}

ordinary_text:
\begin{prob}
Neem een willekeurige oneindige !!{enumerable} verzameling. Laat zien
dat de verzameling van alle eindige deelverzamelingen ervan ook
!!{enumerable} is.
\end{prob}

source_text:
\begin{prob}
Show that the set of all finite subsets of an arbitrary infinite
!!{enumerable} set is !!{enumerable}.
\end{prob}

standard_text:
\begin{prob}
Toon aan dat de verzameling van alle eindige deelverzamelingen van een
willekeurige oneindige !!{enumerable} verzameling !!{enumerable} is.
\end{prob}

ordinary_text:
\begin{prob}
Laat zien dat het samenvoegen van !!{enumerable} veel !!{enumerable}
verzamelingen weer een !!{enumerable} verzameling oplevert. Precies
gezegd: neem verzamelingen $A_1$, $A_2$, \dots{} waarvan elke $A_i$
!!{enumerable} is. Laat zien dat ook de verzameling waarin ze allemaal
samenkomen, $\bigcup_{i=1}^\infty A_i$, !!{enumerable} is. [Let op: dit
is moeilijk!]
\end{prob}

source_text:
\begin{prob}
Show that the !!{enumerable} union of !!{enumerable} sets is
!!{enumerable}. That is, whenever $A_1$, $A_2$, \dots{} are sets, and
each $A_i$ is !!{enumerable}, then the union $\bigcup_{i=1}^\infty
A_i$ of all of them is also !!{enumerable}. [NB: this is hard!]
\end{prob}

standard_text:
\begin{prob}
Toon aan dat een !!{enumerable} vereniging van !!{enumerable}
verzamelingen !!{enumerable} is. Dus: als $A_1$, $A_2$, \dots{}
verzamelingen zijn en elke $A_i$ !!{enumerable} is, dan is ook hun
vereniging $\bigcup_{i=1}^\infty A_i$ !!{enumerable}. [NB: dit is
moeilijk!]
\end{prob}

ordinary_text:
\begin{prob}
