\begin{defn}
$A$ is \emph{niet groter dan}~$B$, geschreven als $\cardle{A}{B}$, precies
als er !!a{injection} $f \colon A \to B$ bestaat.
\end{defn}

source_text:
\begin{defn}
$A$ is \emph{no larger than}~$B$, written $\cardle{A}{B}$, iff there
is !!a{injection} $f \colon A \to B$.
\end{defn}

standard_text:
\begin{defn}
$A$ is \emph{niet groter dan}~$B$, geschreven als $\cardle{A}{B}$, precies
dan wanneer er !!a{injection} $f \colon A \to B$ bestaat.
\end{defn}

ordinary_text:
\begin{defn}
$A$ is \emph{kleiner dan}~$B$, geschreven als $\cardless{A}{B}$, precies als
er !!a{injection}~$f\colon A \to B$ bestaat, maar geen
!!{bijection}~$g\colon A \to B$. Er geldt dus $\cardle{A}{B}$ en
$\cardneq{A}{B}$.
\end{defn}

source_text:
\begin{defn}
$A$ is \emph{smaller than}~$B$, written $\cardless{A}{B}$, iff there
is !!a{injection}~$f\colon A \to B$ but no !!{bijection}~$g\colon A
\to B$, i.e., $\cardle{A}{B}$ and $\cardneq{A}{B}$.
\end{defn}

standard_text:
\begin{defn}
$A$ is \emph{kleiner dan}~$B$, geschreven als $\cardless{A}{B}$, precies dan
wanneer er !!a{injection}~$f\colon A \to B$ bestaat, maar geen
!!{bijection}~$g\colon A \to B$, oftewel $\cardle{A}{B}$ en
$\cardneq{A}{B}$.
\end{defn}

