source_text:
\begin{prob}
  Show that there cannot be !!a{injection} $g\colon \Pow{A} \to
  A$, for any set~$A$. Hint: Suppose $g\colon \Pow{A} \to A$ is
  !!{injective}. Consider $D = \Setabs{g(B)}{B \subseteq A \text{ and
  } g(B) \notin B}$. Let $x = g(D)$. Use the fact that $g$ is
  !!{injective} to derive a contradiction. 
\end{prob}

ordinary_text:
\begin{editorial}
  In deze paragraaf is een opsomming een bijectie met (een eerste deel
  van) $\Nat$. Zo gebeurt het in de verzamelingenleer. Dit wijkt een
  beetje af van de definities in \olref[enm]{sec} en herhaalt alle
  voorbeelden uit die paragraaf. De tekst is hier ook wat korter.
\end{editorial}

\begin{defn}
  \ollabel{defn:enumerable}
  Een verzameling~$A$ is !!{enumerable} precies wanneer $A =
  \emptyset$ of wanneer~$A$ een opsomming heeft. We zeggen dat $A$
  !!{nonenumerable} is precies wanneer $A$ niet !!{enumerable} is.
\end{defn}

source_text:
\begin{defn}
  \ollabel{defn:enumerable}
  A set~$A$ is !!{enumerable} iff either $A = \emptyset$ or there is
  an enumeration of~$A$. We say that $A$ is !!{nonenumerable} iff $A$
  is not !!{enumerable}.
\end{defn}

standard_text:
\begin{defn}
  \ollabel{defn:enumerable}
  Een verzameling~$A$ is !!{enumerable} dan en slechts dan als $A =
  \emptyset$ of er een opsomming van~$A$ bestaat. We noemen $A$
  !!{nonenumerable} dan en slechts dan als $A$ niet !!{enumerable} is.
\end{defn}

ordinary_text:
\begin{explain}
Een verzameling is dus !!{enumerable} als zij leeg is of als je haar
!!{element}s met een opsomming één voor één kunt tellen.
\end{explain}

source_text:
\begin{explain}
So a set is !!{enumerable} iff it is empty or you can use an
enumeration to count out its !!{element}s.
\end{explain}

standard_text:
\begin{explain}
Een verzameling is dus !!{enumerable} dan en slechts dan als zij leeg
is of als haar !!{element}s met een opsomming één voor één kunnen
worden geteld.
\end{explain}

ordinary_text:
\begin{ex}
De identiteitsfunctie $\Id{\Nat} \colon \Nat \to \Nat$, met
$\Id{\Nat}(n) = n$, somt gewoon de natuurlijke getallen op. De functie
die de \emph{positieve} natuurlijke getallen $\Nat^+ = \Nat \setminus
\{0\}$ opsomt, is $g(n) = n + 1$: de opvolgerfunctie.
\end{ex}

source_text:
\begin{ex}
A function enumerating the natural numbers is simply the identity
function $\Id{\Nat} \colon \Nat \to \Nat$ given by $\Id{\Nat}(n) = n$. A
function enumerating the \emph{positive} natural numbers, $\Nat^+ =
\Nat \setminus \{0\}$, is the function $g(n) = n + 1$, i.e., the
successor function.
\end{ex}

standard_text:
\begin{ex}
De identiteitsfunctie $\Id{\Nat} \colon \Nat \to \Nat$, gegeven door
$\Id{\Nat}(n) = n$, somt de natuurlijke getallen op. De functie die de
\emph{positieve} natuurlijke getallen $\Nat^+ = \Nat \setminus
\{0\}$ opsomt, is de functie $g(n) = n + 1$, dus de opvolgerfunctie.
\end{ex}

ordinary_text:
\begin{prob}
Laat zien dat een verzameling $A$ !!{enumerable} is precies wanneer
$A = \emptyset$ of er !!a{surjection} $f\colon \Nat \to A$ is. Laat
ook zien dat $A$ !!{enumerable} is precies wanneer er !!a{injection}
$g\colon A \to \Nat$ is.
\end{prob}

source_text:
\begin{prob}
Show that a set $A$ is !!{enumerable} iff either $A = \emptyset$ or
there is !!a{surjection} $f\colon \Nat \to A$. Show that $A$ is
!!{enumerable} iff there is !!a{injection} $g\colon A \to \Nat$. 
\end{prob}

standard_text:
\begin{prob}
Bewijs dat een verzameling $A$ !!{enumerable} is dan en slechts dan
als $A = \emptyset$ of er !!a{surjection} $f\colon \Nat \to A$
bestaat. Bewijs dat $A$ !!{enumerable} is dan en slechts dan als er
!!a{injection} $g\colon A \to \Nat$ bestaat.
\end{prob}

ordinary_text:
\begin{ex}
Neem de functies $f\colon \Nat \to \Nat$ en $g \colon \Nat \to \Nat$
die zijn vastgelegd door
\begin{align*}
  f(n) & = 2n \text{ en}\\
  g(n) & = 2n+1
\end{align*}
De eerste somt de even natuurlijke getallen op en de tweede de oneven
natuurlijke getallen. Geen van beide is !!{surjective}. Daarom is
geen van beide een opsomming van $\Nat$.
\end{ex}

source_text:
\begin{ex}
The functions $f\colon \Nat \to \Nat$ and $g \colon \Nat \to \Nat$
given by
\begin{align*}
  f(n) & = 2n \text{ and}\\
  g(n) & = 2n+1
\end{align*}
respectively enumerate the even natural numbers and the odd natural
numbers. But neither is !!{surjective}, so neither is an enumeration
of $\Nat$.
\end{ex}

standard_text:
\begin{ex}
De functies $f\colon \Nat \to \Nat$ en $g \colon \Nat \to \Nat$,
gegeven door
\begin{align*}
  f(n) & = 2n \text{ en}\\
  g(n) & = 2n+1
\end{align*}
sommen respectievelijk de even en de oneven natuurlijke getallen op.
Geen van beide is echter !!{surjective}; geen van beide is dus een
opsomming van $\Nat$.
\end{ex}

ordinary_text:
\begin{prob}
