\begin{thm}[\emph{Inductieprincipe voor !!{formula}s}]
  \ollabel{thm:induction}  
  Neem aan dat een eigenschap~$P$ voor alle atomaire !!{formula}s
  geldt. Neem ook aan dat aan de volgende voorwaarden is voldaan:
  \begin{enumerate}
    \tagitem{prvNot}{zij geldt voor $\lnot !A$ zodra zij voor~$!A$
      geldt;}{}
    \tagitem{prvAnd}{zij geldt voor $(!A \land !B)$ zodra zij voor
      $!A$ en~$!B$ geldt;}{}
    \tagitem{prvOr}{zij geldt voor $(!A \lor !B)$ zodra zij voor
      $!A$ en~$!B$ geldt;}{}
    \tagitem{prvIf}{zij geldt voor $(!A \lif !B)$ zodra zij voor
      $!A$ en~$!B$ geldt;}{}
    \tagitem{prvIff}{zij geldt voor $(!A \liff !B)$ zodra zij voor
      $!A$ en~$!B$ geldt.}{}
  \end{enumerate}
  Dan geldt $P$ voor alle !!{formula}s.
\end{thm}

source_text:
\begin{thm}[\emph{Principle of induction on !!{formula}s}]
  \ollabel{thm:induction}  
  If some property~$P$ holds for all the atomic !!{formula}s and is
  such that
  \begin{enumerate}
    \tagitem{prvNot}{it holds for $\lnot !A$ whenever it holds
      for~$!A$;}{}
    \tagitem{prvAnd}{it holds for $(!A \land !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvOr}{it holds for $(!A \lor !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvIf}{it holds for $(!A \lif !B)$
      whenever it holds for $!A$ and~$!B$;}{}
    \tagitem{prvIff}{it holds for $(!A \liff !B)$
      whenever it holds for $!A$ and~$!B$;}{}
  \end{enumerate}
  then $P$ holds for all !!{formula}s.
\end{thm}

standard_text:
\begin{thm}[\emph{Inductieprincipe voor !!{formula}s}]
  \ollabel{thm:induction}  
  Stel dat een eigenschap~$P$ voor alle atomaire !!{formula}s geldt en
  bovendien aan de volgende voorwaarden voldoet:
  \begin{enumerate}
    \tagitem{prvNot}{zij geldt voor $\lnot !A$ wanneer zij voor~$!A$
      geldt;}{}
    \tagitem{prvAnd}{zij geldt voor $(!A \land !B)$ wanneer zij voor
      $!A$ en~$!B$ geldt;}{}
    \tagitem{prvOr}{zij geldt voor $(!A \lor !B)$ wanneer zij voor
      $!A$ en~$!B$ geldt;}{}
    \tagitem{prvIf}{zij geldt voor $(!A \lif !B)$ wanneer zij voor
      $!A$ en~$!B$ geldt;}{}
    \tagitem{prvIff}{zij geldt voor $(!A \liff !B)$ wanneer zij voor
      $!A$ en~$!B$ geldt.}{}
  \end{enumerate}
  Dan geldt $P$ voor alle !!{formula}s.
\end{thm}

