ordinary_text:
\begin{defn} 
\begin{enumerate}
\item !!^a{formula}~$!A$ is \emph{vervulbaar}, dus waar te maken, als
  er een~$\pAssign{v}$ bestaat waarvoor $\pSat{v}{!A}$. De formule is
  \emph{onvervulbaar} als er geen $\pAssign{v}$ bestaat waarvoor
  $\pSat{v}{!A}$;
\item !!^a{formula}~$!A$ is een \emph{tautologie} als
  $\pSat{v}{!A}$ voor alle !!{valuation}s~$\pAssign{v}$;
\item !!^a{formula}~$!A$ is \emph{contingent} als zij wel vervulbaar
  is, maar geen tautologie;
\item Laat $\Gamma$ een verzameling !!{formula}s zijn. Dan geldt
  $\Gamma \Entails !A$ (``uit $\Gamma$ volgt $!A$'') precies als
  $\pSat{v}{!A}$ geldt voor elke !!{valuation}~$\pAssign{v}$ waarvoor
  $\pSat{v}{\Gamma}$;
\item Laat $\Gamma$ een verzameling !!{formula}s zijn. De verzameling
  $\Gamma$ is \emph{vervulbaar} als er !!a{valuation}~$\pAssign{v}$
  bestaat waarvoor $\pSat{v}{\Gamma}$. Anders is $\Gamma$
  \emph{onvervulbaar}.
\end{enumerate} 
\end{defn}

source_text:
\begin{defn} 
\begin{enumerate}
\item !!^a{formula}~$!A$ is \emph{satisfiable} if for
  some~$\pAssign{v}$, $\pSat{v}{!A}$; it is
  \emph{unsatisfiable} if for no $\pAssign{v}$, $\pSat{v}{!A}$;
\item !!^a{formula}~$!A$ is a \emph{tautology} if $\pSat{v}{!A}$ for
  all !!{valuation}s~$\pAssign{v}$;
\item !!^a{formula}~$!A$ is \emph{contingent} if it is satisfiable but
  not a tautology;
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma \Entails !A$ (``$\Gamma$
  entails $!A$'') if and only if $\pSat{v}{!A}$ for every
  !!{valuation}~$\pAssign{v}$ for which $\pSat{v}{\Gamma}$.
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma$ is
  \emph{satisfiable} if there is !!a{valuation}~$\pAssign{v}$ for which
  $\pSat{v}{\Gamma}$, and $\Gamma$ is
  \emph{unsatisfiable} otherwise.
\end{enumerate} 
\end{defn}

standard_text:
\begin{defn} 
\begin{enumerate}
\item !!^a{formula}~$!A$ is \emph{vervulbaar} als voor een zekere
  $\pAssign{v}$ geldt dat $\pSat{v}{!A}$; zij is \emph{onvervulbaar}
  als voor geen enkele $\pAssign{v}$ geldt dat $\pSat{v}{!A}$;
\item !!^a{formula}~$!A$ is een \emph{tautologie} als
  $\pSat{v}{!A}$ voor alle !!{valuation}s~$\pAssign{v}$;
\item !!^a{formula}~$!A$ is \emph{contingent} als zij vervulbaar is,
  maar geen tautologie;
\item Als $\Gamma$ een verzameling !!{formula}s is, dan geldt
  $\Gamma \Entails !A$ (``uit $\Gamma$ volgt $!A$'') dan en slechts dan
  als $\pSat{v}{!A}$ voor elke !!{valuation}~$\pAssign{v}$ waarvoor
  $\pSat{v}{\Gamma}$;
\item Als $\Gamma$ een verzameling !!{formula}s is, dan is $\Gamma$
  \emph{vervulbaar} als er !!a{valuation}~$\pAssign{v}$ bestaat waarvoor
  $\pSat{v}{\Gamma}$, en anders is $\Gamma$ \emph{onvervulbaar}.
\end{enumerate} 
\end{defn}

ordinary_text:
\begin{prob} 
 Bekijk de volgende vier !!{formula}s. Bepaal voor elke formule of zij
 (a)~vervulbaar, (b)~een tautologie en (c)~contingent is.
\begin{enumerate}
  \item \( ( \Obj p_0 \lif ( \lnot \Obj p_1 \lif \lnot \Obj p_0 ) ) \).
  \item \( ( ( \Obj p_0 \land \lnot \Obj p_1 ) \lif ( \lnot \Obj p_0 \land \Obj p_2 )) \liff ( ( \Obj p_2 \lif \Obj p_0 ) \lif ( \Obj p_0 \lif \Obj p_1 )) \).
  \item \( ( \Obj p_0 \liff \Obj p_1 ) \lif ( \Obj p_2 \liff \lnot \Obj p_1 ) \).
  \item \( (( \Obj p_0 \liff ( \lnot \Obj p_1 \land \Obj p_2 )) \lor ( \Obj p_2 \lif ( \Obj p_0 \liff \Obj p_1 ))) \).
\end{enumerate}
\end{prob}

