ordinary_text:
\begin{prop}
\ollabel{prop:semanticalfacts} 
\begin{enumerate} 
\item $!A$ is een tautologie precies als
  $\emptyset \Entails !A$; 
\item Als $\Gamma \Entails !A$ en $\Gamma \Entails !A \lif !B$, dan
  geldt $\Gamma \Entails !B$;
\item Als $\Gamma$ vervulbaar is, dan is elke eindige deelverzameling
  van $\Gamma$ ook vervulbaar; 
\item \ollabel{def:monotonicity} Monotoniciteit: als
  $\Gamma \subseteq \Delta$ en $\Gamma \Entails !A$, dan geldt ook
  $\Delta \Entails !A$;
\item \ollabel{def:Cut} Transitiviteit: als $\Gamma \Entails !A$ en
  $\Delta \cup \{ !A\} \Entails !B$, dan geldt
  $\Gamma \cup \Delta \Entails !B$.
\end{enumerate}
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:semanticalfacts} 
\begin{enumerate} 
\item $!A$ is a tautology if and only if
  $\emptyset \Entails !A$; 
\item If $\Gamma \Entails !A$ and $\Gamma \Entails !A \lif !B$ then
  $\Gamma \Entails !B$;
\item If $\Gamma$ is satisfiable then every finite subset of $\Gamma$
  is also satisfiable; 
\item \ollabel{def:monotonicity} Monotonicity: if $\Gamma \subseteq \Delta$
  and $\Gamma \Entails !A$ then also $\Delta \Entails !A$;
\item \ollabel{def:Cut} Transitivity: if $\Gamma \Entails !A$ and
  $\Delta \cup \{ !A\} \Entails !B$ then $\Gamma \cup \Delta \Entails
  !B$.
\end{enumerate}
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:semanticalfacts} 
\begin{enumerate} 
\item $!A$ is een tautologie dan en slechts dan als
  $\emptyset \Entails !A$; 
\item Als $\Gamma \Entails !A$ en $\Gamma \Entails !A \lif !B$, dan
  geldt $\Gamma \Entails !B$;
\item Als $\Gamma$ vervulbaar is, dan is elke eindige deelverzameling
  van $\Gamma$ eveneens vervulbaar; 
\item \ollabel{def:monotonicity} Monotoniciteit: als
  $\Gamma \subseteq \Delta$ en $\Gamma \Entails !A$, dan geldt ook
  $\Delta \Entails !A$;
\item \ollabel{def:Cut} Transitiviteit: als $\Gamma \Entails !A$ en
  $\Delta \cup \{ !A\} \Entails !B$, dan geldt
  $\Gamma \cup \Delta \Entails !B$.
\end{enumerate}
\end{prop}

