ordinary_text:
\begin{defn}[Beginsequent]
Een sequent heet een \emph{beginsequent} als hij
\iftag{prvFalse,prvTrue}{een van de volgende vormen heeft:
  \begin{enumerate}
    \item $!A \Sequent !A$
    \tagitem{prvTrue}{$\quad \Sequent \ltrue$}{}
    \tagitem{prvFalse}{$\lfalse \Sequent \quad$}{}
  \end{enumerate}}
{de vorm $!A \Sequent !A$ heeft}. Dit geldt voor elke !!{sentence} $!A$
van de taal.
\end{defn}

source_text:
\begin{defn}[Initial Sequent]
An \emph{initial sequent} is a sequent
\iftag{prvFalse,prvTrue}{of one of the following forms:
  \begin{enumerate}
    \item $!A \Sequent !A$
    \tagitem{prvTrue}{$\quad \Sequent \ltrue$}{}
    \tagitem{prvFalse}{$\lfalse \Sequent \quad$}{}
  \end{enumerate}}
{of the form $!A \Sequent !A$} for any !!{sentence} $!A$ in the language.
\end{defn}

standard_text:
\begin{defn}[Beginsequent]
Een \emph{beginsequent} is een sequent
\iftag{prvFalse,prvTrue}{van een van de volgende vormen:
  \begin{enumerate}
    \item $!A \Sequent !A$
    \tagitem{prvTrue}{$\quad \Sequent \ltrue$}{}
    \tagitem{prvFalse}{$\lfalse \Sequent \quad$}{}
  \end{enumerate}}
{van de vorm $!A \Sequent !A$} voor elke !!{sentence} $!A$ van de taal.
\end{defn}

