\begin{prop}\ollabel{prop:provability-contr}
  If $\Gamma \Proves !A$ and $\Gamma \cup \{!A\}$ is
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:provability-contr}
  Als $\Gamma \Proves !A$ en $\Gamma \cup \{!A\}$ inconsistent is,
  dan is $\Gamma$ inconsistent.
\end{prop}

ordinary_text:
\begin{proof}
Er zijn eindige verzamelingen $\Gamma_0$ en $\Gamma_1 \subseteq
\Gamma$ waarvoor $\Log{LK}$ de sequenten $\Gamma_0 \Sequent
!A$ en $!A, \Gamma_1 \Sequent \quad$ !!{derive}s. Noem de
$\Log{LK}$-!!{derivation} van $\Gamma_0 \Sequent !A$ nu~$\pi_0$. Noem
de $\Log{LK}$-!!{derivation} van $\Gamma_1, !A \Sequent \quad$
nu~$\pi_1$. Met de snederegel kunnen we dan het volgende !!{derive}:
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

source_text:
\begin{proof}
There are finite $\Gamma_0$ and $\Gamma_1 \subseteq \Gamma$ such that
$\Log{LK}$ !!{derive}s $\Gamma_0 \Sequent !A$ and $!A, \Gamma_1
\Sequent \quad$.  Let the $\Log{LK}$-!!{derivation} of $\Gamma_0 \Sequent
!A$ be~$\pi_0$ and the $\Log{LK}$-!!{derivation} of $\Gamma_1, !A
\Sequent \quad$ be~$\pi_1$. We can then !!{derive}
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

standard_text:
\begin{proof}
Er bestaan eindige $\Gamma_0$ en $\Gamma_1 \subseteq \Gamma$ zodat
$\Log{LK}$ de sequenten $\Gamma_0 \Sequent !A$ en $!A, \Gamma_1
\Sequent \quad$ !!{derive}s. Noem de $\Log{LK}$-!!{derivation} van
$\Gamma_0 \Sequent !A$ nu~$\pi_0$ en de
$\Log{LK}$-!!{derivation} van $\Gamma_1, !A \Sequent \quad$
nu~$\pi_1$. Dan kunnen we het volgende !!{derive}:
\begin{prooftree}
\AxiomC{}
\RightLabel{$\pi_0$}
\Deduce$ \Gamma_0 \fCenter !A $
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$!A, \Gamma_1 \fCenter $
\RightLabel{\Cut}
\BinaryInf$ \Gamma_0,\Gamma_1 \fCenter $
\end{prooftree}

source_text:
Since $\Gamma_0 \subseteq \Gamma$ and $\Gamma_1 \subseteq \Gamma$,
$\Gamma_0 \cup \Gamma_1 \subseteq \Gamma$, hence $\Gamma$~is inconsistent.
\end{proof}

