standard_text:
\begin{prop}\ollabel{prop:explicit-inc}
  Als $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$, dan is $\Gamma$
  inconsistent.
\end{prop}

ordinary_text:
\begin{proof}
  Neem aan dat $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$. Dan is er
  !!a{derivation}~$\pi$ van een sequent $\Gamma_0 \Sequent !A$. De
  sequent $\lnot !A, \Gamma_0 \Sequent \quad$ is dan eveneens
  !!{derivable}:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  Omdat $\lnot !A \in \Gamma$ en $\Gamma_0 \subseteq \Gamma$, laat
  deze afleiding zien dat $\Gamma$ inconsistent is.
\end{proof}

source_text:
\begin{proof}
  Suppose $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$.  Then there
  is !!a{derivation}~$\pi$ of a sequent $\Gamma_0 \Sequent !A$. The
  sequent $\lnot !A, \Gamma_0 \Sequent \quad$ is also !!{derivable}:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  Since $\lnot !A \in \Gamma$ and $\Gamma_0 \subseteq \Gamma$, this
  shows that $\Gamma$ is inconsistent.
\end{proof}

standard_text:
\begin{proof}
  Stel dat $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$. Er is dan
  !!a{derivation}~$\pi$ van een sequent $\Gamma_0 \Sequent !A$. Ook de
  sequent $\lnot !A, \Gamma_0 \Sequent \quad$ is !!{derivable}:
  \begin{prooftree}
    \AxiomC{}
    \RightLabel{$\pi$}
    \Deduce$\Gamma_0 \fCenter !A$
    \Axiom$!A \fCenter !A$
    \RightLabel{\LeftR{\lnot}}
    \UnaryInf$\lnot !A, !A \fCenter$
    \RightLabel{\LeftR{\Exchange}}
    \UnaryInf$!A, \lnot !A \fCenter$
    \RightLabel{\Cut}
    \BinaryInf$\Gamma_0, \lnot !A \fCenter$
  \end{prooftree}
  Omdat $\lnot !A \in \Gamma$ en $\Gamma_0 \subseteq \Gamma$, toont
  dit aan dat $\Gamma$ inconsistent is.
\end{proof}

