standard_text:
\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ is inconsistent.
  \item Zowel $!A \Proves !A \lor !B$ als $!B \Proves !A \lor !B$.
  \end{enumerate}
\end{prop}

ordinary_text:
\begin{proof}
  \begin{enumerate}
  \item Om het eerste punt te bewijzen, geven we !!a{derivation} van
    de sequent $!A \lor !B, \lnot !A, \lnot !B \Sequent$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !A, !A \fCenter$
      \doubleLine
      \UnaryInf$!A, \lnot !A, \lnot !B \fCenter$
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !B, !B \fCenter$
      \doubleLine
      \UnaryInf$!B, \lnot !A, \lnot !B \fCenter$
      \RightLabel{\LeftR{\lor}}
      \BinaryInf$ !A \lor !B, \lnot !A, \lnot !B \fCenter $
    \end{prooftree}
    (Een dubbele afleidingslijn staat voor meerdere stappen met
    verzwakking, contractie en verwisseling.)
  \item Het tweede punt volgt uit !!{derivation}s van de twee
    sequenten $!A \Sequent !A \lor !B$ en $!B \Sequent !A \lor !B$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!A \fCenter !A \lor !B$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!B \fCenter !A \lor !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

source_text:
\begin{proof}
  \begin{enumerate}
  \item We give !!a{derivation} of the sequent $!A \lor !B, \lnot !A,
    \lnot !B \Sequent$:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !A, !A \fCenter$
      \doubleLine
      \UnaryInf$!A, \lnot !A, \lnot !B \fCenter$
      \Axiom$!B \fCenter !B$
      \RightLabel{\LeftR{\lnot}}
      \UnaryInf$\lnot !B, !B \fCenter$
      \doubleLine
      \UnaryInf$!B, \lnot !A, \lnot !B \fCenter$
      \RightLabel{\LeftR{\lor}}
      \BinaryInf$ !A \lor !B, \lnot !A, \lnot !B \fCenter $
    \end{prooftree}
    (Recall that double inference lines indicate several weakening,
    contraction, and exchange inferences.)
  \item   Both sequents $!A \Sequent !A \lor !B$ and $!B \Sequent !A
    \lor !B$ have !!{derivation}s:
    \begin{prooftree}
      \Axiom$!A \fCenter !A$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!A \fCenter !A \lor !B$
      \DisplayProof\qquad\bottomAlignProof
      \Axiom$!B \fCenter !B$
      \RightLabel{\RightR{\lor}}
      \UnaryInf$!B \fCenter !A \lor !B$
    \end{prooftree}
  \end{enumerate}
\end{proof}

standard_text:
\begin{proof}
  \begin{enumerate}
