ordinary_text:
\begin{proof}
Als $\Gamma \Proves !A$, dan is er een eindige deelverzameling
$\Gamma_0 \subseteq \Gamma$ waarvoor !!a{derivation} van
$\Gamma_0 \Sequent !A$ bestaat. Volgens
\olref{thm:sequent-soundness} maakt elke
\iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$}
ofwel een $!B \in \Gamma_0$ onwaar, ofwel $!A$ waar. Als dus
$\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan ook
$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$.
\end{proof}

source_text:
\begin{proof}
If $\Gamma \Proves !A$ then for some finite subset $\Gamma_0 \subseteq
\Gamma$, there is !!a{derivation} of $\Gamma_0 \Sequent !A$.  By
\olref{thm:sequent-soundness}, every
\iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$}
either makes some $!B \in \Gamma_0$ false or makes $!A$ true.  Hence,
if $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ then also
$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$.
\end{proof}

standard_text:
\begin{proof}
Als $\Gamma \Proves !A$, dan is er voor een eindige deelverzameling
$\Gamma_0 \subseteq \Gamma$ !!a{derivation} van $\Gamma_0 \Sequent
!A$. Volgens \olref{thm:sequent-soundness} maakt elke
\iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$}
ofwel een $!B \in \Gamma_0$ onwaar, ofwel $!A$ waar. Als dus
$\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan ook
$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$.
\end{proof}

