source_text:
\begin{defn}[Theorems]
A !!{sentence}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ in natural deduction in which all assumptions are
!!{discharged}.  We write $\Proves !A$ if $!A$ is a theorem and
$\Proves/ !A$ if it is not.
\end{defn}

ordinary_text:
\begin{prop}[Reflexiviteit]
\ollabel{prop:reflexivity}
Als $!A \in \Gamma$, dan $\Gamma \Proves !A$.
\end{prop}

source_text:
\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

standard_text:
\begin{prop}[Reflexiviteit]
\ollabel{prop:reflexivity}
Als $!A \in \Gamma$, dan $\Gamma \Proves !A$.
\end{prop}

ordinary_text:
\begin{proof}
De aanname $!A$ op zichzelf is al !!a{derivation} van~$!A$. De enige
!!{undischarged} aanname is $!A$, en die staat in~$\Gamma$.
\end{proof}

source_text:
\begin{proof}
The assumption $!A$ by itself is !!a{derivation} of~$!A$ where every
!!{undischarged} assumption (i.e., $!A$) is in~$\Gamma$.
\end{proof}

standard_text:
\begin{proof}
De aanname $!A$ op zichzelf is !!a{derivation} van~$!A$ waarin elke
!!{undischarged} aanname (namelijk $!A$) tot~$\Gamma$ behoort.
\end{proof}

ordinary_text:
\begin{prop}[Monotonie]
\ollabel{prop:monotonicity}
Als $\Gamma \subseteq \Delta$ en $\Gamma \Proves !A$, dan $\Delta
\Proves !A$.
\end{prop}

source_text:
\begin{prop}[Monotonicity]
