standard_text:
\begin{prop}[Monotonie]
\ollabel{prop:monotonicity}
Als $\Gamma \subseteq \Delta$ en $\Gamma \Proves !A$, dan $\Delta
\Proves !A$.
\end{prop}

ordinary_text:
\begin{proof}
Elke !!{derivation} van $!A$ uit $\Gamma$ is ook !!a{derivation} van
$!A$ uit~$\Delta$.
\end{proof}

source_text:
\begin{proof}
Any !!{derivation} of $!A$ from $\Gamma$ is also !!a{derivation} of
$!A$ from~$\Delta$.
\end{proof}

standard_text:
\begin{proof}
Elke !!{derivation} van $!A$ uit $\Gamma$ is tevens !!a{derivation}
van $!A$ uit~$\Delta$.
\end{proof}

ordinary_text:
\begin{prop}[Transitiviteit]
\ollabel{prop:transitivity}
Als $\Gamma \Proves !A$ en $\{!A\} \cup \Delta \Proves
!B$, dan $\Gamma \cup \Delta \Proves !B$.
\end{prop}

source_text:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup \Delta \Proves
!B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

standard_text:
\begin{prop}[Transitiviteit]
\ollabel{prop:transitivity}
Als $\Gamma \Proves !A$ en $\{!A\} \cup \Delta \Proves
!B$, dan $\Gamma \cup \Delta \Proves !B$.
\end{prop}

ordinary_text:
\begin{proof}
Uit $\Gamma \Proves !A$ volgt dat er !!a{derivation}~$\delta_0$
van~$!A$ bestaat. Alle !!{undischarged} aannamen daarvan staan
in~$\Gamma$. Uit $\{!A\} \cup \Delta \Proves !B$ volgt dat er
!!a{derivation}~$\delta_1$ van~$!B$ bestaat. Alle !!{undischarged}
aannamen daarvan staan in~$\{!A\} \cup \Delta$. Beschouw nu:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
Alle !!{undischarged} aannamen staan nu in $\Gamma \cup
\Delta$. Dit toont dus $\Gamma \cup \Delta \Proves !B$ aan.
\end{proof}

source_text:
\begin{proof}
If $\Gamma \Proves !A$, there is !!a{derivation}~$\delta_0$ of~$!A$
with all !!{undischarged} assumptions in~$\Gamma$.  If $\{!A\} \cup
\Delta \Proves !B$, then there is !!a{derivation}~$\delta_1$ of~$!B$
with all !!{undischarged} assumptions in~$\{!A\} \cup \Delta$.
Now consider:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
The !!{undischarged} assumptions are now all among $\Gamma \cup
\Delta$, so this shows $\Gamma \cup \Delta \Proves !B$.
\end{proof}

standard_text:
\begin{proof}
Als $\Gamma \Proves !A$, bestaat er !!a{derivation}~$\delta_0$
van~$!A$ waarvan alle !!{undischarged} aannamen in~$\Gamma$ liggen.
Als $\{!A\} \cup \Delta \Proves !B$, bestaat er !!a{derivation}
~$\delta_1$ van~$!B$ waarvan alle !!{undischarged} aannamen in
~$\{!A\} \cup \Delta$ liggen. Beschouw nu:
\begin{prooftree}
  \AxiomC{$\Delta, \Discharge{!A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$!B$}
  \DischargeRule{\Intro{\lif}}{1}
  \UnaryInfC{$!A \lif !B$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lif}}
  \BinaryInfC{$!B$}
\end{prooftree}
De !!{undischarged} aannamen behoren nu alle tot $\Gamma \cup
\Delta$, en dit toont dus $\Gamma \cup \Delta \Proves !B$ aan.
\end{proof}

ordinary_text:
\begin{prop}
\ollabel{prop:incons}
De volgende uitspraken zijn equivalent.
    \begin{enumerate}
      \item \( \Gamma \) is inconsistent.
      \item \( \Gamma \Proves {!A} \) geldt voor elke
        !!{sentence}~\( {!A} \).
      \item Zowel \( \Gamma \Proves {!A} \) als
        \( \Gamma \Proves \lnot {!A} \) geldt voor minstens één
        !!{sentence}~\( {!A} \).
    \end{enumerate}
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:incons}
The following are equivalent. 
    \begin{enumerate}
      \item \( \Gamma \) is inconsistent.
      \item \( \Gamma \Proves {!A} \) for every !!{sentence}~\( {!A} \).
      \item \( \Gamma \Proves {!A} \) and \( \Gamma \Proves \lnot {!A} \) for some !!{sentence}~\( {!A} \).
    \end{enumerate}
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:incons}
De volgende uitspraken zijn equivalent.
    \begin{enumerate}
      \item \( \Gamma \) is inconsistent.
      \item \( \Gamma \Proves {!A} \) voor elke !!{sentence}~\( {!A} \).
      \item Zowel \( \Gamma \Proves {!A} \) als
        \( \Gamma \Proves \lnot {!A} \) geldt voor een zekere
        !!{sentence}~\( {!A} \).
    \end{enumerate}
\end{prop}

