ordinary_text:
\begin{prop}[Compactheid]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item Als $\Gamma \Proves !A$, dan is er een eindige
    deelverzameling $\Gamma_0 \subseteq \Gamma$ waarvoor
    $\Gamma_0 \Proves !A$.
  \item Als elke eindige deelverzameling van~$\Gamma$ consistent is,
    dan is $\Gamma$ consistent.
  \end{enumerate}
\end{prop}

source_text:
\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

standard_text:
\begin{prop}[Compactheid]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item Als $\Gamma \Proves !A$, dan bestaat er een eindige
    deelverzameling $\Gamma_0 \subseteq \Gamma$ waarvoor
    $\Gamma_0 \Proves !A$.
  \item Als elke eindige deelverzameling van~$\Gamma$ consistent is,
    dan is $\Gamma$ consistent.
  \end{enumerate}
\end{prop}

ordinary_text:
\begin{proof}
  \begin{enumerate}
    \item Als $\Gamma \Proves !A$, is er !!a{derivation}~$\delta$
      van~$!A$ uit~$\Gamma$. Laat $\Gamma_0$ bestaan uit de
      !!{undischarged} aannamen van~$\delta$. Elke !!{derivation} is
      eindig. Daarom kan $\Gamma_0$ maar eindig veel !!{sentence}s
      bevatten. Dus is $\delta$ !!a{derivation} van~$!A$ uit een
      eindige~$\Gamma_0 \subseteq \Gamma$.
    \item Dit is de contrapositie van (1) in het bijzondere geval
      $!A \ident \lfalse$.
  \end{enumerate}
\end{proof}

source_text:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is
      !!a{derivation}~$\delta$ of~$!A$ from~$\Gamma$. Let $\Gamma_0$
      be the set of !!{undischarged} assumptions of~$\delta$.  Since
      any !!{derivation} is finite, $\Gamma_0$ can only contain
      finitely many !!{sentence}s.  So, $\delta$ is !!a{derivation}
      of~$!A$ from a finite~$\Gamma_0 \subseteq \Gamma$.
    \item This is the contrapositive of (1) for the special case $!A
      \ident \lfalse$.
  \end{enumerate}
\end{proof}

standard_text:
\begin{proof}
  \begin{enumerate}
    \item Als $\Gamma \Proves !A$, bestaat er !!a{derivation}
      ~$\delta$ van~$!A$ uit~$\Gamma$. Laat $\Gamma_0$ de verzameling
      !!{undischarged} aannamen van~$\delta$ zijn. Omdat elke
      !!{derivation} eindig is, kan $\Gamma_0$ slechts eindig veel
      !!{sentence}s bevatten. Dus is $\delta$ !!a{derivation} van
      ~$!A$ uit een eindige~$\Gamma_0 \subseteq \Gamma$.
    \item Dit is de contrapositie van (1) voor het bijzondere geval
      $!A \ident \lfalse$.
  \end{enumerate}
\end{proof}

