source_text:
We will now establish a number of properties of the !!{derivability}
relation.  They are independently interesting, but each will play a
role in the proof of the completeness theorem.

ordinary_text:
\begin{prop}\ollabel{prop:provability-contr}
  Als $\Gamma \Proves !A$ en $\Gamma \cup \{!A\}$ inconsistent is,
  dan is $\Gamma$ inconsistent.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:provability-contr}
  If $\Gamma \Proves !A$ and $\Gamma \cup \{!A\}$ is inconsistent,
  then $\Gamma$ is inconsistent.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:provability-contr}
  Als $\Gamma \Proves !A$ en $\Gamma \cup \{!A\}$ inconsistent is,
  dan is $\Gamma$ inconsistent.
\end{prop}

ordinary_text:
\begin{proof}
Noem de !!{derivation} van~$!A$ uit~$\Gamma$~$\delta_1$. Noem de
!!{derivation} van~$\lfalse$ uit $\Gamma \cup \{!A\}$~$\delta_2$.
Dan kunnen we dit !!{derive}:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\AxiomC{$\Gamma$}
\RightLabel{$\delta_1$}
\DeduceC{$!A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
In de nieuwe !!{derivation} is de aanname~$!A$ !!{discharged}. Daarom
is het !!a{derivation} uit~$\Gamma$.
\end{proof}

source_text:
\begin{proof}
Let the !!{derivation} of~$!A$ from~$\Gamma$ be~$\delta_1$ and the
!!{derivation} of~$\lfalse$ from $\Gamma \cup \{!A\}$
be~$\delta_2$. We can then !!{derive}:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\AxiomC{$\Gamma$}
\RightLabel{$\delta_1$}
\DeduceC{$!A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
In the new !!{derivation}, the assumption~$!A$ is !!{discharged}, so it is
!!a{derivation} from~$\Gamma$.
\end{proof}

standard_text:
\begin{proof}
Laat de !!{derivation} van~$!A$ uit~$\Gamma$~$\delta_1$ zijn en laat
de !!{derivation} van~$\lfalse$ uit $\Gamma \cup \{!A\}$~$\delta_2$
zijn. Dan kunnen we het volgende !!{derive}:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\AxiomC{$\Gamma$}
\RightLabel{$\delta_1$}
\DeduceC{$!A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
In de nieuwe !!{derivation} is de aanname~$!A$ !!{discharged}; het is
dus !!a{derivation} uit~$\Gamma$.
\end{proof}

ordinary_text:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ precies als $\Gamma \cup \{\lnot !A\}$
inconsistent is.
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ iff $\Gamma \cup \{\lnot !A\}$ is inconsistent.
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:prov-incons}
$\Gamma \Proves !A$ dan en slechts dan als
$\Gamma \cup \{\lnot !A\}$ inconsistent is.
\end{prop}

ordinary_text:
\begin{proof}
Stel eerst dat $\Gamma \Proves !A$. Er is dan !!a{derivation}
~$\delta_0$ van~$!A$ waarvan de !!{undischarged} aannamen in
~$\Gamma$ staan. Zo krijgen we !!a{derivation} van $\lfalse$ uit
$\Gamma \cup \{\lnot !A\}$:
\begin{prooftree}
  \AxiomC{$\lnot !A$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lnot}}
  \BinaryInfC{$\lfalse$}
\end{prooftree}

source_text:
\begin{proof}
First suppose $\Gamma \Proves !A$, i.e., there is
!!a{derivation}~$\delta_0$ of~$!A$ from !!{undischarged}
assumptions~$\Gamma$. We obtain !!a{derivation} of $\lfalse$ from
$\Gamma \cup \{\lnot !A\}$ as follows:
\begin{prooftree}
  \AxiomC{$\lnot !A$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lnot}}
  \BinaryInfC{$\lfalse$}
\end{prooftree}

standard_text:
\begin{proof}
Stel eerst dat $\Gamma \Proves !A$. Er bestaat dan dus
!!a{derivation}~$\delta_0$ van~$!A$ uit de !!{undischarged}
aannamen~$\Gamma$. We verkrijgen als volgt !!a{derivation} van
$\lfalse$ uit $\Gamma \cup \{\lnot !A\}$:
\begin{prooftree}
  \AxiomC{$\lnot !A$}
  \AxiomC{$\Gamma$}
  \RightLabel{$\delta_0$}
  \DeduceC{$!A$}
  \RightLabel{\Elim{\lnot}}
  \BinaryInfC{$\lfalse$}
\end{prooftree}

ordinary_text:
Neem nu aan dat $\Gamma \cup \{\lnot !A\}$ inconsistent is. Laat
$\delta_1$ de bijbehorende !!{derivation} van~$\lfalse$ zijn, met
!!{undischarged} aannamen in~$\Gamma \cup \{\lnot !A\}$. Zo krijgen
we !!a{derivation} van~$!A$ uit alleen~$\Gamma$ door~$\FalseCl$ te
gebruiken:
\begin{prooftree}
  \AxiomC{$\Gamma, \Discharge{\lnot !A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$\lfalse$}
  \RightLabel{\FalseCl}
  \DischargeRule{\FalseCl}{1}
  \UnaryInfC{$!A$}
\end{prooftree}
\end{proof}

source_text:
Now assume $\Gamma \cup \{\lnot !A\}$ is inconsistent, and let
$\delta_1$ be the corresponding !!{derivation} of~$\lfalse$ from
!!{undischarged} assumptions in~$\Gamma \cup \{\lnot !A\}$. We obtain
!!a{derivation} of~$!A$ from~$\Gamma$ alone by using~$\FalseCl$:
\begin{prooftree}
  \AxiomC{$\Gamma, \Discharge{\lnot !A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$\lfalse$}
  \RightLabel{\FalseCl}
  \DischargeRule{\FalseCl}{1}
  \UnaryInfC{$!A$}
\end{prooftree}
\end{proof}

standard_text:
Veronderstel nu dat $\Gamma \cup \{\lnot !A\}$ inconsistent is en
laat $\delta_1$ de bijbehorende !!{derivation} van~$\lfalse$ uit
!!{undischarged} aannamen in~$\Gamma \cup \{\lnot !A\}$ zijn. We
verkrijgen !!a{derivation} van~$!A$ uit uitsluitend~$\Gamma$ door
~$\FalseCl$ te gebruiken:
\begin{prooftree}
  \AxiomC{$\Gamma, \Discharge{\lnot !A}{1}$}
  \RightLabel{$\delta_1$}
  \DeduceC{$\lfalse$}
  \RightLabel{\FalseCl}
  \DischargeRule{\FalseCl}{1}
  \UnaryInfC{$!A$}
\end{prooftree}
\end{proof}

ordinary_text:
\begin{prob}
Bewijs dat $\Gamma \Proves \lnot !A$ precies als
$\Gamma \cup \{!A\}$ inconsistent is.
\end{prob}

source_text:
\begin{prob}
Prove that $\Gamma \Proves \lnot !A$ iff $\Gamma \cup \{!A\}$ is
inconsistent.
\end{prob}

standard_text:
\begin{prob}
Bewijs dat $\Gamma \Proves \lnot !A$ dan en slechts dan als
$\Gamma \cup \{!A\}$ inconsistent is.
\end{prob}

ordinary_text:
\begin{prop}\ollabel{prop:explicit-inc}
  Als $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$, dan is $\Gamma$
  inconsistent.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:explicit-inc}
  If $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$, then $\Gamma$ is
  inconsistent.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:explicit-inc}
  Als $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$, dan is $\Gamma$
  inconsistent.
\end{prop}

ordinary_text:
\begin{proof}
  Stel dat $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$. Dan is er
  !!a{derivation}~$\delta$ van~$!A$ uit~$\Gamma$. Kijk naar deze
  eenvoudige toepassing van de regel $\Elim{\lnot}$:
  \begin{prooftree}
    \AxiomC{$\lnot !A$}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lnot}}
    \BinaryInfC{$\lfalse$}
  \end{prooftree}
  Omdat $\lnot !A \in \Gamma$, staan alle !!{undischarged} aannamen
  in~$\Gamma$. Dit laat zien dat $\Gamma \Proves \lfalse$.
\end{proof}

source_text:
\begin{proof}
  Suppose $\Gamma \Proves !A$ and $\lnot !A \in \Gamma$.  Then there
  is !!a{derivation}~$\delta$ of~$!A$ from~$\Gamma$. Consider this
    simple application of the $\Elim{\lnot}$ rule:
  \begin{prooftree}
    \AxiomC{$\lnot !A$}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lnot}}
    \BinaryInfC{$\lfalse$}
  \end{prooftree}
  Since $\lnot !A \in \Gamma$, all !!{undischarged} assumptions are
  in~$\Gamma$, this shows that $\Gamma \Proves \lfalse$.
\end{proof}

standard_text:
\begin{proof}
  Stel dat $\Gamma \Proves !A$ en $\lnot !A \in \Gamma$. Dan bestaat
  er !!a{derivation}~$\delta$ van~$!A$ uit~$\Gamma$. Beschouw deze
  eenvoudige toepassing van de regel $\Elim{\lnot}$:
  \begin{prooftree}
    \AxiomC{$\lnot !A$}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lnot}}
    \BinaryInfC{$\lfalse$}
  \end{prooftree}
  Omdat $\lnot !A \in \Gamma$, liggen alle !!{undischarged} aannamen
  in~$\Gamma$. Dit toont aan dat $\Gamma \Proves \lfalse$.
\end{proof}

