ordinary_text:
\begin{proof}
Er zijn !!{derivation}s $\delta_1$ en $\delta_2$ van respectievelijk
~$\lfalse$ uit $\Gamma \cup \{ !A \}$ en~$\lfalse$ uit
$\Gamma \cup \{ \lnot !A \}$. Daarmee kunnen we dit !!{derive}:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{\lnot !A}{2}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{2}
\UnaryInfC{$\lnot \lnot !A$}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_1$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
De aannamen $!A$ en $\lnot !A$ zijn !!{discharged}. Dit is dus
!!a{derivation} van~$\lfalse$ uit alleen~$\Gamma$. Daarom is
$\Gamma$ inconsistent.
\end{proof}

source_text:
\begin{proof}
There are !!{derivation}s $\delta_1$ and $\delta_2$ of~$\lfalse$ from
  $\Gamma \cup \{ !A \}$ and $\lfalse$ from $\Gamma \cup \{ \lnot !A
  \}$, respectively. We can then !!{derive}
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{\lnot !A}{2}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{2}
\UnaryInfC{$\lnot \lnot !A$}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_1$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
Since the assumptions $!A$ and $\lnot !A$ are !!{discharged}, this is
!!a{derivation} of~$\lfalse$ from~$\Gamma$ alone. Hence $\Gamma$ is
inconsistent.
\end{proof}

standard_text:
\begin{proof}
Er bestaan !!{derivation}s $\delta_1$ en $\delta_2$ van respectievelijk
~$\lfalse$ uit $\Gamma \cup \{ !A \}$ en~$\lfalse$ uit
$\Gamma \cup \{ \lnot !A \}$. Dan kunnen we het volgende !!{derive}:
\begin{prooftree}
\AxiomC{$\Gamma, \Discharge{\lnot !A}{2}$}
\RightLabel{$\delta_2$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{2}
\UnaryInfC{$\lnot \lnot !A$}
\AxiomC{$\Gamma, \Discharge{!A}{1}$}
\RightLabel{$\delta_1$}
\DeduceC{$\lfalse$}
\DischargeRule{\Intro{\lnot}}{1}
\UnaryInfC{$\lnot !A$}
\RightLabel{\Elim{\lnot}}
\BinaryInfC{$\lfalse$}
\end{prooftree}
Omdat de aannamen $!A$ en $\lnot !A$ zijn !!{discharged}, is dit
!!a{derivation} van~$\lfalse$ uit uitsluitend~$\Gamma$. Bijgevolg is
$\Gamma$ inconsistent.
\end{proof}

