ordinary_text:
\begin{explain}
!!^a{derivation}ssysteem, zoals natuurlijke deductie, is
\emph{correct} als het alleen dingen kan !!{derive} die werkelijk
volgen. Correctheid geeft dus een veiligheidsgarantie voor
!!{derivation}ssystemen. Welke precieze eigenschap we nodig hebben,
hangt van de situatie af. We willen bijvoorbeeld weten dat
\begin{enumerate}
\item elke !!{derivable} !!{sentence}
  \iftag{FOL}{geldig}{onder elke valuatie waar} is;
\item als !!a{sentence} !!{derivable} is uit andere zinnen, zij daar
  ook logisch uit volgt;
\item als een verzameling !!{sentence}s inconsistent is, zij niet waar
  te maken is.
\end{enumerate}
Dit zijn belangrijke eigenschappen van !!a{derivation}ssysteem. Als
een ervan niet geldt, kan het systeem te veel !!{derive} en deugt het
niet. Daarom is het heel belangrijk om de correctheid van
!!a{derivation}ssysteem te bewijzen.
\end{explain}

source_text:
\begin{explain}
!!^a{derivation} system, such as natural deduction, is \emph{sound}
if it cannot !!{derive} things that do not actually follow.  Soundness is
thus a kind of guaranteed safety property for !!{derivation} systems.
Depending on which proof theoretic property is in question, we would
like to know for instance, that
\begin{enumerate}
\item every !!{derivable} !!{sentence} is \iftag{FOL}{valid}{a tautology};
\item if !!a{sentence} is !!{derivable} from some others, it is also a
  consequence of them;
\item if a set of !!{sentence}s is inconsistent, it is unsatisfiable.
\end{enumerate}
These are important properties of !!a{derivation} system. If any of
them do not hold, the !!{derivation} system is deficient---it would
!!{derive} too much.  Consequently, establishing the soundness of a
!!{derivation} system is of the utmost importance.
\end{explain}

standard_text:
\begin{explain}
!!^a{derivation}ssysteem, zoals natuurlijke deductie, is
\emph{correct} als het geen zaken kan !!{derive} die in werkelijkheid
niet volgen. Correctheid is dus een soort gegarandeerde
veiligheidseigenschap van !!{derivation}ssystemen. Afhankelijk van de
bewijstheoretische eigenschap in kwestie willen we bijvoorbeeld weten
dat
\begin{enumerate}
\item elke !!{derivable} !!{sentence} \iftag{FOL}{geldig}{een
  tautologie} is;
\item als !!a{sentence} !!{derivable} is uit enkele andere, zij ook een
  gevolg daarvan is;
\item als een verzameling !!{sentence}s inconsistent is, zij
  onvervulbaar is.
\end{enumerate}
Dit zijn belangrijke eigenschappen van !!a{derivation}ssysteem. Als
een ervan niet geldt, schiet het !!{derivation}ssysteem tekort: het zou
te veel !!{derive}. Het is daarom van het grootste belang de
correctheid van !!a{derivation}ssysteem vast te stellen.
\end{explain}

ordinary_text:
\begin{thm}[Correctheid]
\ollabel{thm:soundness}
Als $!A$ !!{derivable} is uit de !!{undischarged} aannamen
$\Gamma$, dan $\Gamma \Entails !A$.
\end{thm}

source_text:
\begin{thm}[Soundness]
\ollabel{thm:soundness}
If $!A$ is !!{derivable} from the !!{undischarged} assumptions
$\Gamma$, then $\Gamma \Entails !A$.
\end{thm}

standard_text:
\begin{thm}[Correctheid]
\ollabel{thm:soundness}
Als $!A$ !!{derivable} is uit de !!{undischarged} aannamen
$\Gamma$, dan $\Gamma \Entails !A$.
\end{thm}

ordinary_text:
\begin{proof}
Laat $\delta$ !!a{derivation} van $!A$ zijn. We gebruiken inductie
over het aantal inferenties in~$\delta$.

source_text:
\begin{proof}
Let $\delta$ be !!a{derivation} of $!A$. We proceed by
induction on the number of inferences in~$\delta$.

standard_text:
\begin{proof}
Laat $\delta$ !!a{derivation} van $!A$ zijn. We voeren inductie uit
naar het aantal inferenties in~$\delta$.

ordinary_text:
\begin{enumerate}
\item Stel dat de laatste inferentie \Intro{\lnot} is. De
  !!{derivation} heeft dan deze vorm:
  \begin{prooftree}
    \AxiomC{$\Gamma, \Discharge{!A}{n}$}
    \RightLabel{$\delta_1$}
    \DeduceC{$\lfalse$}
    \DischargeRule{\Intro{\lnot}}{n}
    \UnaryInfC{$\lnot !A$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $\lfalse$ uit de
  !!{undischarged} aannamen $\Gamma \cup \{!A\}$ van~$\delta_1$.
  Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  We moeten laten zien: als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\lnot !A}$. Neem voor een bewijs via
  tegenspraak aan dat $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, maar
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{\lnot !A}$. Dit laatste betekent
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Dan zou
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma \cup \{!A\}}$ gelden. Dat is
  in strijd met de inductiehypothese. Dus
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\lnot !A}$.

source_text:
\begin{enumerate}
\item Suppose that the last inference is \Intro{\lnot}: The
  !!{derivation} has the form
  \begin{prooftree}
    \AxiomC{$\Gamma, \Discharge{!A}{n}$}
    \RightLabel{$\delta_1$}
    \DeduceC{$\lfalse$}
    \DischargeRule{\Intro{\lnot}}{n}
    \UnaryInfC{$\lnot !A$}
  \end{prooftree}
  By inductive hypothesis, $\lfalse$ follows from the !!{undischarged}
  assumptions $\Gamma \cup \{!A\}$ of~$\delta_1$. Consider
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}. We
  need to show that, if $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, then
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\lnot !A}$. Suppose for reductio
  that $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, but
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{\lnot !A}$, i.e.,
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. This would mean that
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma \cup \{!A\}}$. This is
  contrary to our inductive hypothesis. So,
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\lnot !A}$.

standard_text:
\begin{enumerate}
\item Veronderstel dat de laatste inferentie \Intro{\lnot} is. De
  !!{derivation} heeft dan de vorm
  \begin{prooftree}
    \AxiomC{$\Gamma, \Discharge{!A}{n}$}
    \RightLabel{$\delta_1$}
    \DeduceC{$\lfalse$}
    \DischargeRule{\Intro{\lnot}}{n}
    \UnaryInfC{$\lnot !A$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $\lfalse$ uit de
  !!{undischarged} aannamen $\Gamma \cup \{!A\}$ van~$\delta_1$.
  Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  We moeten aantonen dat, als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\lnot !A}$. Veronderstel voor een
  bewijs uit het ongerijmde dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, maar
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{\lnot !A}$, dat wil zeggen
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Dit zou betekenen dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma \cup \{!A\}}$, in strijd
  met onze inductiehypothese. Dus
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\lnot !A}$.

ordinary_text:
\item De laatste inferentie is \Elim{\land}. Er zijn twee
  mogelijkheden: we mogen $!A$ of $!B$ uit de uitgangsformule
  $!A \land !B$ afleiden. Bekijk de eerste mogelijkheid. De
  !!{derivation}~$\delta$ ziet er zo uit:
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A \land !B$}
    \RightLabel{\Elim{\land}}
    \UnaryInfC{$!A$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A \land !B$ uit de
  !!{undischarged} aannamen~$\Gamma$ van~$\delta_1$. Beschouw
  !!a{structure}~\iftag{FOL}{$\Struct{M}$}{$\pAssign{v}$}. We moeten
  laten zien: als $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Neem aan dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$. De inductiehypothese
  ($\Gamma \Entails !A \land !B$) geeft
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$. Per definitie geldt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$ precies als zowel
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. (De mogelijkheid waarin $!B$
  uit $!A \land !B$ wordt afgeleid, werkt op dezelfde manier.)

source_text:
\item The last inference is \Elim{\land}: There are two variants: $!A$
  or $!B$ may be inferred from the premise $!A \land !B$. Consider the
  first case. The !!{derivation}~$\delta$ looks like this:
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A \land !B$}
    \RightLabel{\Elim{\land}}
    \UnaryInfC{$!A$}
  \end{prooftree}
  By inductive hypothesis, $!A \land !B$ follows from the
  !!{undischarged} assumptions~$\Gamma$ of~$\delta_1$. Consider
  !!a{structure}~\iftag{FOL}{$\Struct{M}$}{$\pAssign{v}$}. We need to
  show that, if $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, then
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Suppose
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$. By our inductive
  hypothesis ($\Gamma \Entails !A \land !B$), we know that
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$. By definition,
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$ iff
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ and
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$.  (The case where $!B$ is
  inferred from $!A \land !B$ is handled similarly.)

standard_text:
\item De laatste inferentie is \Elim{\land}. Er zijn twee varianten:
  $!A$ of $!B$ mag uit de premisse $!A \land !B$ worden afgeleid.
  Beschouw het eerste geval. De !!{derivation}~$\delta$ ziet er als
  volgt uit:
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A \land !B$}
    \RightLabel{\Elim{\land}}
    \UnaryInfC{$!A$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A \land !B$ uit de
  !!{undischarged} aannamen~$\Gamma$ van~$\delta_1$. Beschouw
  !!a{structure}~\iftag{FOL}{$\Struct{M}$}{$\pAssign{v}$}. We moeten
  aantonen dat, als $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Veronderstel
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$. Uit onze
  inductiehypothese ($\Gamma \Entails !A \land !B$) weten we dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$. Per definitie geldt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$ dan en slechts dan
  als $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ en
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. (Het geval waarin $!B$ uit
  $!A \land !B$ wordt afgeleid, verloopt op dezelfde wijze.)

ordinary_text:
\item De laatste inferentie is \Intro{\lor}. Er zijn twee
  mogelijkheden: we mogen $!A \lor !B$ afleiden uit de
  uitgangsformule~$!A$ of uit~$!B$. Bekijk de eerste mogelijkheid. De
  !!{derivation} heeft deze vorm:
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A$}
    \RightLabel{\Intro{\lor}}
    \UnaryInfC{$!A \lor !B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A$ uit de !!{undischarged}
  aannamen~$\Gamma$ van~$\delta_1$. Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  We moeten laten zien: als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lor !B}$. Neem aan dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$. Dan geldt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ wegens
  $\Gamma \Entails !A$ (de inductiehypothese). Daarom geldt ook
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lor !B}$. (De mogelijkheid
  waarin $!A \lor !B$ uit~$!B$ wordt afgeleid, werkt op dezelfde
  manier.)

source_text:
\item The last inference is \Intro{\lor}: There are two variants: $!A
  \lor !B$ may be inferred from the premise~$!A$ or the
  premise~$!B$. Consider the first case. The !!{derivation} has the form
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A$}
    \RightLabel{\Intro{\lor}}
    \UnaryInfC{$!A \lor !B$}
  \end{prooftree}
  By inductive hypothesis, $!A$ follows from the !!{undischarged}
  assumptions~$\Gamma$ of~$\delta_1$.  Consider
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}. We
  need to show that, if $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, then
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lor !B}$. Suppose
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$; then
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ since $\Gamma \Entails !A$ (the
  inductive hypothesis). So it must also be the case that
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lor !B}$.  (The case where $!A
  \lor !B$ is inferred from~$!B$ is handled similarly.)

standard_text:
\item De laatste inferentie is \Intro{\lor}. Er zijn twee varianten:
  $!A \lor !B$ mag worden afgeleid uit de premisse~$!A$ of uit de
  premisse~$!B$. Beschouw het eerste geval. De !!{derivation} heeft de
  vorm
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A$}
    \RightLabel{\Intro{\lor}}
    \UnaryInfC{$!A \lor !B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A$ uit de !!{undischarged}
  aannamen~$\Gamma$ van~$\delta_1$. Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  We moeten aantonen dat, als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lor !B}$. Veronderstel
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$. Dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$, omdat
  $\Gamma \Entails !A$ (de inductiehypothese). Bijgevolg geldt ook
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lor !B}$. (Het geval waarin
  $!A \lor !B$ uit~$!B$ wordt afgeleid, verloopt op dezelfde wijze.)

ordinary_text:
\item De laatste inferentie is \Intro{\lif}. We leiden $!A \lif !B$
  af uit een deelbewijs met aanname~$!A$ en conclusie~$!B$. Dus:
  \begin{prooftree}
    \AxiomC{$\Gamma, \Discharge{!A}{n}$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!B$}
    \DischargeRule{\Intro{\lif}}{n}
    \UnaryInfC{$!A \lif !B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!B$ uit de !!{undischarged}
  aannamen van~$\delta_1$. Dus $\Gamma \cup \{!A\} \Entails
  !B$. Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  De !!{undischarged} aannamen van~$\delta$ staan alleen in $\Gamma$,
  want de laatste inferentie heft $!A$ op. We moeten dus laten zien
  dat $\Gamma \Entails !A \lif !B$. Neem voor een bewijs via
  tegenspraak aan dat er een
  \iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$},
  is waarvoor $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ maar
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A \lif !B}$. Dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ en
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!B}$. Volgens de hypothese volgt
  $!B$ echter uit $\Gamma \cup \{!A\}$, dus
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. Dat is een tegenspraak. Dus
  $\Gamma \Entails !A \lif !B$.

source_text:
\item The last inference is \Intro{\lif}: $!A \lif !B$ is inferred
  from a subproof with assumption~$!A$ and conclusion~$!B$, i.e.,
  \begin{prooftree}
    \AxiomC{$\Gamma, \Discharge{!A}{n}$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!B$}
    \DischargeRule{\Intro{\lif}}{n}
    \UnaryInfC{$!A \lif !B$}
  \end{prooftree}
  By inductive hypothesis, $!B$ follows from the !!{undischarged}
  assumptions of~$\delta_1$, i.e., $\Gamma \cup \{!A\} \Entails
  !B$. Consider
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}. The
  !!{undischarged} assumptions of~$\delta$ are just $\Gamma$, since
  $!A$ is discharged at the last inference. So we need to show that
  $\Gamma \Entails !A \lif !B$.  For reductio, suppose that for some
  \iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$},
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ but
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A \lif !B}$. So,
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ and
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!B}$. But by hypothesis, $!B$ is a
  consequence of $\Gamma \cup \{!A\}$, i.e.,
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$, which is a contradiction. So,
  $\Gamma \Entails !A \lif !B$.

ordinary_text:
\item De laatste inferentie is \FalseInt. Hier eindigt $\delta$ zo:
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$\lfalse$}
    \RightLabel{\FalseInt}
    \UnaryInfC{$!A$}
  \end{prooftree}
  Volgens de inductiehypothese is $\Gamma \Entails \lfalse$. We
  moeten laten zien dat $\Gamma \Entails !A$. Stel dat dit niet zo is.
  Dan is er een~$\iftag{FOL}{\Struct{M}}{\pAssign{v}}$ waarvoor
    $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ en
    $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A}$. Maar
    $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{\lfalse}$ geldt altijd. Dit zou
    dus betekenen dat $\Gamma \Entails/ \lfalse$, in strijd met de
    inductiehypothese.

source_text:
\item The last inference is \FalseInt: Here, $\delta$ ends in
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$\lfalse$}
    \RightLabel{\FalseInt}
    \UnaryInfC{$!A$}
  \end{prooftree}
  By induction hypothesis, $\Gamma \Entails \lfalse$. We have to show
  that $\Gamma \Entails !A$. Suppose not; then for
  some~$\iftag{FOL}{\Struct{M}}{\pAssign{v}}$ we have
    $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ and
    $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A}$. But we always have
    $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{\lfalse}$, so this would mean
    that $\Gamma \Entails/ \lfalse$, contrary to the induction
    hypothesis.

standard_text:
\item De laatste inferentie is \FalseInt. Hier eindigt $\delta$ op
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$\lfalse$}
    \RightLabel{\FalseInt}
    \UnaryInfC{$!A$}
  \end{prooftree}
  Volgens de inductiehypothese is $\Gamma \Entails \lfalse$. We
  moeten aantonen dat $\Gamma \Entails !A$. Veronderstel dat dit niet
  zo is. Dan geldt voor een zekere
  ~$\iftag{FOL}{\Struct{M}}{\pAssign{v}}$:
    $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ en
    $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A}$. We hebben echter altijd
    $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{\lfalse}$. Dit zou dus
    $\Gamma \Entails/ \lfalse$ betekenen, in strijd met de
    inductiehypothese.

source_text:
\iftag{FOL}{
\item The last inference is \Intro{\lforall}: Then $\delta$ has the form
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A(a)$}
    \RightLabel{\Intro{\lforall}}
    \UnaryInfC{$\lforall[x][!A(x)]$}
  \end{prooftree}
  The premise $!A(a)$ is a consequence of the !!{undischarged}
  assumptions $\Gamma$ by induction hypothesis.  Consider some
  structure, $\Struct{M}$, such that $\Sat{M}{\Gamma}$.  We need to
  show that $\Sat{M}{\lforall[x][!A(x)]}$. Since $\lforall[x][!A(x)]$
  is !!a{sentence}, this means we have to show that for every variable
  assignment~$s$, $\Sat{M}{!A(x)}[s]$
  (\olref[syn][ass]{prop:sat-quant}). Since $\Gamma$ consists entirely
  of sentences, $\Sat{M}{!B}[s]$ for all $!B \in \Gamma$ by
  \olref[syn][sat]{defn:satisfaction}.  Let $\Struct{M'}$ be like
  $\Struct{M}$ except that $\Assign{a}{M'} = s(x)$.  Since $a$ does
  not occur in~$\Gamma$, $\Sat{M'}{\Gamma}$ by
  \olref[syn][ext]{cor:extensionality-sent}. Since $\Gamma \Entails
  !A(a)$, $\Sat{M'}{!A(a)}$.  Since $!A(a)$ is !!a{sentence},
  $\Sat{M'}{!A(a)}[s]$ by
  \olref[syn][ass]{prop:sentence-sat-true}. $\Sat{M'}{!A(x)}[s]$ iff
  $\Sat{M'}{!A(a)}$ by \olref[syn][ext]{prop:ext-formulas} (recall
  that $!A(a)$ is just $\Subst{!A(x)}{a}{x}$). So,
  $\Sat{M'}{!A(x)}[s]$. Since $a$ does not occur in~$!A(x)$, by
  \olref[syn][ext]{prop:extensionality}, $\Sat{M}{!A(x)}[s]$. But $s$
  was an arbitrary variable assignment, so
  $\Sat{M}{\lforall[x][!A(x)]}$.

ordinary_text:
\item De laatste inferentie is \Elim{\forall}. Oefening.
}{}
\end{enumerate}

source_text:
\item The last inference is \Elim{\forall}: Exercise.
}{}
\end{enumerate}

standard_text:
\item De laatste inferentie is \Elim{\forall}. Oefening.
}{}
\end{enumerate}

ordinary_text:
\item De laatste inferentie is \Intro{\land}. We leiden
  $!A \land !B$ af uit de uitgangsformules $!A$ en $!B$.
  $\delta$ heeft deze vorm:
  \begin{prooftree}
    \AxiomC{$\Gamma_1$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A$}
    \AxiomC{$\Gamma_2$}
    \RightLabel{$\delta_2$}
    \DeduceC{$!B$}
    \RightLabel{\Intro{\land}}
    \BinaryInfC{$!A \land !B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A$ uit de !!{undischarged}
  aannamen~$\Gamma_1$ van~$\delta_1$. Ook volgt $!B$ uit de
  !!{undischarged} aannamen~$\Gamma_2$ van~$\delta_2$. De
  !!{undischarged} aannamen van~$\delta$ zijn $\Gamma_1 \cup
  \Gamma_2$. Daarom moeten we laten zien dat
  $\Gamma_1 \cup \Gamma_2 \Entails !A \land !B$. Beschouw
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}
  waarvoor
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$. Uit
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1}$ volgt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$, want
  $\Gamma_1 \Entails !A$. En uit
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_2}$ volgt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$, want
  $\Gamma_2 \Entails !B$. Samen geeft dit
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$.

source_text:
\item The last inference is \Intro{\land}. $!A \land !B$ is inferred
  from the premises $!A$ and $!B$ and $\delta$ has the form
  \begin{prooftree}
    \AxiomC{$\Gamma_1$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A$}
    \AxiomC{$\Gamma_2$}
    \RightLabel{$\delta_2$}
    \DeduceC{$!B$}
    \RightLabel{\Intro{\land}}
    \BinaryInfC{$!A \land !B$}
  \end{prooftree}
  By induction hypothesis, $!A$ follows from the !!{undischarged}
  assumptions~$\Gamma_1$ of~$\delta_1$ and $!B$ follows from the
  !!{undischarged} assumptions~$\Gamma_2$ of~$\delta_2$. The
  !!{undischarged} assumptions of~$\delta$ are $\Gamma_1 \cup
  \Gamma_2$, so we have to show that $\Gamma_1 \cup \Gamma_2 \Entails
  !A \land !B$. Consider
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}
  with $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$. Since
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1}$, it must be the case that
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ as $\Gamma_1 \Entails !A$, and
  since $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_2}$,
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$ since $\Gamma_2 \Entails
  !B$. Together, $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$.

standard_text:
\item De laatste inferentie is \Intro{\land}. $!A \land !B$ wordt
  afgeleid uit de premissen $!A$ en $!B$, en $\delta$ heeft de vorm
  \begin{prooftree}
    \AxiomC{$\Gamma_1$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A$}
    \AxiomC{$\Gamma_2$}
    \RightLabel{$\delta_2$}
    \DeduceC{$!B$}
    \RightLabel{\Intro{\land}}
    \BinaryInfC{$!A \land !B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A$ uit de !!{undischarged}
  aannamen~$\Gamma_1$ van~$\delta_1$, en volgt $!B$ uit de
  !!{undischarged} aannamen~$\Gamma_2$ van~$\delta_2$. De
  !!{undischarged} aannamen van~$\delta$ zijn $\Gamma_1 \cup
  \Gamma_2$. We moeten dus aantonen dat
  $\Gamma_1 \cup \Gamma_2 \Entails !A \land !B$. Beschouw
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}
  waarvoor
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$. Omdat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1}$, moet
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ gelden, aangezien
  $\Gamma_1 \Entails !A$. En omdat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_2}$, geldt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$, aangezien
  $\Gamma_2 \Entails !B$. Samen leveren deze feiten
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \land !B}$ op.

ordinary_text:
\item De laatste inferentie is \Elim{\lif}. We leiden $!B$ af uit de
  uitgangsformules $!A \lif !B$ en~$!A$. De !!{derivation}~$\delta$
  ziet er zo uit:
  \begin{prooftree}
    \AxiomC{$\Gamma_1$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A \lif !B$}
    \AxiomC{$\Gamma_2$}
    \RightLabel{$\delta_2$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lif}}
    \BinaryInfC{$!B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A \lif !B$ uit de
  !!{undischarged} aannamen~$\Gamma_1$ van~$\delta_1$. Ook volgt $!A$
  uit de !!{undischarged} aannamen~$\Gamma_2$ van~$\delta_2$.
  Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  We moeten laten zien: als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. Neem aan dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$. Uit
  $\Gamma_1 \Entails !A \lif !B$ volgt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lif !B}$. Uit
  $\Gamma_2 \Entails !A$ volgt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Dit betekent
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. (Als namelijk
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!B}$, dan zou uit
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ volgen dat
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A \lif !B}$. Dat is in
  tegenspraak met
  ~$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lif !B}$.)

source_text:
\item The last inference is \Elim{\lif}. $!B$ is inferred from the
  premises $!A \lif !B$ and~$!A$. The !!{derivation}~$\delta$ looks like this:
  \begin{prooftree}
    \AxiomC{$\Gamma_1$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A \lif !B$}
    \AxiomC{$\Gamma_2$}
    \RightLabel{$\delta_2$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lif}}
    \BinaryInfC{$!B$}
  \end{prooftree}
  By induction hypothesis, $!A \lif !B$ follows from the
  !!{undischarged} assumptions~$\Gamma_1$ of~$\delta_1$ and $!A$
  follows from the !!{undischarged} assumptions~$\Gamma_2$
  of~$\delta_2$. Consider
  \iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}. We
  need to show that, if $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup
    \Gamma_2}$, then $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. Suppose
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$. Since
  $\Gamma_1 \Entails !A \lif !B$, $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A
    \lif !B}$. Since $\Gamma_2 \Entails !A$, we have
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. This means that
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$ (For if
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!B}$, since
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$, we'd have
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A \lif !B}$,
  contradicting~$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lif !B}$).

standard_text:
\item De laatste inferentie is \Elim{\lif}. $!B$ wordt afgeleid uit
  de premissen $!A \lif !B$ en~$!A$. De !!{derivation}~$\delta$ ziet
  er als volgt uit:
  \begin{prooftree}
    \AxiomC{$\Gamma_1$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A \lif !B$}
    \AxiomC{$\Gamma_2$}
    \RightLabel{$\delta_2$}
    \DeduceC{$!A$}
    \RightLabel{\Elim{\lif}}
    \BinaryInfC{$!B$}
  \end{prooftree}
  Volgens de inductiehypothese volgt $!A \lif !B$ uit de
  !!{undischarged} aannamen~$\Gamma_1$ van~$\delta_1$, en volgt $!A$
  uit de !!{undischarged} aannamen~$\Gamma_2$ van~$\delta_2$.
  Beschouw
\iftag{FOL}{!!a{structure}~$\Struct{M}$}{!!a{valuation}~$\pAssign{v}$}.
  We moeten aantonen dat, als
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$, dan
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$. Veronderstel
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma_1 \cup \Gamma_2}$. Omdat
  $\Gamma_1 \Entails !A \lif !B$, geldt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lif !B}$. Omdat
  $\Gamma_2 \Entails !A$, geldt
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$. Dit betekent dat
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!B}$ (want als
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!B}$, dan zou uit
  $\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$ volgen dat
  $\iftag{FOL}{\Sat/{M}}{\pSat/{v}}{!A \lif !B}$,
  in tegenspraak met
  ~$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A \lif !B}$).

ordinary_text:
\tagitem{FOL}{De laatste inferentie is \Elim{\lexists}. Oefening.}{}
\end{enumerate}
\end{proof}

