ordinary_text:
\begin{prop}[Reflexiviteit: wat is aangenomen, volgt ook]
\ollabel{prop:reflexivity}
Als $!A \in \Gamma$, dan $\Gamma \Proves !A$.
\end{prop}

source_text:
\begin{prop}[Reflexivity]
\ollabel{prop:reflexivity}
If $!A \in \Gamma$, then $\Gamma \Proves !A$.
\end{prop}

standard_text:
\begin{prop}[Reflexiviteit]
\ollabel{prop:reflexivity}
Als $!A \in \Gamma$, dan $\Gamma \Proves !A$.
\end{prop}

ordinary_text:
\begin{proof}
Als $!A \in \Gamma$, is $\{!A\}$ een eindige deelverzameling
van~$\Gamma$. Het volgende !!{tableau}
\begin{oltableau}
  [\sFmla{\False}{\formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A}}, just = \TAss,close]
  ]
\end{oltableau}
is gesloten.
\end{proof}

source_text:
\begin{proof}
If $!A \in \Gamma$, $\{!A\}$ is a finite subset of~$\Gamma$ and the !!{tableau}
\begin{oltableau}
  [\sFmla{\False}{\formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A}}, just = \TAss,close]
  ]
\end{oltableau}
is closed.
\end{proof}

standard_text:
\begin{proof}
Als $!A \in \Gamma$, dan is $\{!A\}$ een eindige deelverzameling
van~$\Gamma$ en is het !!{tableau}
\begin{oltableau}
  [\sFmla{\False}{\formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A}}, just = \TAss,close]
  ]
\end{oltableau}
gesloten.
\end{proof}

ordinary_text:
\begin{prop}[Monotoniciteit: extra aannamen mogen erbij]
\ollabel{prop:monotonicity}
Als $\Gamma \subseteq \Delta$ en $\Gamma \Proves !A$, dan $\Delta
\Proves !A$.
\end{prop}

source_text:
\begin{prop}[Monotonicity]
\ollabel{prop:monotonicity}
If $\Gamma \subseteq \Delta$ and $\Gamma \Proves !A$, then $\Delta
\Proves !A$.
\end{prop}

standard_text:
\begin{prop}[Monotoniciteit]
\ollabel{prop:monotonicity}
Als $\Gamma \subseteq \Delta$ en $\Gamma \Proves !A$, dan $\Delta
\Proves !A$.
\end{prop}

ordinary_text:
\begin{proof}
Elke eindige deelverzameling van~$\Gamma$ is ook een eindige
deelverzameling van~$\Delta$.
\end{proof}

source_text:
\begin{proof}
Any finite subset of~$\Gamma$ is also a finite subset of~$\Delta$.
\end{proof}

standard_text:
\begin{proof}
Elke eindige deelverzameling van~$\Gamma$ is ook een eindige
deelverzameling van~$\Delta$.
\end{proof}

ordinary_text:
\begin{prop}[Transitiviteit: afleidingen achter elkaar zetten]
\ollabel{prop:transitivity}
Als $\Gamma \Proves !A$ en $\{!A\} \cup
\Delta \Proves !B$, dan $\Gamma \cup \Delta \Proves !B$.
\end{prop}

source_text:
\begin{prop}[Transitivity]
\ollabel{prop:transitivity}
If $\Gamma \Proves !A$ and $\{!A\} \cup
\Delta \Proves !B$, then $\Gamma \cup \Delta \Proves !B$.
\end{prop}

standard_text:
\begin{prop}[Transitiviteit]
\ollabel{prop:transitivity}
Als $\Gamma \Proves !A$ en $\{!A\} \cup
\Delta \Proves !B$, dan $\Gamma \cup \Delta \Proves !B$.
\end{prop}

ordinary_text:
\begin{proof}
Stel dat $\{!A\} \cup \Delta \Proves !B$. Dan is er een eindige
deelverzameling $\Delta_0 =
\{!C_1, \dots, !C_n\} \subseteq \Delta$ waarvoor
\begin{align*}
\{\sFmla{\False}{!B}, & \sFmla{\True}{!A}, \sFmla{\True}{!C_1},
\dots, \sFmla{\True}{!C_n}\}
\intertext{een gesloten !!{tableau} bestaat. Stel nu dat
  $\Gamma \Proves !A$. Dan zijn er $!D_1$, \dots,
  $!D_m \subseteq \Gamma$ waarvoor}
\{\sFmla{\False}{!A}, & \sFmla{\True}{!D_1},
\dots, \sFmla{\True}{!D_m}\}
\end{align*}
een gesloten !!{tableau} bestaat.

source_text:
\begin{proof}
If $\{!A\} \cup \Delta \Proves !B$, then there is a finite subset $\Delta_0 =
\{!C_1, \dots, !C_n\} \subseteq \Delta$ such that
\begin{align*}
\{\sFmla{\False}{!B}, & \sFmla{\True}{!A}, \sFmla{\True}{!C_1},
\dots, \sFmla{\True}{!C_n}\}
\intertext{has a closed !!{tableau}. If $\Gamma \Proves !A$ then there
  are $!D_1$, \dots, $!D_m \subseteq \Gamma$ such that}
\{\sFmla{\False}{!A}, & \sFmla{\True}{!D_1},
\dots, \sFmla{\True}{!D_m}\}
\end{align*}
has a closed !!{tableau}.

standard_text:
\begin{proof}
Als $\{!A\} \cup \Delta \Proves !B$, dan is er een eindige
deelverzameling $\Delta_0 =
\{!C_1, \dots, !C_n\} \subseteq \Delta$ zodat
\begin{align*}
\{\sFmla{\False}{!B}, & \sFmla{\True}{!A}, \sFmla{\True}{!C_1},
\dots, \sFmla{\True}{!C_n}\}
\intertext{een gesloten !!{tableau} heeft. Als $\Gamma \Proves !A$,
  dan zijn er $!D_1$, \dots, $!D_m \subseteq \Gamma$ zodat}
\{\sFmla{\False}{!A}, & \sFmla{\True}{!D_1},
\dots, \sFmla{\True}{!D_m}\}
\end{align*}
een gesloten !!{tableau} heeft.

