ordinary_text:
\begin{defn}[Axioma's voor kwantoren]
De \emph{axioma's} voor kwantoren, de tekens voor `voor alle' en `er
bestaat', zijn alle invullingen van de volgende twee vormen:
\begin{align}
\ollabel{ax:q1} & \lforall[x][!B] \lif !B(t), \\
\ollabel{ax:q2} & !B(t) \lif \lexists[x][!B].
\end{align}
Hierbij mag $t$ elke gesloten term zijn, dus elke term zonder
variabelen.
\end{defn}

source_text:
\begin{defn}[Axioms for quantifiers]
The \emph{axioms} governing quantifiers are
all instances of the following:
\begin{align}
\ollabel{ax:q1} & \lforall[x][!B] \lif !B(t), \\
\ollabel{ax:q2} & !B(t) \lif \lexists[x][!B].
\end{align}
for any closed term~$t$.
\end{defn}

standard_text:
\begin{defn}[Axioma's voor kwantoren]
De \emph{axioma's} voor kwantoren zijn alle instanties van de volgende
schema's:
\begin{align}
\ollabel{ax:q1} & \lforall[x][!B] \lif !B(t), \\
\ollabel{ax:q2} & !B(t) \lif \lexists[x][!B].
\end{align}
voor elke gesloten term~$t$.
\end{defn}

