source_text:
\begin{ex}
Let us give !!a{derivation} of $(\lforall[x][!A(x)] \land
\lforall[y][!B(y)]) \lif \lforall[x][(!A(x) \land !B(x))]$.

standard_text:
\begin{ex}
Laten we !!a{derivation} geven van $(\lforall[x][!A(x)] \land
\lforall[y][!B(y)]) \lif \lforall[x][(!A(x) \land !B(x))]$.

ordinary_text:
Kijk eerst naar
\begin{align*}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[x][!A(x)]\\
  \intertext{Dit is een invulling van \olref[prp]{ax:land1}. Verder is}
  \lforall[x][!A(x)] & \lif !A(a) \\
  \intertext{een invulling van \olref[qua]{ax:q1}. Volgens \olref[pro]{prop:chain} is daarom}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif !A(a) \\
  \intertext{!!{derivable}. Dezelfde stappen werken voor $!B$. Eerst hebben we}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[y][!B(y)] \qquad\text{and}\\
    \lforall[y][!B(y)] & \lif !B(a)\\
    \intertext{In die volgorde zijn dit invullingen van \olref[prp]{ax:land2} en \olref[qua]{ax:q1}. Daarom is}
    (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif !B(a)\\
    \intertext{volgens \olref[pro]{prop:chain} af te leiden. Neem nu een passende invulling van \olref[prp]{ax:land3} en pas~\MP twee keer toe. Dan krijgen we}
    (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif (!A(a) \land !B(a))\\
    \intertext{Ook dit is af te leiden. Pas nu \QR{} toe. Dat geeft}
(\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[x][(!A(x) \land !B(x))].
\end{align*}
\end{ex}

source_text:
First, note that
\begin{align*}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[x][!A(x)]\\
  \intertext{is an instance of \olref[prp]{ax:land1}, and}
  \lforall[x][!A(x)] & \lif !A(a) \\
  \intertext{of \olref[qua]{ax:q1}. So, by \olref[pro]{prop:chain}, we know that}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif !A(a) \\
  \intertext{is !!{derivable}. Likewise, since}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[y][!B(y)] \qquad\text{and}\\
    \lforall[y][!B(y)] & \lif !B(a)\\
    \intertext{are instances of \olref[prp]{ax:land2} and \olref[qua]{ax:q1}, respectively,}
    (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif !B(a)\\
    \intertext{is derivable by \olref[pro]{prop:chain}. Using an appropriate instance of \olref[prp]{ax:land3} and two applications of~\MP, we see that}
    (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif (!A(a) \land !B(a))\\
    \intertext{is derivable. We can now apply \QR{} to obtain}
(\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[x][(!A(x) \land !B(x))].
\end{align*}
\end{ex}

standard_text:
Merk eerst op dat
\begin{align*}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[x][!A(x)]\\
  \intertext{een instantie is van \olref[prp]{ax:land1}, en dat}
  \lforall[x][!A(x)] & \lif !A(a) \\
  \intertext{een instantie is van \olref[qua]{ax:q1}. Uit \olref[pro]{prop:chain} weten we dus dat}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif !A(a) \\
  \intertext{!!{derivable} is. Evenzo geldt dat}
  (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[y][!B(y)] \qquad\text{and}\\
    \lforall[y][!B(y)] & \lif !B(a)\\
    \intertext{respectievelijk instanties zijn van \olref[prp]{ax:land2} en \olref[qua]{ax:q1}, zodat}
    (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif !B(a)\\
    \intertext{volgens \olref[pro]{prop:chain} afleidbaar is. Met een passende instantie van \olref[prp]{ax:land3} en twee toepassingen van~\MP zien we dat}
    (\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif (!A(a) \land !B(a))\\
    \intertext{afleidbaar is. We kunnen nu \QR{} toepassen en verkrijgen}
(\lforall[x][!A(x)] \land \lforall[y][!B(y)]) & \lif \lforall[x][(!A(x) \land !B(x))].
\end{align*}
\end{ex}

