ordinary_text:
\begin{prop}[Compactheid: eindige delen zijn genoeg]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item Als $\Gamma \Proves !A$, dan is er een eindige
    deelverzameling $\Gamma_0 \subseteq \Gamma$ waarvoor
    $\Gamma_0 \Proves !A$.
  \item Als elke eindige deelverzameling van~$\Gamma$ consistent is,
    dan is $\Gamma$ zelf consistent.
  \end{enumerate}
\end{prop}

source_text:
\begin{prop}[Compactness]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

standard_text:
\begin{prop}[Compactheid]
\ollabel{prop:proves-compact}
  \begin{enumerate}
  \item Als $\Gamma \Proves !A$, dan bestaat er een eindige
    deelverzameling $\Gamma_0 \subseteq \Gamma$ waarvoor
    $\Gamma_0 \Proves !A$.
  \item Als elke eindige deelverzameling van~$\Gamma$ consistent is,
    dan is $\Gamma$ consistent.
  \end{enumerate}
\end{prop}

source_text:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite sequence of
      !!{formula}s $!A_1$, \dots,~$!A_n$ so that $!A \ident !A_n$ and
      each $!A_i$ is either a logical axiom, !!a{element} of~$\Gamma$
      or follows from previous !!{formula}s by modus ponens.  Take
      $\Gamma_0$ to be those $!A_i$ which are in~$\Gamma$.  Then the
      !!{derivation} is likewise !!a{derivation} from~$\Gamma_0$, and
      so $\Gamma_0 \Proves !A$.
    \item This is the contrapositive of~(1) for the special case $!A
      \ident \lfalse$.
\end{enumerate}
\end{proof}

standard_text:
\begin{proof}
  \begin{enumerate}
    \item Als $\Gamma \Proves !A$, bestaat er een eindige rij
      !!{formula}s $!A_1$, \dots,~$!A_n$ waarvoor $!A \ident !A_n$,
      waarbij elke $!A_i$ ofwel een logisch axioma, ofwel !!a{element}
      van~$\Gamma$ is, ofwel door modus ponens uit eerdere
      !!{formula}s volgt. Laat $\Gamma_0$ bestaan uit die $!A_i$ die
      tot~$\Gamma$ behoren. De !!{derivation} is dan tevens
      !!a{derivation} uit~$\Gamma_0$, en dus $\Gamma_0 \Proves !A$.
    \item Dit is de contrapositie van~(1) voor het bijzondere geval
      $!A \ident \lfalse$.
\end{enumerate}
\end{proof}

