ordinary_text:
\begin{prop}
  \ollabel{prop:mp} Als $\Gamma \Proves !A$ en $\Gamma \Proves !A \lif
  !B$, dan $\Gamma \Proves !B$.
\end{prop}

source_text:
\begin{prop}
  \ollabel{prop:mp} If $\Gamma \Proves !A$ and $\Gamma \Proves !A \lif
  !B$, then $\Gamma \Proves !B$.
\end{prop}

standard_text:
\begin{prop}
  \ollabel{prop:mp} Als $\Gamma \Proves !A$ en $\Gamma \Proves !A \lif
  !B$, dan $\Gamma \Proves !B$.
\end{prop}

ordinary_text:
\begin{proof}
  De volgende drie regels laten zien dat $\{!A, !A \lif !B\} \Proves
  !B$:
  \begin{derivation}
    1. & $!A$ & Aanname\\
    2. & $!A \lif !B$ & Aanname\\
    3. & $!B$ & 1, 2, MP
  \end{derivation}
  Met \olref[ptn]{prop:transitivity} krijgen we dan $\Gamma \Proves
  !B$.
\end{proof}

source_text:
\begin{proof}
  We have that $\{!A, !A \lif !B\} \Proves !B$:
  \begin{derivation}
    1. & $!A$ & Hyp.\\
    2. & $!A \lif !B$ & Hyp.\\
    3. & $!B$ & 1, 2, MP
  \end{derivation}
  By \olref[ptn]{prop:transitivity}, $\Gamma \Proves !B$.
\end{proof}

standard_text:
\begin{proof}
  Er geldt $\{!A, !A \lif !B\} \Proves !B$:
  \begin{derivation}
    1. & $!A$ & Aanname\\
    2. & $!A \lif !B$ & Aanname\\
    3. & $!B$ & 1, 2, MP
  \end{derivation}
  Volgens \olref[ptn]{prop:transitivity} geldt $\Gamma \Proves !B$.
\end{proof}

ordinary_text:
\begin{proof}
De richting ``als'' is direct. Neem aan dat $\Gamma \Proves !A \lif
!B$. Volgens \olref[ptn]{prop:monotonicity} mogen we de extra aanname
toevoegen en krijgen we $\Gamma \cup \{!A\} \Proves !A \lif !B$.
Volgens \olref[ptn]{prop:reflexivity} geldt ook $\Gamma \cup \{!A\}
\Proves !A$. Met \olref{prop:mp} krijgen we dus $\Gamma \cup \{!A\}
\Proves !B$.

\begin{prop}
  \ollabel{prop:derivfacts}
\begin{enumerate}
\item $\Proves (!A \lif !B) \lif ((!B \lif !C)
  \lif (!A \lif !C)$; \ollabel{derivfacts:a}
\item Als $\Gamma \cup \{ \lnot !A\}
  \Proves \lnot !B$, dan $\Gamma \cup \{ !B\} \Proves
  !A$ (contrapositie: keer de richting om en ontken beide kanten);
  \ollabel{derivfacts:b}
\item  $\{ !A, \lnot!A\} \Proves
    !B$ (ex falso quodlibet, ofwel explosie: uit een tegenspraak volgt
    elke formule); \ollabel{derivfacts:c}
\item  $\{ \lnot\lnot!A\} \Proves
  !A$ (eliminatie van dubbele negatie: verwijder de twee negaties);
  \ollabel{derivfacts:d}
\item Als $\Gamma \Proves \lnot\lnot!A$, dan $\Gamma \Proves
  !A$;\ollabel{derivfacts:e}
\end{enumerate}
\end{prop}

source_text:
\begin{prop}
  \ollabel{prop:derivfacts}
\begin{enumerate}
\item $\Proves (!A \lif !B) \lif ((!B \lif !C)
  \lif (!A \lif !C)$; \ollabel{derivfacts:a}
\item If $\Gamma \cup \{ \lnot !A\}
  \Proves \lnot !B$ then $\Gamma \cup \{ !B\} \Proves
  !A$ (Contraposition); \ollabel{derivfacts:b}
\item  $\{ !A, \lnot!A\} \Proves
    !B$ (Ex Falso Quodlibet, Explosion); \ollabel{derivfacts:c}
\item  $\{ \lnot\lnot!A\} \Proves
  !A$ (Double Negation Elimination);\ollabel{derivfacts:d}
\item If $\Gamma \Proves \lnot\lnot!A$ then $\Gamma \Proves
  !A$;\ollabel{derivfacts:e}
\end{enumerate}
\end{prop}

