\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item De formules $!A \lor !B, \lnot !A, \lnot !B$ zijn samen
    inconsistent.
  \item Er gelden twee gevolgtrekkingen: zowel
    $!A \Proves !A \lor !B$ als $!B \Proves !A \lor !B$.
  \end{enumerate}
\end{prop}

