\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ is inconsistent.
  \item Both $!A \Proves !A \lor !B$ and $!B \Proves !A \lor !B$.
  \end{enumerate}
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:provability-lor}
  \begin{enumerate}
  \item $!A \lor !B, \lnot !A, \lnot !B$ is inconsistent.
  \item Zowel $!A \Proves !A \lor !B$ als $!B \Proves !A \lor !B$.
  \end{enumerate}
\end{prop}

source_text:
\begin{proof}
  \begin{enumerate}
  \item From \olref[prp]{ax:lnot1} we get $\Proves \lnot !A \lif (!A
    \lif \lfalse)$ and $\Proves \lnot !B \lif (!B \lif \lfalse)$. So
    by the deduction theorem, we have $\{\lnot !A\} \Proves !A \lif
    \lfalse$ and $\{\lnot !B\} \Proves !B \lif \lfalse$. From
    \olref[prp]{ax:lor3} we get $\{\lnot !A, \lnot !B\} \Proves (!A
    \lor !B) \lif \lfalse$. By the deduction theorem, $\{!A \lor !B,
    \lnot !A, \lnot !B\} \Proves \lfalse$.
  \item From \olref[prp]{ax:lor1} and \olref[prp]{ax:lor2} by modus
    ponsens.
  \end{enumerate}
\end{proof}

standard_text:
\begin{proof}
  \begin{enumerate}
  \item Uit \olref[prp]{ax:lnot1} volgen $\Proves \lnot !A \lif (!A
    \lif \lfalse)$ en $\Proves \lnot !B \lif (!B \lif \lfalse)$.
    Volgens de deductiestelling hebben we dus $\{\lnot !A\} \Proves
    !A \lif \lfalse$ en $\{\lnot !B\} \Proves !B \lif \lfalse$. Uit
    \olref[prp]{ax:lor3} volgt $\{\lnot !A, \lnot !B\} \Proves (!A
    \lor !B) \lif \lfalse$. Volgens de deductiestelling geldt
    $\{!A \lor !B, \lnot !A, \lnot !B\} \Proves \lfalse$.
  \item Uit \olref[prp]{ax:lor1} en \olref[prp]{ax:lor2} met modus
    ponens.
  \end{enumerate}
\end{proof}

