\ollabel{prop:ccs}
Veronderstel dat $\Gamma$ !!{complete} en consistent is. Dan geldt:
\begin{enumerate}
\item \ollabel{prop:ccs-prov-in} Als $\Gamma \Proves !A$, dan $!A \in
  \Gamma$.

ordinary_text:
\tagitem{prvIf}{\ollabel{prop:ccs-if} $!A \lif !B \in \Gamma$ precies
  als $!A \notin \Gamma$ of $!B \in \Gamma$.}{}
\end{enumerate}
\end{prop}

