\tagitem{prvIf}{\ollabel{prop:ccs-if} $!A \lif !B \in \Gamma$ dan en
  slechts dan als $!A \notin \Gamma$ of $!B \in \Gamma$.}{}
\end{enumerate}
\end{prop}

