ordinary_text:
\begin{explain}
Een lastig deel van het volledigheidsbewijs is dit: het model dat we uit
een volledige consistente verzameling~$\Gamma$ bouwen, moet alle
gekwantificeerde !!{formula}s in~$\Gamma$ waar maken. Een truc van Leon
Henkin zorgt daarvoor. We breiden eerst de taal uit met oneindig veel
nieuwe !!{constant}s. Daarna voegen we voor elke !!{formula} met één
vrije !!{variable} $!A(x)$ een formule toe van de vorm
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c)$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c)$},
waarbij $c$ een van de nieuwe !!{constant}s is. Later bouwen we de
!!{structure} die~$\Gamma$ waar maakt. De toegevoegde formules zorgen er
dan voor dat elke
\iftag{prvEx}
{ware existentiële zin een getuige heeft}
{onware universele zin een tegenvoorbeeld heeft}
onder de nieuwe constanten.
\end{explain}

source_text:
\begin{explain}
Part of the challenge in proving the completeness theorem is that the
model we construct from a complete consistent set~$\Gamma$ must make
all the quantified !!{formula}s in~$\Gamma$ true.  In order to
guarantee this, we use a trick due to Leon Henkin.  In essence, the
trick consists in expanding the language by infinitely many !!{constant}s
and adding, for each !!{formula} with one free !!{variable} $!A(x)$ a
formula of the form
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c)$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c)$},
where $c$ is one of the new !!{constant}s.  When we construct the
!!{structure} satisfying~$\Gamma$, this will guarantee that each
\iftag{prvEx}
{true existential sentence has a witness}
{false universal sentence has a counterexample}
among the new constants.
\end{explain}

standard_text:
\begin{explain}
Een deel van de moeilijkheid bij het bewijzen van de volledigheidsstelling
is dat het model dat we uit een volledige consistente verzameling~$\Gamma$
construeren, alle gekwantificeerde !!{formula}s in~$\Gamma$ waar moet
maken. Om dit te garanderen gebruiken we een kunstgreep van Leon Henkin.
Deze kunstgreep komt er in wezen op neer dat we de taal uitbreiden met
oneindig veel !!{constant}s en voor elke !!{formula} met één vrije
!!{variable} $!A(x)$ een formule toevoegen van de vorm
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c)$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c)$},
waarbij $c$ een van de nieuwe !!{constant}s is. Wanneer we de
!!{structure} construeren die~$\Gamma$ vervult, garandeert dit dat elke
\iftag{prvEx}
{ware existentiële zin een getuige heeft}
{onware universele zin een tegenvoorbeeld heeft}
onder de nieuwe constanten.
\end{explain}

ordinary_text:
\begin{prop}
\ollabel{prop:lang-exp}
Stel dat $\Gamma$ consistent is in $\Lang L$. Stel ook dat we $\Lang L'$
uit $\Lang L$ maken door !!a{denumerable} verzameling nieuwe
!!{constant}s $\Obj d_0$, $\Obj d_1$, \dots toe te voegen. Dan blijft
$\Gamma$ consistent in~$\Lang L'$.
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:lang-exp}
If $\Gamma$ is consistent in $\Lang L$ and $\Lang L'$ is obtained from
$\Lang L$ by adding !!a{denumerable} set of new !!{constant}s $\Obj d_0$,
$\Obj d_1$, \dots, then $\Gamma$ is consistent in~$\Lang L'$.
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:lang-exp}
Als $\Gamma$ consistent is in $\Lang L$ en $\Lang L'$ uit $\Lang L$
wordt verkregen door !!a{denumerable} verzameling nieuwe
!!{constant}s $\Obj d_0$, $\Obj d_1$, \dots toe te voegen, dan is
$\Gamma$ consistent in~$\Lang L'$.
\end{prop}

ordinary_text:
\begin{defn}[Verzadigde verzameling]
Een verzameling $\Gamma$ van !!{formula}s van een taal $\Lang {L}$ heet
\emph{verzadigd} precies als aan de volgende voorwaarde is voldaan. Neem
een willekeurige !!{formula}~$!A(x) \in \Frm[L]$ met één vrije
!!{variable}~$x$. Er moet dan een !!{constant}~$c \in \Lang{L}$ zijn
waarvoor
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c) \in \Gamma$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c) \in \Gamma$}.
\end{defn}

source_text:
\begin{defn}[Saturated set]
A set $\Gamma$ of !!{formula}s of a language $\Lang {L}$ is
\emph{saturated} iff for each !!{formula}~$!A(x) \in \Frm[L]$ with one
free !!{variable}~$x$ there is !!a{constant}~$c \in \Lang{L}$ such
that
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c) \in \Gamma$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c) \in \Gamma$}.
\end{defn}

standard_text:
\begin{defn}[Verzadigde verzameling]
Een verzameling $\Gamma$ van !!{formula}s van een taal $\Lang {L}$ is
\emph{verzadigd} dan en slechts dan als er voor elke
!!{formula}~$!A(x) \in \Frm[L]$ met één vrije !!{variable}~$x$ een
!!{constant}~$c \in \Lang{L}$ bestaat waarvoor
\iftag{prvEx}
      {$\lexists[x][!A(x)] \lif !A(c) \in \Gamma$}
      {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c) \in \Gamma$}.
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:henkin-exp}
Let $\Lang L'$ be as in \olref{prop:lang-exp}.  Fix an enumeration
$!A_0(x_0)$, $!A_1(x_1)$, \dots of all !!{formula}s~$!A_i(x_i)$
of~$\Lang L'$ in which one variable ($x_i$) occurs free.  We define
the !!{sentence}s~$!D_n$ by induction on~$n$.

standard_text:
\begin{defn}
\ollabel{defn:henkin-exp}
Laat $\Lang L'$ zijn zoals in \olref{prop:lang-exp}. Kies een opsomming
$!A_0(x_0)$, $!A_1(x_1)$, \dots van alle !!{formula}s~$!A_i(x_i)$
van~$\Lang L'$ waarin één variabele ($x_i$) vrij voorkomt. We definiëren
de !!{sentence}s~$!D_n$ door inductie naar~$n$.

ordinary_text:
Definieer $!D_{n}$ als de volgende !!{formula}: \iftag{prvEx}
{$\lexists[x_{n}][!A_{n}(x_{n})] \lif
  !A_{n}(c_{n})$}{$\lnot\lforall[x_{n}][!A_{n}(x_{n})] \lif \lnot
  !A_{n}(c_{n})$}.
\end{defn}

source_text:
Now let $!D_{n}$ be the !!{formula} \iftag{prvEx}
{$\lexists[x_{n}][!A_{n}(x_{n})] \lif
  !A_{n}(c_{n})$}{$\lnot\lforall[x_{n}][!A_{n}(x_{n})] \lif \lnot
  !A_{n}(c_{n})$}.
\end{defn}

standard_text:
Laat nu $!D_{n}$ de volgende !!{formula} zijn: \iftag{prvEx}
{$\lexists[x_{n}][!A_{n}(x_{n})] \lif
  !A_{n}(c_{n})$}{$\lnot\lforall[x_{n}][!A_{n}(x_{n})] \lif \lnot
  !A_{n}(c_{n})$}.
\end{defn}

ordinary_text:
\begin{lem}
\ollabel{lem:henkin}
Elke consistente verzameling~$\Gamma$ past in een grotere verzameling
$\Gamma'$ die zowel verzadigd als consistent is.
\end{lem}

source_text:
\begin{lem}
\ollabel{lem:henkin}
Every consistent set~$\Gamma$ can be extended to a saturated
consistent set~$\Gamma'$.
\end{lem}

standard_text:
\begin{lem}
\ollabel{lem:henkin}
Elke consistente verzameling~$\Gamma$ kan worden uitgebreid tot een
verzadigde consistente verzameling~$\Gamma'$.
\end{lem}

ordinary_text:
\begin{proof}
Begin met een consistente verzameling zinnen~$\Gamma$ in een
taal~$\Lang{L}$. Voeg !!a{denumerable} verzameling nieuwe !!{constant}s
aan de taal toe. Zo krijgen we~$\Lang{L'}$. Volgens
\olref{prop:lang-exp} blijft $\Gamma$ consistent in deze ruimere taal.
Neem verder de formules $!D_i$ uit \olref{defn:henkin-exp}. Definieer
\begin{align*}
\Gamma_0 & = \Gamma \\
\Gamma_{n+1} & = \Gamma_n \cup \{!D_n \}
\end{align*}
Dus $\Gamma_{n+1} = \Gamma \cup \{ !D_0, \dots, !D_n \}$. Definieer
ook $\Gamma' = \bigcup_{n} \Gamma_n$. Door de manier waarop we de
formules hebben toegevoegd, is $\Gamma'$ verzadigd.

source_text:
\begin{proof}
Given a consistent set of sentences~$\Gamma$ in a language~$\Lang{L}$,
expand the language by adding !!a{denumerable} set of new
!!{constant}s to form~$\Lang{L'}$.  By \olref{prop:lang-exp}, $\Gamma$
is still consistent in the richer language.  Further, let $!D_i$ be as
in \olref{defn:henkin-exp}.  Let
\begin{align*}
\Gamma_0 & = \Gamma \\
\Gamma_{n+1} & = \Gamma_n \cup \{!D_n \}
\end{align*}
i.e., $\Gamma_{n+1} = \Gamma \cup \{ !D_0, \dots, !D_n \}$, and let
$\Gamma' = \bigcup_{n} \Gamma_n$.  $\Gamma'$ is clearly saturated.

standard_text:
\begin{proof}
Neem een consistente verzameling zinnen~$\Gamma$ in een taal~$\Lang{L}$.
Breid de taal uit tot~$\Lang{L'}$ door !!a{denumerable} verzameling
nieuwe !!{constant}s toe te voegen. Volgens \olref{prop:lang-exp} blijft
$\Gamma$ consistent in de rijkere taal. Laat verder $!D_i$ zijn zoals
in \olref{defn:henkin-exp}. Definieer
\begin{align*}
\Gamma_0 & = \Gamma \\
\Gamma_{n+1} & = \Gamma_n \cup \{!D_n \}
\end{align*}
dat wil zeggen, $\Gamma_{n+1} = \Gamma \cup \{ !D_0, \dots, !D_n \}$,
en stel $\Gamma' = \bigcup_{n} \Gamma_n$. Dan is $\Gamma'$ kennelijk
verzadigd.

ordinary_text:
Als $\Gamma_n \cup \{!D_n\}$ inconsistent is, dan $\Gamma_n
\Proves \lnot !D_n$. Daaruit volgen de twee beweringen hieronder:
\iftag{prvEx}{
\[
\Gamma_n \Proves \lexists[x_n][!A_n(x_n)]
\qquad
\Gamma_n \Proves \lnot !A_n(c_n)
\]}{
\[
\Gamma_n \Proves \lnot\lforall[x_n][!A_n(x_n)]
\qquad
\Gamma_n \Proves !A_n(c_n)
\]}
De constante $c_n$ komt niet voor in
$\Gamma_n$ of in~$!A_n(x_n)$. Daarom mogen we
\tagrefs{prfAX/{fol:axd:qpr:thm:strong-generalization},prfSC/{fol:seq:qpr:thm:strong-generalization},prfND/{fol:ntd:qpr:thm:strong-generalization},prfTab/{fol:tab:qpr:thm:strong-generalization}}
toepassen. Uit \iftag{prvEx}
{$\Gamma_n \Proves \lnot !A_n(c_n)$}
{$\Gamma_n \Proves !A_n(c_n)$}
volgt dan
\iftag{prvEx}
{$\Gamma_n \Proves \lforall[x_n][\lnot !A_n(x_n)]$}
{$\Gamma_n \Proves \lforall[x_n][!A_n(x_n)]$}.
We hebben dus zowel
\iftag{prvEx}
{$\Gamma_n \Proves \lexists[x_n][!A_n(x_n)]$ als
$\Gamma_n \Proves \lforall[x_n][\lnot !A_n(x_n)]$}
{$\Gamma_n \Proves \lnot\lforall[x_n][!A_n(x_n)]$ als
$\Gamma_n \Proves \lforall[x_n][!A_n(x_n)]$}.
Daarmee is $\Gamma_n$ zelf inconsistent.
\iftag{prvEx}
{(Merk op dat
\iftag{prvAll}
{$\lforall[x_n][\lnot !A_n(x_n)] \Proves
  \lnot\lexists[x_n][!A_n(x_n)]$}
{$\lforall[x_n][\lnot !A_n]$ per definitie gelijk is aan
  $\lnot\lexists[x_n][\lnot\lnot !A_n(x_n)]$ en dat
  $\lnot\lexists[x_n][\lnot\lnot !A_n(x_n)] \Proves
  \lnot\lexists[x_n][!A_n(x_n)]$}.)}{}
Dat is een tegenspraak: we hadden aangenomen dat $\Gamma_n$ consistent
was. Dus is $\Gamma_n \cup \{ !D_n\}$ consistent.
\end{proof}

source_text:
If $\Gamma_n \cup \{!D_n\}$ is inconsistent, then $\Gamma_n
\Proves \lnot !D_n$, and hence both of the following hold:
\iftag{prvEx}{
\[
\Gamma_n \Proves \lexists[x_n][!A_n(x_n)]
\qquad
\Gamma_n \Proves \lnot !A_n(c_n)
\]}{
\[
\Gamma_n \Proves \lnot\lforall[x_n][!A_n(x_n)]
\qquad
\Gamma_n \Proves !A_n(c_n)
\]}
Since $c_n$ does not occur in
$\Gamma_n$ or in~$!A_n(x_n)$, 
\tagrefs{prfAX/{fol:axd:qpr:thm:strong-generalization},prfSC/{fol:seq:qpr:thm:strong-generalization},prfND/{fol:ntd:qpr:thm:strong-generalization},prfTab/{fol:tab:qpr:thm:strong-generalization}} applies.
From \iftag{prvEx}
{$\Gamma_n \Proves \lnot !A_n(c_n)$}
{$\Gamma_n \Proves !A_n(c_n)$},
we obtain
\iftag{prvEx}
{$\Gamma_n \Proves \lforall[x_n][\lnot !A_n(x_n)]$}
{$\Gamma_n \Proves \lforall[x_n][!A_n(x_n)]$}.
Thus we have that both
\iftag{prvEx}
{$\Gamma_n \Proves \lexists[x_n][!A_n(x_n)]$ and
$\Gamma_n \Proves \lforall[x_n][\lnot !A_n(x_n)]$}
{$\Gamma_n \Proves \lnot\lforall[x_n][!A_n(x_n)]$ and
$\Gamma_n \Proves \lforall[x_n][!A_n(x_n)]$},
so $\Gamma_n$ itself is inconsistent.
\iftag{prvEx}
{(Note that
\iftag{prvAll}
{$\lforall[x_n][\lnot !A_n(x_n)] \Proves
  \lnot\lexists[x_n][!A_n(x_n)]$}
{$\lforall[x_n][\lnot !A_n]$ is defined as
  $\lnot\lexists[x_n][\lnot\lnot !A_n(x_n)]$ and
  $\lnot\lexists[x_n][\lnot\lnot !A_n(x_n)] \Proves
  \lnot\lexists[x_n][!A_n(x_n)]$}.)}{}
Contradiction: $\Gamma_n$ was supposed to be consistent.  Hence
$\Gamma_n \cup \{ !D_n\}$ is consistent.
\end{proof}

standard_text:
Als $\Gamma_n \cup \{!D_n\}$ inconsistent is, dan $\Gamma_n
\Proves \lnot !D_n$, en dus gelden beide volgende beweringen:
\iftag{prvEx}{
\[
\Gamma_n \Proves \lexists[x_n][!A_n(x_n)]
\qquad
\Gamma_n \Proves \lnot !A_n(c_n)
\]}{
\[
\Gamma_n \Proves \lnot\lforall[x_n][!A_n(x_n)]
\qquad
\Gamma_n \Proves !A_n(c_n)
\]}
Omdat $c_n$ niet voorkomt in
$\Gamma_n$ of in~$!A_n(x_n)$, is
\tagrefs{prfAX/{fol:axd:qpr:thm:strong-generalization},prfSC/{fol:seq:qpr:thm:strong-generalization},prfND/{fol:ntd:qpr:thm:strong-generalization},prfTab/{fol:tab:qpr:thm:strong-generalization}}
van toepassing. Uit \iftag{prvEx}
{$\Gamma_n \Proves \lnot !A_n(c_n)$}
{$\Gamma_n \Proves !A_n(c_n)$}
verkrijgen we
\iftag{prvEx}
{$\Gamma_n \Proves \lforall[x_n][\lnot !A_n(x_n)]$}
{$\Gamma_n \Proves \lforall[x_n][!A_n(x_n)]$}.
Daarmee gelden zowel
\iftag{prvEx}
{$\Gamma_n \Proves \lexists[x_n][!A_n(x_n)]$ als
$\Gamma_n \Proves \lforall[x_n][\lnot !A_n(x_n)]$}
{$\Gamma_n \Proves \lnot\lforall[x_n][!A_n(x_n)]$ als
$\Gamma_n \Proves \lforall[x_n][!A_n(x_n)]$},
zodat $\Gamma_n$ zelf inconsistent is.
\iftag{prvEx}
{(Merk op dat
\iftag{prvAll}
{$\lforall[x_n][\lnot !A_n(x_n)] \Proves
  \lnot\lexists[x_n][!A_n(x_n)]$}
{$\lforall[x_n][\lnot !A_n]$ is gedefinieerd als
  $\lnot\lexists[x_n][\lnot\lnot !A_n(x_n)]$ en
  $\lnot\lexists[x_n][\lnot\lnot !A_n(x_n)] \Proves
  \lnot\lexists[x_n][!A_n(x_n)]$}.)}{}
Dit is een tegenspraak, want $\Gamma_n$ was verondersteld consistent te
zijn. Bijgevolg is $\Gamma_n \cup \{ !D_n\}$ consistent.
\end{proof}

ordinary_text:
\begin{explain}
Nu bekijken we wat verzadiging ons oplevert. Neem een verzameling die
\emph{volledig}, consistent en verzadigd is. Dan geldt:
\iftag{prvAll}{zij bevat een universeel gekwantificeerde !!{sentence}
  precies als zij al haar instanties bevat}{}\iftag{defAll,defEx}{}{
  en }\iftag{prvAll}{zij bevat een existentieel gekwantificeerde
  !!{sentence} precies als zij minstens één instantie bevat}{}. We
gebruiken dit straks om te bewijzen dat de !!{structure} die we uit een
volledige, consistente, verzadigde verzameling bouwen al haar
gekwantificeerde zinnen waar maakt.
\end{explain}

standard_text:
\begin{explain}
We zullen nu aantonen dat \emph{volledige}, consistente verzamelingen die
verzadigd zijn de volgende eigenschap hebben: \iftag{prvAll}{zo'n
  verzameling bevat een universeel gekwantificeerde !!{sentence} dan en
  slechts dan als zij al haar instanties bevat}{}\iftag{defAll,defEx}{}{
  en }\iftag{prvAll}{zij bevat een existentieel gekwantificeerde
  !!{sentence} dan en slechts dan als zij ten minste één instantie
  bevat}{}. We zullen dit gebruiken om aan te tonen dat de !!{structure}
die we uit een volledige, consistente, verzadigde verzameling genereren,
al haar gekwantificeerde zinnen waar maakt.
\end{explain}

ordinary_text:
\begin{prop}\ollabel{prop:saturated-instances}
Stel dat $\Gamma$ volledig, consistent en verzadigd is.
\begin{tagenumerate}{prvEx,prvAll}
\tagitem{prvEx}{$\lexists[x][!A(x)] \in \Gamma$ precies als
  $!A(t) \in \Gamma$ voor minstens één gesloten term~$t$.}{}
\tagitem{prvAll}{$\lforall[x][!A(x)] \in \Gamma$ precies als
  $!A(t) \in \Gamma$ voor alle gesloten termen~$t$.}{}
\end{tagenumerate}
\end{prop}

source_text:
\begin{prop}\ollabel{prop:saturated-instances}
Suppose $\Gamma$ is complete, consistent, and saturated.
\begin{tagenumerate}{prvEx,prvAll}
\tagitem{prvEx}{$\lexists[x][!A(x)] \in \Gamma$ iff $!A(t) \in \Gamma$
  for at least one closed term~$t$.}{}
\tagitem{prvAll}{$\lforall[x][!A(x)] \in \Gamma$ iff $!A(t) \in \Gamma$
  for all closed terms~$t$.}{}
\end{tagenumerate}
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:saturated-instances}
Veronderstel dat $\Gamma$ volledig, consistent en verzadigd is.
\begin{tagenumerate}{prvEx,prvAll}
\tagitem{prvEx}{$\lexists[x][!A(x)] \in \Gamma$ dan en slechts dan als
  $!A(t) \in \Gamma$ voor ten minste één gesloten term~$t$.}{}
\tagitem{prvAll}{$\lforall[x][!A(x)] \in \Gamma$ dan en slechts dan als
  $!A(t) \in \Gamma$ voor alle gesloten termen~$t$.}{}
\end{tagenumerate}
\end{prop}

