\begin{defn}[Termmodel]
\ollabel{defn:termmodel}
Neem een !!{complete}, consistente en verzadigde verzameling
$\Gamma^*$ van !!{sentence}s in een taal~$\Lang L$. Het
\emph{termmodel}~$\Struct M(\Gamma^*)$ van $\Gamma^*$ is de volgende
!!{structure}:
\begin{enumerate}
\item Het !!{domain}~$\Domain{M(\Gamma^*)}$ bestaat uit alle gesloten
  termen van~$\Lang L$.
\item Een !!{constant} $c$ verwijst naar $c$ zelf:
  $\Assign{c}{M(\Gamma^*)} = c$.
\item Krijgt de !!{function}~$f$ de gesloten termen $t_1$, \dots, $t_n$
  als invoer, dan is haar uitkomst de gesloten term
  $f(t_1, \dots, t_n)$:
\[
\Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) = f(t_1,\dots, t_n)
\]
\item Is $R$ een $n$-plaatsig !!{predicate}, dan geldt
  \[
  \tuple{t_1, \dots,
  t_n} \in \Assign{R}{M(\Gamma^*)} \text{ precies als } \Atom{R}{t_1, \dots,
    t_n} \in \Gamma^*.
  \]
\end{enumerate}
\end{defn}
}{%
\begin{defn}
\ollabel{defn:termmodel}
Neem een volledige consistente verzameling $\Gamma^*$ van
!!{formula}s. We definiëren
\[
\pAssign v(\Gamma^*)(p) = \begin{cases}
  \True & \text{als $p \in \Gamma^*$}\\
  \False & \text{als $p \notin \Gamma^*$}
  \end{cases}
\]
\end{defn}
}

source_text:
\iftag{FOL}{%
\begin{defn}[Term model]
\ollabel{defn:termmodel}
Let $\Gamma^*$ be !!a{complete} and consistent,
saturated set of !!{sentence}s in a language~$\Lang L$. The \emph{term
  model}~$\Struct M(\Gamma^*)$ of $\Gamma^*$ is the !!{structure}
defined as follows:
\begin{enumerate}
\item The !!{domain}~$\Domain{M(\Gamma^*)}$ is the set of all closed
  terms of~$\Lang L$.
\item The interpretation of !!a{constant} $c$ is $c$ itself:
  $\Assign{c}{M(\Gamma^*)} = c$.
\item The !!{function}~$f$ is assigned the function which, given as
  arguments the closed terms $t_1$, \dots, $t_n$, has as value the
  closed term $f(t_1, \dots, t_n)$:
\[
\Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) = f(t_1,\dots, t_n)
\]
\item If $R$ is an $n$-place !!{predicate}, then
  \[
  \tuple{t_1, \dots,
  t_n} \in \Assign{R}{M(\Gamma^*)} \text{ iff } \Atom{R}{t_1, \dots,
    t_n} \in \Gamma^*.
  \]
\end{enumerate}
\end{defn}
}{%
\begin{defn}
\ollabel{defn:termmodel}
Suppose $\Gamma^*$ is a complete consistent set of !!{formula}s. Then we let
\[
\pAssign v(\Gamma^*)(p) = \begin{cases}
  \True & \text{if $p \in \Gamma^*$}\\
  \False & \text{if $p \notin \Gamma^*$}
  \end{cases}
\]
\end{defn}
}

