ordinary_text:
\begin{lem} 
\ollabel{lem:val-in-termmodel} Neem het termmodel
$\Struct M(\Gamma^*)$ uit \olref{defn:termmodel}. Dan geldt
$\Value{t}{M(\Gamma^*)} = t$.
\end{lem}
\begin{proof} 
 We bewijzen dit met inductie naar $t$. Eerst het basisgeval: als $t$
 !!a{constant} is, volgt de bewering meteen uit de definitie van het
 termmodel. Neem voor de volgende stap gesloten termen
 $t_1, \ldots, t_n$ waarvoor $\Value{t_i}{M(\Gamma^*)} = t_i$, en neem
 een !!{function}~$f$ met $n$ argumenten. Dan
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)}, 
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*} 
De inductie laat dus zien dat dit voor elke gesloten term~$t$ geldt.
\end{proof}
}

source_text:
\begin{lem} 
\ollabel{lem:val-in-termmodel} Let $\Struct M(\Gamma^*)$ be the term model
of \olref{defn:termmodel}, then $\Value{t}{M(\Gamma^*)} = t$.
\end{lem}
\begin{proof} 
 The proof is by induction on $t$, where the base case, when $t$
 is !!a{constant}, follows directly from the definition of the term
 model. For the induction step assume $t_1, \ldots, t_n$ are closed terms
 such that $\Value{t_i}{M(\Gamma^*)} = t_i$ and that $f$ is an $n$-ary
 !!{function}. Then 
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)}, 
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*} 
and so by induction this holds for every closed term~$t$.
\end{proof}
}

standard_text:
\begin{lem} 
\ollabel{lem:val-in-termmodel} Laat $\Struct M(\Gamma^*)$ het termmodel
uit \olref{defn:termmodel} zijn. Dan geldt $\Value{t}{M(\Gamma^*)} = t$.
\end{lem}
\begin{proof} 
 Het bewijs verloopt door inductie naar $t$. Het basisgeval, waarin $t$
 !!a{constant} is, volgt rechtstreeks uit de definitie van het termmodel.
 Veronderstel voor de inductiestap dat $t_1, \ldots, t_n$ gesloten termen
 zijn waarvoor $\Value{t_i}{M(\Gamma^*)} = t_i$ en dat $f$ een $n$-aire
 !!{function} is. Dan
\begin{align*}
\Value{f(t_1,\ldots,t_n)}{M(\Gamma^*)} &= \Assign{f}{M(\Gamma^*)}(\Value{t_1}
 {M(\Gamma^*)}, 
\ldots, \Value{t_n}{M(\Gamma^*)}) \\
&= \Assign{f}{M(\Gamma^*)}(t_1, \dots, t_n) \\
&= f(t_1,\dots, t_n),
\end{align*} 
en dus geldt de bewering door inductie voor elke gesloten term~$t$.
\end{proof}
}

