\begin{defn}
Neem een consistente en !!{complete} verzameling $\Gamma^*$ in een
taal~$\Lang L$, een gesloten term $t$ en de relatie $\approx$ uit de
vorige definitie. Dan:
\[
\equivrep{t}{\approx} = \Setabs{t'}{t'\in \Trm[L], t \approx t'}
\]
and $\equivclass{\Trm[L]}{\approx} = \Setabs{\equivrep{t}{\approx}}{t \in \Trm[L]}$.
\end{defn}

source_text:
\begin{defn}
Suppose $\Gamma^*$ is a consistent and !!{complete} set in a
language~$\Lang L$, $t$ is a closed term, and $\approx$ as in the
previous definition. Then:
\[
\equivrep{t}{\approx} = \Setabs{t'}{t'\in \Trm[L], t \approx t'}
\]
and $\equivclass{\Trm[L]}{\approx} = \Setabs{\equivrep{t}{\approx}}{t \in \Trm[L]}$.
\end{defn}

standard_text:
\begin{defn}
Veronderstel dat $\Gamma^*$ een consistente en !!{complete} verzameling
in een taal~$\Lang L$ is, dat $t$ een gesloten term is en dat $\approx$
de relatie uit de vorige definitie is. Dan:
\[
\equivrep{t}{\approx} = \Setabs{t'}{t'\in \Trm[L], t \approx t'}
\]
and $\equivclass{\Trm[L]}{\approx} = \Setabs{\equivrep{t}{\approx}}{t \in \Trm[L]}$.
\end{defn}

ordinary_text:
\begin{defn}
\ollabel{defn:term-model-factor}
Neem het termmodel $\Struct M = \Struct M(\Gamma^*)$ voor~$\Gamma^*$ uit
\olref[mod]{defn:termmodel}. De !!{structure}
$\Struct{\equivclass{M}{\approx}}$ wordt dan als volgt opgebouwd:
\begin{enumerate}
\item $\Domain{\equivclass{M}{\approx}} = \equivclass{\Trm[L]}{\approx}$.
\item $\Assign{c}{\equivclass{M}{\approx}} = \equivrep{c}{\approx}$
\item $\Assign{f}{\equivclass{M}{\approx}}(\equivrep{t_1}{\approx}, \dots,
  \equivrep{t_n}{\approx}) = \equivrep{\Atom{f}{t_1,\dots, t_n}}{\approx}$
\item $\tuple{\equivrep{t_1}{\approx}, \dots, \equivrep{t_n}{\approx}} \in
  \Assign{R}{\equivclass{M}{\approx}}$ precies als
  $\Sat{M}{\Atom{R}{t_1,\dots, t_n}}$, en dus precies als
  $\Atom{R}{t_1,\dots,
  t_n} \in \Gamma^*$.
\end{enumerate}
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:term-model-factor}
Let $\Struct M = \Struct M(\Gamma^*)$ be the term model
for~$\Gamma^*$ from \olref[mod]{defn:termmodel}.  Then $\Struct{\equivclass{M}{\approx}}$ is the following
!!{structure}:
\begin{enumerate}
\item $\Domain{\equivclass{M}{\approx}} = \equivclass{\Trm[L]}{\approx}$.
\item $\Assign{c}{\equivclass{M}{\approx}} = \equivrep{c}{\approx}$
\item $\Assign{f}{\equivclass{M}{\approx}}(\equivrep{t_1}{\approx}, \dots,
  \equivrep{t_n}{\approx}) = \equivrep{\Atom{f}{t_1,\dots, t_n}}{\approx}$
\item $\tuple{\equivrep{t_1}{\approx}, \dots, \equivrep{t_n}{\approx}} \in
  \Assign{R}{\equivclass{M}{\approx}}$ iff
  $\Sat{M}{\Atom{R}{t_1,\dots, t_n}}$, i.e., iff $\Atom{R}{t_1,\dots,
  t_n} \in \Gamma^*$.
\end{enumerate}
\end{defn}

ordinary_text:
\begin{prop}
$\Struct{\equivclass{M}{\approx}}$ is goed gedefinieerd. Dat betekent het
volgende. Zijn $t_1$, \dots, $t_n$, $t_1'$, \dots, $t_n'$ gesloten termen
en geldt $t_i \approx t_i'$, dan
\begin{enumerate}
\item $\equivrep{\Atom{f}{t_1,\dots, t_n}}{\approx} =
    \equivrep{\Atom{f}{t_1',\dots, t_n'}}{\approx}$, dus
  \[
  \Atom{f}{t_1,\dots, t_n} \approx \Atom{f}{t_1',\dots, t_n'}
  \]
  en
\item $\Sat{M}{\Atom{R}{t_1,\dots, t_n}}$ precies als
  $\Sat{M}{\Atom{R}{t_1',\dots, t_n'}}$, dus
  \[
    \Atom{R}{t_1,\dots, t_n} \in \Gamma^* \text{ precies als }
    \Atom{R}{t_1',\dots, t_n'} \in \Gamma^*.
  \]
\end{enumerate}
\end{prop}

source_text:
\begin{prop}
$\Struct{\equivclass{M}{\approx}}$ is well defined, i.e., if $t_1$,
  \dots, $t_n$, $t_1'$, \dots, $t_n'$ are closed terms,
  and $t_i \approx t_i'$ then
\begin{enumerate}
\item $\equivrep{\Atom{f}{t_1,\dots, t_n}}{\approx} =
    \equivrep{\Atom{f}{t_1',\dots, t_n'}}{\approx}$, i.e.,
  \[
  \Atom{f}{t_1,\dots, t_n} \approx \Atom{f}{t_1',\dots, t_n'}
  \]
  and
\item $\Sat{M}{\Atom{R}{t_1,\dots, t_n}}$ iff
  $\Sat{M}{\Atom{R}{t_1',\dots, t_n'}}$, i.e.,
  \[
    \Atom{R}{t_1,\dots, t_n} \in \Gamma^* \text{ iff }
    \Atom{R}{t_1',\dots, t_n'} \in \Gamma^*.
  \]
\end{enumerate}
\end{prop}

standard_text:
\begin{prop}
$\Struct{\equivclass{M}{\approx}}$ is goed gedefinieerd. Als $t_1$,
  \dots, $t_n$, $t_1'$, \dots, $t_n'$ gesloten termen zijn en
  $t_i \approx t_i'$, dan
\begin{enumerate}
\item $\equivrep{\Atom{f}{t_1,\dots, t_n}}{\approx} =
    \equivrep{\Atom{f}{t_1',\dots, t_n'}}{\approx}$, dat wil zeggen
  \[
  \Atom{f}{t_1,\dots, t_n} \approx \Atom{f}{t_1',\dots, t_n'}
  \]
  en
\item $\Sat{M}{\Atom{R}{t_1,\dots, t_n}}$ dan en slechts dan als
  $\Sat{M}{\Atom{R}{t_1',\dots, t_n'}}$, dat wil zeggen
  \[
    \Atom{R}{t_1,\dots, t_n} \in \Gamma^* \text{ dan en slechts dan als }
    \Atom{R}{t_1',\dots, t_n'} \in \Gamma^*.
  \]
\end{enumerate}
\end{prop}

