ordinary_text:
\begin{proof}
We gebruiken inductie naar~$!A$, net als in het bewijs van
\olref[mod]{lem:truth}. Alleen het geval $!A \ident \eq[t][t']$ vraagt
extra aandacht.
\begin{align*}
\Sat{\equivclass{M}{\approx}}{\eq[t][t']} & \text{ precies als } \equivrep{t}{\approx} = \equivrep{t'}{\approx}
\text{ (volgens de definitie van $\Struct{\equivclass{M}{\approx}}$)}\\
& \text{ precies als } t \approx t' \text{ (volgens de definitie van $\equivrep{t}{\approx}$)}\\
& \text{ precies als } \eq[t][t'] \in \Gamma^* \text{ (volgens de definitie van $\approx$).}
\end{align*}
\end{proof}

source_text:
\begin{proof}
By induction on~$!A$, just as in the proof of \olref[mod]{lem:truth}.
The only case that needs additional attention is when $!A \ident
\eq[t][t']$.
\begin{align*}
\Sat{\equivclass{M}{\approx}}{\eq[t][t']} & \text{ iff } \equivrep{t}{\approx} = \equivrep{t'}{\approx}
\text{ (by definition of $\Struct{\equivclass{M}{\approx}}$)}\\
& \text{ iff } t \approx t' \text{ (by definition of $\equivrep{t}{\approx}$)}\\
& \text{ iff } \eq[t][t'] \in \Gamma^* \text{ (by definition of $\approx$).}
\end{align*}
\end{proof}

standard_text:
\begin{proof}
Door inductie naar~$!A$, net als in het bewijs van
\olref[mod]{lem:truth}. Het enige geval dat extra aandacht vereist, is
$!A \ident \eq[t][t']$.
\begin{align*}
\Sat{\equivclass{M}{\approx}}{\eq[t][t']} & \text{ dan en slechts dan als } \equivrep{t}{\approx} = \equivrep{t'}{\approx}
\text{ (volgens de definitie van $\Struct{\equivclass{M}{\approx}}$)}\\
& \text{ dan en slechts dan als } t \approx t' \text{ (volgens de definitie van $\equivrep{t}{\approx}$)}\\
& \text{ dan en slechts dan als } \eq[t][t'] \in \Gamma^* \text{ (volgens de definitie van $\approx$).}
\end{align*}
\end{proof}

ordinary_text:
\begin{digress}
Het model $\Struct{M(\Gamma^*)}$ is altijd !!{enumerable} en oneindig.
Het quotiëntmodel $\Struct{\equivclass{M}{\approx}}$ kan toch eindig zijn,
want er kunnen maar eindig veel klassen $\equivrep{t}{\approx}$ zijn.
Dat is niet vreemd. De verzameling $\Gamma$ kan !!{sentence}s bevatten
die alleen waar kunnen zijn in een eindige !!{structure}. Een voorbeeld
is $\lforall[x][\lforall[y][x = y]]$. Deze !!{sentence} is consistent,
maar wordt alleen vervuld in !!{structure}s waarvan het !!{domain}
precies één !!{element} bevat.
\end{digress}

standard_text:
\begin{digress}
Hoewel $\Struct{M(\Gamma^*)}$ altijd !!{enumerable} en oneindig is, kan
$\Struct{\equivclass{M}{\approx}}$ eindig zijn: er kunnen slechts eindig
veel klassen $\equivrep{t}{\approx}$ zijn. Dat is te verwachten, want
$\Gamma$ kan !!{sentence}s bevatten die eisen dat elke !!{structure}
waarin ze waar zijn eindig is. Zo is
$\lforall[x][\lforall[y][x = y]]$ een consistente !!{sentence}, maar zij
wordt alleen vervuld in !!{structure}s met !!a{domain} dat precies één
!!{element} bevat.
\end{digress}

