\begin{thm}[Volledigheidsstelling]
\ollabel{thm:completeness}
Neem een verzameling !!{sentence}s~$\Gamma$. Als $\Gamma$ consistent is,
dan is de verzameling vervulbaar.
\end{thm}

source_text:
\begin{thm}[Completeness Theorem]
\ollabel{thm:completeness}
Let $\Gamma$ be a set of !!{sentence}s.  If $\Gamma$ is consistent, it
is satisfiable.
\end{thm}

standard_text:
\begin{thm}[Volledigheidsstelling]
\ollabel{thm:completeness}
Laat $\Gamma$ een verzameling !!{sentence}s zijn. Als $\Gamma$ consistent
is, dan is zij vervulbaar.
\end{thm}

ordinary_text:
\begin{proof}
Neem aan dat $\Gamma$ consistent is.\iftag{FOL}{ Volgens
  \olref[hen]{lem:henkin} bestaat er een verzadigde consistente
  verzameling $\Gamma' \supseteq \Gamma$.}{} Het lemma van Lindenbaum,
\olref[lin]{lem:lindenbaum}, geeft vervolgens een
$\Gamma^* \supseteq \iftag{FOL}{\Gamma'}{\Gamma}$ die consistent en
!!{complete} is.
\iftag{FOL}{
  Omdat $\Gamma' \subseteq \Gamma^*$, geldt voor elke
  !!{formula}~$!A(x)$ dat $\Gamma^*$ !!a{sentence} van deze vorm bevat:
  \iftag{prvEx}
        {$\lexists[x][!A(x)] \lif !A(c)$}
        {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c)$}
  en daarom is $\Gamma^*$ verzadigd. Bevat $\Gamma$ geen~$\eq$, dan zegt}{Dan zegt}
\olref[mod]{lem:truth},
$\iftag{FOL}{\Sat{M(\Gamma^*)}}{\pSat{v(\Gamma^*)}}{!A}$ precies als
$!A \in \Gamma^*$, volgens \olref[mod]{lem:truth}. Dus geldt voor elke
$!A \in \Gamma$ dat
$\iftag{FOL}{\Sat{M(\Gamma^*)}}{\pSat{v(\Gamma^*)}}{!A}$. Daarmee is
$\Gamma$ vervulbaar.\iftag{FOL}{ Bevat $\Gamma$ wel~$\eq$, dan zegt
  \olref[ide]{lem:truth} voor elke !!{sentence}~$!A$ dat
  $\Sat{\equivclass{M}{\approx}}{!A}$ precies als
  $!A \in \Gamma^*$. Dus geldt $\Sat{\equivclass{M}{\approx}}{!A}$ voor
  elke $!A \in \Gamma$. Ook in dit geval is $\Gamma$ vervulbaar.}{}
\end{proof}

source_text:
\begin{proof}
Suppose $\Gamma$ is consistent.\iftag{FOL}{ By
  \olref[hen]{lem:henkin}, there is a saturated consistent set
  $\Gamma' \supseteq \Gamma$.}{} By \olref[lin]{lem:lindenbaum}, there
is a $\Gamma^* \supseteq \iftag{FOL}{\Gamma'}{\Gamma}$ which is
consistent and !!{complete}.
\iftag{FOL}{
  Since $\Gamma' \subseteq \Gamma^*$, for each
  !!{formula}~$!A(x)$, $\Gamma^*$ contains !!a{sentence} of the form
  \iftag{prvEx}
        {$\lexists[x][!A(x)] \lif !A(c)$}
        {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c)$}
  and so $\Gamma^*$ is saturated.  If $\Gamma$
  does not contain~$\eq$, then by}{By}
\olref[mod]{lem:truth},
$\iftag{FOL}{\Sat{M(\Gamma^*)}}{\pSat{v(\Gamma^*)}}{!A}$ iff $!A \in
\Gamma^*$.  From this it follows in particular that for all $!A \in
\Gamma$, $\iftag{FOL}{\Sat{M(\Gamma^*)}}{\pSat{v(\Gamma^*)}}{!A}$, so
$\Gamma$ is satisfiable.\iftag{FOL}{
  If $\Gamma$ does contain~$\eq$,
  then by \olref[ide]{lem:truth}, for all !!{sentence}s~$!A$,
  $\Sat{\equivclass{M}{\approx}}{!A}$ iff $!A \in \Gamma^*$.  In
  particular, $\Sat{\equivclass{M}{\approx}}{!A}$ for all $!A \in
  \Gamma$, so $\Gamma$ is satisfiable.}{}
\end{proof}

standard_text:
\begin{proof}
Veronderstel dat $\Gamma$ consistent is.\iftag{FOL}{ Volgens
  \olref[hen]{lem:henkin} bestaat er een verzadigde consistente
  verzameling $\Gamma' \supseteq \Gamma$.}{} Volgens
\olref[lin]{lem:lindenbaum} bestaat er een
$\Gamma^* \supseteq \iftag{FOL}{\Gamma'}{\Gamma}$ die consistent en
!!{complete} is.
\iftag{FOL}{
  Omdat $\Gamma' \subseteq \Gamma^*$, geldt voor elke
  !!{formula}~$!A(x)$ dat $\Gamma^*$ !!a{sentence} van de volgende vorm bevat:
  \iftag{prvEx}
        {$\lexists[x][!A(x)] \lif !A(c)$}
        {$\lnot\lforall[x][!A(x)] \lif \lnot !A(c)$}
  en dus is $\Gamma^*$ verzadigd. Als $\Gamma$ geen~$\eq$ bevat, volgt
  uit}{Uit}
\olref[mod]{lem:truth},
$\iftag{FOL}{\Sat{M(\Gamma^*)}}{\pSat{v(\Gamma^*)}}{!A}$ dan en slechts
dan als $!A \in \Gamma^*$. Hieruit volgt in het bijzonder dat voor alle
$!A \in \Gamma$, $\iftag{FOL}{\Sat{M(\Gamma^*)}}{\pSat{v(\Gamma^*)}}{!A}$,
zodat $\Gamma$ vervulbaar is.\iftag{FOL}{ Als $\Gamma$ wel~$\eq$ bevat,
  dan geldt volgens \olref[ide]{lem:truth} voor alle !!{sentence}s~$!A$
  dat $\Sat{\equivclass{M}{\approx}}{!A}$ dan en slechts dan als
  $!A \in \Gamma^*$. In het bijzonder geldt
  $\Sat{\equivclass{M}{\approx}}{!A}$ voor alle $!A \in \Gamma$, zodat
  $\Gamma$ vervulbaar is.}{}
\end{proof}

ordinary_text:
\begin{cor}[Volledigheidsstelling, tweede formulering]
\ollabel{cor:completeness}
Voor elke $\Gamma$ en elke !!{sentence}~$!A$ geldt: als
$\Gamma \Entails !A$, dan $\Gamma \Proves !A$.
\end{cor}

source_text:
\begin{cor}[Completeness Theorem, Second Version]
\ollabel{cor:completeness}
For all $\Gamma$ and !!{sentence}s~$!A$: if $\Gamma \Entails !A$ then
$\Gamma \Proves !A$.
\end{cor}

