\begin{defn}
  Een verzameling $\Gamma$ van !!{formula}s heet \emph{eindig
  vervulbaar} precies als elke eindige $\Gamma_0 \subseteq \Gamma$
  vervulbaar is.
\end{defn}

source_text:
\begin{defn}
  A set $\Gamma$ of !!{formula}s is \emph{finitely satisfiable} iff every finite $\Gamma_0 \subseteq \Gamma$ is satisfiable.
\end{defn}

standard_text:
\begin{defn}
  Een verzameling $\Gamma$ van !!{formula}s heet \emph{eindig
  vervulbaar} dan en slechts dan als elke eindige
  $\Gamma_0 \subseteq \Gamma$ vervulbaar is.
\end{defn}

ordinary_text:
\begin{thm}[Compactheidsstelling]
\ollabel{thm:compactness}
Voor elke verzameling zinnen $\Gamma$ en elke zin $!A$ geldt:
\begin{enumerate}
  \item $\Gamma \Entails !A$ precies als er een eindige
    $\Gamma_0 \subseteq \Gamma$ bestaat waarvoor
    $\Gamma_0 \Entails !A$.
  \item $\Gamma$ is vervulbaar precies als zij eindig vervulbaar is.
\end{enumerate}
\end{thm}

source_text:
\begin{thm}[Compactness Theorem]
\ollabel{thm:compactness}
The following hold for any sentences $\Gamma$ and $!A$:
\begin{enumerate}
  \item $\Gamma \Entails !A$ iff there is a finite $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Entails !A$.
  \item $\Gamma$ is satisfiable iff it is finitely
    satisfiable.
\end{enumerate}
\end{thm}

standard_text:
\begin{thm}[Compactheidsstelling]
\ollabel{thm:compactness}
Voor elke verzameling zinnen $\Gamma$ en elke zin $!A$ geldt:
\begin{enumerate}
  \item $\Gamma \Entails !A$ dan en slechts dan als er een eindige
    $\Gamma_0 \subseteq \Gamma$ bestaat waarvoor
    $\Gamma_0 \Entails !A$.
  \item $\Gamma$ is vervulbaar dan en slechts dan als zij eindig
    vervulbaar is.
\end{enumerate}
\end{thm}

