\begin{prop}
\ollabel{prop:fsat-ccs}
Stel dat $\Gamma$ !!{complete} en eindig vervulbaar is. Dan geldt:
\begin{enumerate}
\tagitem{prvAnd}{$(!A \land !B) \in \Gamma$
  precies als zowel $!A \in \Gamma$ als $!B \in \Gamma$.}{}

source_text:
\begin{prop}
\ollabel{prop:fsat-ccs}
Suppose $\Gamma$ is !!{complete} and finitely satisfiable. Then:
\begin{enumerate}
\tagitem{prvAnd}{$(!A \land !B) \in \Gamma$
  iff both $!A \in \Gamma$ and $!B \in \Gamma$.}{}

standard_text:
\begin{prop}
\ollabel{prop:fsat-ccs}
Veronderstel dat $\Gamma$ !!{complete} en eindig vervulbaar is. Dan geldt:
\begin{enumerate}
\tagitem{prvAnd}{$(!A \land !B) \in \Gamma$
  dan en slechts dan als zowel $!A \in \Gamma$ als $!B \in \Gamma$.}{}

ordinary_text:
\tagitem{prvIf}{$(!A \lif !B) \in \Gamma$ precies als
  $!A \notin \Gamma$ of $!B \in \Gamma$.}{}
\end{enumerate}
\end{prop}

source_text:
\tagitem{prvIf}{$(!A \lif !B) \in \Gamma$ iff
  either $!A \notin \Gamma$ or $!B \in \Gamma$.}{}
\end{enumerate}
\end{prop}

standard_text:
\tagitem{prvIf}{$(!A \lif !B) \in \Gamma$ dan en slechts dan als
  $!A \notin \Gamma$ of $!B \in \Gamma$.}{}
\end{enumerate}
\end{prop}

