\begin{thm} 
\ollabel{thm:downward-ls} Als $\Gamma$ consistent is, heeft zij
!!a{enumerable} model. De verzameling is dus vervulbaar in !!a{structure}
waarvan het domein eindig of !!{denumerable} is.
\end{thm}

source_text:
\begin{thm} 
\ollabel{thm:downward-ls} If $\Gamma$ is consistent then it has
!!a{enumerable} model, i.e., it is satisfiable in !!a{structure}
whose domain is either finite or !!{denumerable}.
\end{thm}

standard_text:
\begin{thm} 
\ollabel{thm:downward-ls} Als $\Gamma$ consistent is, heeft zij
!!a{enumerable} model; zij is dus vervulbaar in !!a{structure}
waarvan het domein eindig of !!{denumerable} is.
\end{thm}

ordinary_text:
\begin{proof}
Stel dat $\Gamma$ consistent is. Het bewijs van de volledigheidsstelling
levert dan de !!{structure}~$\Struct M$. Haar domein $\Domain{M}$ is niet
groter dan de verzameling termen van de taal~$\Lang L$. De structuur
$\Struct M$ is dus hoogstens !!{denumerable}.
\end{proof}

source_text:
\begin{proof}
If $\Gamma$ is consistent, the !!{structure}~$\Struct M$ delivered by
the proof of the completeness theorem has a domain $\Domain{M}$ that
is no larger than the set of the terms of the language~$\Lang L$. So
$\Struct M$ is at most !!{denumerable}.
\end{proof}

