\begin{thm}
\ollabel{noidentity-ls} Stel dat $\Gamma$ een consistente verzameling
!!{sentence}s is in de taal van de eerste-ordelogica zonder identiteit.
Dan heeft zij !!a{denumerable} model. Zij is dus vervulbaar in
!!a{structure} waarvan het domein oneindig en !!{enumerable} is.
\end{thm}

source_text:
\begin{thm}
\ollabel{noidentity-ls} If $\Gamma$ is a consistent set of !!{sentence}s
in the language of first-order logic without identity, then it has
!!a{denumerable} model, i.e., it is satisfiable in !!a{structure}
whose domain is infinite and !!{enumerable}.
\end{thm}

