\begin{defn}[Termen]
\ollabel{defn:terms}
De verzameling \emph{termen}~$\Trm[L]$ van~$\Lang L$ bouwen we stap
voor stap (inductief) met de volgende regels:
\begin{enumerate}
\item Iedere !!{variable} is een term.
\item Iedere !!{constant} van~$\Lang L$ is een term.
\item Als $f$ een !!{function} met $n$ argumentplaatsen is en $t_1$,
  \dots, $t_n$ termen zijn, dan is $\Atom{f}{t_1, \ldots, t_n}$ een
  term.
\tagitem{limitClause}{
  Verder is niets een term.}{}
\end{enumerate}
Een term zonder !!{variable}s heet een \emph{gesloten term}.
\end{defn}

source_text:
\begin{defn}[Terms]
\ollabel{defn:terms}
The set of \emph{terms}~$\Trm[L]$ of~$\Lang L$ is
defined inductively by:
\begin{enumerate}
\item Every !!{variable} is a term.
\item Every !!{constant} of~$\Lang L$ is a term.
\item If $f$ is an $n$-place !!{function} and $t_1$, \dots, $t_n$
  are terms, then $\Atom{f}{t_1, \ldots, t_n}$ is a term.
\tagitem{limitClause}{
  Nothing else is a term.}{}
\end{enumerate}
A term containing no !!{variable}s is a \emph{closed term}.
\end{defn}

standard_text:
\begin{defn}[Termen]
\ollabel{defn:terms}
De verzameling \emph{termen}~$\Trm[L]$ van~$\Lang L$ wordt inductief
gedefinieerd door:
\begin{enumerate}
\item Iedere !!{variable} is een term.
\item Iedere !!{constant} van~$\Lang L$ is een term.
\item Als $f$ een $n$-plaatsige !!{function} is en $t_1$, \dots, $t_n$
  termen zijn, dan is $\Atom{f}{t_1, \ldots, t_n}$ een term.
\tagitem{limitClause}{
  Niets anders is een term.}{}
\end{enumerate}
Een term die geen !!{variable}s bevat, heet een \emph{gesloten term}.
\end{defn}

