\begin{lem}[\emph{Inductieprincipe voor !!{formula}s}]
    \ollabel{thm:frmind}
    Neem een taal~$\Lang L$ van de logica van de eerste orde.
    Stel dat een eigenschap~$P$ voor alle atomaire !!{formula}s geldt.
    Stel ook dat zij aan de volgende voorwaarden voldoet:
    %
    \begin{enumerate}
        \tagitem{prvNot}{zij geldt voor $\lnot !A$ zodra zij
            geldt voor~$!A$;}{}
        \tagitem{prvAnd}{zij geldt voor $(!A \land !B)$ zodra zij
            geldt voor $!A$ en~$!B$;}{}
        \tagitem{prvOr}{zij geldt voor $(!A \lor !B)$ zodra zij
            geldt voor $!A$ en~$!B$;}{}
        \tagitem{prvIf}{zij geldt voor $(!A \lif !B)$ zodra zij
            geldt voor $!A$ en~$!B$;}{}
        \tagitem{prvIff}{zij geldt voor $(!A \liff !B)$ zodra zij
            geldt voor $!A$ en~$!B$;}{}
        \tagitem{prvEx}{zij geldt voor $\lexists[x][!A]$ zodra zij
            geldt voor~$!A$;}{}
        \tagitem{prvAll}{zij geldt voor $\lforall[x][!A]$ zodra zij
            geldt voor~$!A$;}{}
  \end{enumerate}
  Hierbij zijn $!A$ en $!B$ !!{formula}s van~$\Lang{L}$. Dan geldt
  $P$ voor alle formules in~$\Frm[L]$.
\end{lem}

source_text:
\begin{lem}[\emph{Principle of induction on !!{formula}s}]
    \ollabel{thm:frmind}
    Let $\Lang L$ be a first-order language.
    If some property~$P$ holds for all the atomic !!{formula}s
    and is such that
    %
    \begin{enumerate}
        \tagitem{prvNot}{it holds for $\lnot !A$ whenever it
            holds for~$!A$;}{}
        \tagitem{prvAnd}{it holds for $(!A \land !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvOr}{it holds for $(!A \lor !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvIf}{it holds for $(!A \lif !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvIff}{it holds for $(!A \liff !B)$
            whenever it holds for $!A$ and~$!B$;}{}
        \tagitem{prvEx}{it holds for $\lexists[x][!A]$
            whenever it holds for~$!A$;}{}
        \tagitem{prvAll}{it holds for $\lforall[x][!A]$
            whenever it holds for~$!A$;}{}
  \end{enumerate}
  (assuming $!A$ and $!B$ are !!{formula}s of~$\Lang{L}$),
  then $P$ holds for all formulas in~$\Frm[L]$.
\end{lem}

standard_text:
\begin{lem}[\emph{Inductieprincipe voor !!{formula}s}]
    \ollabel{thm:frmind}
    Zij $\Lang L$ een eerste-ordetaal.
    Als een eigenschap~$P$ voor alle atomaire !!{formula}s geldt
    en zo is dat
    %
    \begin{enumerate}
        \tagitem{prvNot}{zij voor $\lnot !A$ geldt wanneer zij
            voor~$!A$ geldt;}{}
        \tagitem{prvAnd}{zij voor $(!A \land !B)$ geldt
            wanneer zij voor $!A$ en~$!B$ geldt;}{}
        \tagitem{prvOr}{zij voor $(!A \lor !B)$ geldt
            wanneer zij voor $!A$ en~$!B$ geldt;}{}
        \tagitem{prvIf}{zij voor $(!A \lif !B)$ geldt
            wanneer zij voor $!A$ en~$!B$ geldt;}{}
        \tagitem{prvIff}{zij voor $(!A \liff !B)$ geldt
            wanneer zij voor $!A$ en~$!B$ geldt;}{}
        \tagitem{prvEx}{zij voor $\lexists[x][!A]$ geldt
            wanneer zij voor~$!A$ geldt;}{}
        \tagitem{prvAll}{zij voor $\lforall[x][!A]$ geldt
            wanneer zij voor~$!A$ geldt;}{}
  \end{enumerate}
  waarbij $!A$ en $!B$ !!{formula}s van~$\Lang{L}$ zijn, dan geldt
  $P$ voor alle formules in~$\Frm[L]$.
\end{lem}

