ordinary_text:
\begin{prop}
\ollabel{prop:unique-atomic}
Als $!A$ een atomaire !!{formula} is, geldt precies één van de volgende
mogelijkheden.
\begin{enumerate}
\tagitem{prvFalse}{$!A \ident \lfalse$.}{}
\tagitem{prvTrue}{$!A \ident \ltrue$.}{}
\item $!A \ident \Atom{R}{t_1,\dots,t_n}$, waarbij $R$ een $n$-plaatsig
  !!{predicate} is en $t_1$, \dots, $t_n$ termen zijn. De symbolen $R$,
  $t_1$, \dots, $t_n$ liggen allemaal precies vast.
\item $!A \ident \eq[t_1][t_2]$, waarbij er voor $t_1$ en $t_2$ maar
  één keuze mogelijk is.
\end{enumerate}
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:unique-atomic}
If $!A$ is an atomic !!{formula}, then it satisfies one, and only one
of the following conditions.
\begin{enumerate}
\tagitem{prvFalse}{$!A \ident \lfalse$.}{}
\tagitem{prvTrue}{$!A \ident \ltrue$.}{}
\item $!A \ident \Atom{R}{t_1,\dots,t_n}$ where $R$ is an $n$-place
  !!{predicate}, $t_1$, \dots, $t_n$ are terms, and each of $R$,
  $t_1$, \dots, $t_n$ is uniquely determined.
\item $!A \ident \eq[t_1][t_2]$ where $t_1$ and $t_2$ are uniquely
  determined terms.
\end{enumerate}
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:unique-atomic}
Als $!A$ een atomaire !!{formula} is, voldoet zij aan precies één van
de volgende voorwaarden.
\begin{enumerate}
\tagitem{prvFalse}{$!A \ident \lfalse$.}{}
\tagitem{prvTrue}{$!A \ident \ltrue$.}{}
\item $!A \ident \Atom{R}{t_1,\dots,t_n}$, waarbij $R$ een $n$-plaatsig
  !!{predicate} is, $t_1$, \dots, $t_n$ termen zijn en elk van $R$,
  $t_1$, \dots, $t_n$ eenduidig bepaald is.
\item $!A \ident \eq[t_1][t_2]$, waarbij $t_1$ en $t_2$ eenduidig
  bepaalde termen zijn.
\end{enumerate}
\end{prop}

