\begin{prop}
\ollabel{prop:subfrm-trans}
Stel dat $!B$ een subformule van $!A$ is en $!C$ een subformule van
$!B$. Dan is $!C$ ook een subformule van $!A$. De relatie ``is een
subformule van'' is dus transitief.
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:subfrm-trans}
Suppose $!B$ is a subformula of $!A$ and $!C$ is a subformula of $!B$.
Then $!C$ is a subformula of $!A$. In other words, the subformula
relation is transitive.
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:subfrm-trans}
Stel dat $!B$ een subformule van $!A$ is en $!C$ een subformule van
$!B$. Dan is $!C$ een subformule van $!A$. Met andere woorden: de
subformulerelatie is transitief.
\end{prop}

