source_text:
\begin{defn}[Minimal formation sequences]
\ollabel{defn:minimal-fseq}
A formation sequence $\tuple{!A_0, \ldots, !A_n}$ for a
formula~$!A$ is a \emph{minimal formation sequence} for~$!A$
if for every other formation sequence~$s$ for~$!A$,
the length of~$s$ is greater than or equal to~$n+1$.

ordinary_text:
Zo is ook een constructiereeks $\tuple{t_0, \ldots, t_n}$
voor een term~$t$ een \emph{kortst mogelijke constructiereeks}
voor~$t$ als geen andere constructiereeks met hetzelfde einddoel korter
is. Neem een willekeurige andere constructiereeks~$s$ voor~$t$. De
lengte van~$s$ is dan groter dan of gelijk aan~$n+1$.
\end{defn}

source_text:
Similarly, a formation sequence $\tuple{t_0, \ldots, t_n}$
for a term~$t$ is a \emph{minimal formation sequence}
for~$t$ if for every other formation sequence~$s$ for~$t$,
the length of~$s$ is greater than or equal to~$n+1$.
\end{defn}

standard_text:
Op dezelfde wijze is een constructiereeks $\tuple{t_0, \ldots, t_n}$
voor een term~$t$ een \emph{minimale constructiereeks}
voor~$t$ als voor iedere andere constructiereeks~$s$ voor~$t$ geldt dat
de lengte van~$s$ groter dan of gelijk aan~$n+1$ is.
\end{defn}

ordinary_text:
\begin{prop}
\ollabel{prop:subformula-equivs}
De volgende drie uitspraken zijn equivalent; ze zeggen dus hetzelfde:
\begin{enumerate}
    \item $!B$ is een sub-!!{formula} van~$!A$.
    \item $!B$ komt voor in iedere constructiereeks van~$!A$.
    \item $!B$ komt voor in een kortst mogelijke constructiereeks van~$!A$.
\end{enumerate}
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:subformula-equivs}
The following are equivalent:
\begin{enumerate}
    \item $!B$ is a sub-!!{formula} of~$!A$.
    \item $!B$ occurs in every formation sequence of~$!A$.
    \item $!B$ occurs in a minimal formation sequence of~$!A$.
\end{enumerate}
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:subformula-equivs}
De volgende uitspraken zijn equivalent:
\begin{enumerate}
    \item $!B$ is een sub-!!{formula} van~$!A$.
    \item $!B$ komt voor in iedere constructiereeks van~$!A$.
    \item $!B$ komt voor in een minimale constructiereeks van~$!A$.
\end{enumerate}
\end{prop}

