\begin{history}
Raymond Smullyan voerde constructiereeksen in in zijn leerboek
\emph{First-Order Logic} \citep{Smullyan1968}.
\citet{Zuckerman1973} stelde later meer eigenschappen van
constructiereeksen vast.
\end{history}

source_text:
\begin{history}
Formation sequences were introduced by Raymond Smullyan in his
textbook \emph{First-Order Logic} \citep{Smullyan1968}.
Additional properties of formation sequences were established by
\citet{Zuckerman1973}.
\end{history}

standard_text:
