\begin{defn}[Een term invullen in een term]
We schrijven $\Subst{s}{t}{x}$ voor het resultaat van het
\emph{invullen} van $t$ voor ieder voorkomen van~$x$ in $s$. Dat
resultaat wordt stap voor stap bepaald door de opbouw van de oorspronkelijke term:
\begin{enumerate}
\item \indcase{s}{c}{$\Subst{\indfrm}{t}{x}$ gewoon $s$ blijft.}

source_text:
\begin{defn}[Substitution in a term]
We define $\Subst{s}{t}{x}$, the result of \emph{substituting} $t$
for every occurrence of~$x$ in $s$, recursively:
\begin{enumerate}
\item \indcase{s}{c}{$\Subst{\indfrm}{t}{x}$ is just $s$.}

standard_text:
\begin{defn}[Substitutie in een term]
We definiëren $\Subst{s}{t}{x}$, het resultaat van het
\emph{substitueren} van $t$ voor ieder voorkomen van~$x$ in $s$,
recursief:
\begin{enumerate}
\item \indcase{s}{c}{$\Subst{\indfrm}{t}{x}$ gewoon $s$ is.}

ordinary_text:
\item\indcase{s}{\Atom{f}{t_1, \dots, t_n}}{we in elk onderdeel
  dezelfde vervanging uitvoeren, zodat $\Subst{\indfrmp}{t}{x}$ gelijk is aan
  $\Atom{f}{\Subst{t_1}{t}{x}, \dots, \Subst{t_n}{t}{x}}$.}
\end{enumerate}
\end{defn}

source_text:
\item\indcase{s}{\Atom{f}{t_1, \dots, t_n}}{$\Subst{\indfrmp}{t}{x}$ is
  $\Atom{f}{\Subst{t_1}{t}{x}, \dots, \Subst{t_n}{t}{x}}$.}
\end{enumerate}
\end{defn}

standard_text:
\item\indcase{s}{\Atom{f}{t_1, \dots, t_n}}{$\Subst{\indfrmp}{t}{x}$ gelijk is aan
  $\Atom{f}{\Subst{t_1}{t}{x}, \dots, \Subst{t_n}{t}{x}}$.}
\end{enumerate}
\end{defn}

ordinary_text:
\begin{defn}
Een term~$t$ kan veilig voor $x$ in $!A$ worden ingevuld — in de vaste
vakterm is hij dan \emph{!!{free for}} — als geen vrij voorkomen van~$x$
in $!A$ binnen het bereik ligt van een kwantor die een variabele bindt
die in~$t$ voorkomt. Dat betekent dat het invullen geen nieuwe binding maakt.
\end{defn}

source_text:
\begin{defn}
A term~$t$ is \emph{!!{free for}} $x$ in $!A$ if none of the free
occurrences of~$x$ in $!A$ occur in the scope of a quantifier that
binds a variable in~$t$.
\end{defn}

standard_text:
\begin{defn}
Een term~$t$ is \emph{!!{free for}} $x$ in $!A$ als geen van de vrije
voorkomens van~$x$ in $!A$ binnen het bereik ligt van een kwantor die
een in~$t$ voorkomende variabele bindt.
\end{defn}

