\begin{defn}[Variable Assignment]
A \emph{variable assignment}~$s$ for !!a{structure}~$\Struct{M}$ is a
function which maps each !!{variable} to !!a{element} of~$\Domain M$,
i.e., $s\colon \Var \to \Domain M$.
\end{defn}

ordinary_text:
\begin{explain}
!!^a{structure} geeft elke !!{constant} een !!{value}. Een toekenning
aan variabelen geeft elke variabele een waarde. Ook een term die uit
zulke tekens is opgebouwd, moet een !!{element} van het !!{domain}
aanwijzen. Daarom bepalen we de !!{value} van een term stap voor stap.
Bij !!{constant}s en variabelen nemen we de waarde die de !!{structure}
of de toekenning al geeft. Bij een langere term rekenen we verder met
de functies die de !!{structure} aan de !!{function}s heeft gekoppeld.
\end{explain}

\begin{defn}[De !!^{value} van termen]
Neem een term $t$ van de taal~$\Lang L$, een !!{structure}~$\Struct M$
voor~$\Lang L$ en !!a{variable} toekenning~$s$ voor~$\Struct M$.
De \emph{!!{value}}~$\Value{t}{M}[s]$ bepalen we zo:
\begin{enumerate}
\item \indcase{t}{c}{$\Value{\indfrm}{M}[s] = \Assign{\indcomplex}{M}$.}
\item \indcase{t}{x}{$\Value{\indfrm}{M}[s] = s(\indcomplex)$.}
\item \indcase{t}{\Atom{f}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = \Assign{f}{M}(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{enumerate}
\end{defn}

source_text:
\begin{defn}[!!^{value} of Terms]
If $t$ is a term of the language~$\Lang L$, $\Struct M$ is a
!!{structure} for~$\Lang L$, and $s$ is !!a{variable} assignment
for~$\Struct M$, the \emph{!!{value}}~$\Value{t}{M}[s]$ is defined as
follows:
\begin{enumerate}
\item \indcase{t}{c}{$\Value{\indfrm}{M}[s] = \Assign{\indcomplex}{M}$.}
\item \indcase{t}{x}{$\Value{\indfrm}{M}[s] = s(\indcomplex)$.}
\item \indcase{t}{\Atom{f}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = \Assign{f}{M}(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{enumerate}
\end{defn}

standard_text:
\begin{defn}[!!^{value} van termen]
Zij $t$ een term van de taal~$\Lang L$, zij $\Struct M$ een
!!{structure} voor~$\Lang L$, en zij $s$ !!a{variable} bedeling
voor~$\Struct M$. De \emph{!!{value}}~$\Value{t}{M}[s]$ wordt als
volgt gedefinieerd:
\begin{enumerate}
\item \indcase{t}{c}{$\Value{\indfrm}{M}[s] = \Assign{\indcomplex}{M}$.}
\item \indcase{t}{x}{$\Value{\indfrm}{M}[s] = s(\indcomplex)$.}
\item \indcase{t}{\Atom{f}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = \Assign{f}{M}(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{enumerate}
\end{defn}

ordinary_text:
\begin{explain}
Een $x$-variant van een toekenning~$s$ hoeft bij~$x$ \emph{niet}
werkelijk iets anders te geven. Elke toekenning is dus ook een
$x$-variant van zichzelf.
\end{explain}

source_text:
\begin{explain}
Note that an $x$-variant of an assignment~$s$ does not \emph{have} to
assign something different to~$x$.  In fact, every assignment counts
as an $x$-variant of itself.
\end{explain}

standard_text:
\begin{explain}
Merk op dat een $x$-variant van een bedeling~$s$ \emph{niet} noodzakelijk iets
anders aan~$x$ toekent. Elke bedeling geldt zelfs als een $x$-variant
van zichzelf.
\end{explain}

ordinary_text:
\begin{defn}
  Neem !!a{variable} toekenning~$s$ voor !!a{structure}~$\Struct M$
  en neem $m \in \Domain{M}$. Dan is~$\Subst{s}{m}{x}$ de toekenning
  aan variabelen met de volgende regel:
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{als } y \ident x\\
    s(y) & \text{anders}.
  \end{cases}\]
\end{defn}

source_text:
\begin{defn}
  If $s$ is !!a{variable} assignment for !!a{structure}~$\Struct M$
  and $m \in \Domain{M}$, then the assignment~$\Subst{s}{m}{x}$ is the
  variable assignment defined by
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{if } y \ident x\\
    s(y) & \text{otherwise}.
  \end{cases}\]
\end{defn}

standard_text:
\begin{defn}
  Als $s$ !!a{variable} bedeling is voor !!a{structure}~$\Struct M$
  en $m \in \Domain{M}$, dan is de bedeling~$\Subst{s}{m}{x}$ de
  variabeletoekenning die wordt gedefinieerd door
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{als } y \ident x\\
    s(y) & \text{anders}.
  \end{cases}\]
\end{defn}

ordinary_text:
\begin{defn}[Wanneer een formule waar is]
\ollabel{defn:satisfaction}
We zeggen dat !!a{formula}~$!A$ waar is in !!a{structure}~$\Struct M$
bij !!a{variable} toekenning~$s$. We schrijven dat als
$\Sat{M}{!A}[s]$. De volgende regels leggen stap voor stap vast wanneer
dit geldt. (Met $\Sat/{M}{!A}[s]$ bedoelen we ``niet $\Sat{M}{!A}[s]$.'')
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{$\Sat/{M}{\indfrm}[s]$.}}{}

source_text:
\begin{defn}[Satisfaction]
\ollabel{defn:satisfaction}
Satisfaction of !!a{formula}~$!A$ in !!a{structure}~$\Struct M$
relative to !!a{variable} assignment~$s$, in symbols:
$\Sat{M}{!A}[s]$, is defined recursively as follows. (We write
$\Sat/{M}{!A}[s]$ to mean ``not $\Sat{M}{!A}[s]$.'')
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{$\Sat/{M}{\indfrm}[s]$.}}{}

standard_text:
\begin{defn}[Vervulling]
\ollabel{defn:satisfaction}
!!^a{formula}~$!A$ wordt in !!a{structure}~$\Struct M$ onder
!!a{variable} bedeling~$s$ vervuld, in symbolen:
$\Sat{M}{!A}[s]$, volgens de volgende recursieve definitie. (We schrijven
