ordinary_text:
Nu rekenen we:
\begin{align*}
\Value{f(a,b)}{M}[s] & = \Assign{f}{M}(\Value{a}{M}[s], \Value{b}{M}[s]).
\intertext{$a$ en $b$ zijn !!{constant}s. Daarom is $\Value{a}{M}[s]
  = \Assign{a}{M} = 1$ en $\Value{b}{M}[s] = \Assign{b}{M} = 2$. Dus}
\Value{f(a,b)}{M}[s] & = \Assign{f}{M}(1, 2) = 1+2 = 3.
\intertext{Voor de waarde van $f(f(a,b),a)$ bekijken we eerst}
\Value{f(f(a,b),a)}{M}[s] & = \Assign{f}{M}(\Value{f(a, b)}{M}[s],
\Value{a}{M}[s]) = \Assign{f}{M}(3, 1) = 3,
\intertext{want $3+1 > 3$. Verder is $s(x) = 1$ en $\Value{x}{M}[s] =
  s(x)$. Daarom is ook}
\Value{f(f(a,b),x)}{M}[s] & = \Assign{f}{M}(\Value{f(a, b)}{M}[s],
\Value{x}{M}[s]) = \Assign{f}{M}(3, 1) = 3,
\end{align*}

source_text:
Then
\begin{align*}
\Value{f(a,b)}{M}[s] & = \Assign{f}{M}(\Value{a}{M}[s], \Value{b}{M}[s]).
\intertext{Since $a$ and $b$ are !!{constant}s, $\Value{a}{M}[s]
  = \Assign{a}{M} = 1$ and $\Value{b}{M}[s] = \Assign{b}{M} = 2$. So}
\Value{f(a,b)}{M}[s] & = \Assign{f}{M}(1, 2) = 1+2 = 3.
\intertext{To compute the value of $f(f(a,b),a)$ we have to consider}
\Value{f(f(a,b),a)}{M}[s] & = \Assign{f}{M}(\Value{f(a, b)}{M}[s],
\Value{a}{M}[s]) = \Assign{f}{M}(3, 1) = 3,
\intertext{since $3+1 > 3$. Since $s(x) = 1$ and $\Value{x}{M}[s] =
  s(x)$, we also have}
\Value{f(f(a,b),x)}{M}[s] & = \Assign{f}{M}(\Value{f(a, b)}{M}[s],
\Value{x}{M}[s]) = \Assign{f}{M}(3, 1) = 3,
\end{align*}

standard_text:
Dan geldt
\begin{align*}
\Value{f(a,b)}{M}[s] & = \Assign{f}{M}(\Value{a}{M}[s], \Value{b}{M}[s]).
\intertext{Omdat $a$ en $b$ !!{constant}s zijn, geldt $\Value{a}{M}[s]
  = \Assign{a}{M} = 1$ en $\Value{b}{M}[s] = \Assign{b}{M} = 2$. Dus}
\Value{f(a,b)}{M}[s] & = \Assign{f}{M}(1, 2) = 1+2 = 3.
\intertext{Om de waarde van $f(f(a,b),a)$ te berekenen, beschouwen we}
\Value{f(f(a,b),a)}{M}[s] & = \Assign{f}{M}(\Value{f(a, b)}{M}[s],
\Value{a}{M}[s]) = \Assign{f}{M}(3, 1) = 3,
\intertext{omdat $3+1 > 3$. Omdat $s(x) = 1$ en $\Value{x}{M}[s] =
  s(x)$, geldt ook}
\Value{f(f(a,b),x)}{M}[s] & = \Assign{f}{M}(\Value{f(a, b)}{M}[s],
\Value{x}{M}[s]) = \Assign{f}{M}(3, 1) = 3,
\end{align*}

