\begin{prop}\ollabel{prop:valindep}
Staan in een term~$t$ alleen de !!{variable}s $x_1$, \dots,~$x_n$,
en geldt $s_1(x_i) = s_2(x_i)$ voor $i = 1$, \dots,~$n$, dan geldt
$\Value{t}{M}[s_1] = \Value{t}{M}[s_2]$.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:valindep}
If the !!{variable}s in a term~$t$ are among $x_1$, \dots,~$x_n$, and
$s_1(x_i) = s_2(x_i)$ for $i = 1$, \dots,~$n$, then $\Value{t}{M}[s_1]
= \Value{t}{M}[s_2]$.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:valindep}
Als de !!{variable}s in een term~$t$ tot $x_1$, \dots,~$x_n$ behoren
en $s_1(x_i) = s_2(x_i)$ voor $i = 1$, \dots,~$n$, dan geldt
$\Value{t}{M}[s_1] = \Value{t}{M}[s_2]$.
\end{prop}

