\begin{prop}\ollabel{prop:satindep}
Zijn de vrije !!{variable}s in~$!A$ allemaal een van
$x_1$, \dots,~$x_n$, en geldt $s_1(x_i) = s_2(x_i)$ voor
$i = 1$, \dots,~$n$, dan geldt $\Sat{M}{!A}[s_1]$ precies als
$\Sat{M}{!A}[s_2]$.
\end{prop}

source_text:
