ordinary_text:
\begin{explain}
Een !!{sentence} is een formule zonder vrije variabelen. Er zijn dus
nul vrije variabelen waarover twee toekenningen het oneens kunnen
zijn. Elke twee toekenningen stemmen daar automatisch op overeen. De
vorige uitspraak zegt daarom iets eenvoudigs: of een zin waar is in
een structuur, hangt helemaal niet af van de gekozen toekenning. We
leggen dat hieronder vast. Daarna kunnen we zeggen dat !!a{sentence}
waar is in !!a{structure} zonder er steeds een toekenning bij te noemen.
\end{explain}

\begin{cor}
\ollabel{cor:sat-sentence}
Als $!A$ !!a{sentence} is en $s$ een toekenning aan variabelen, dan
geldt $\Sat{M}{!A}[s]$ precies als $\Sat{M}{!A}[s']$ voor elke andere
toekenning~$s'$.
\end{cor}

source_text:
\begin{cor}
\ollabel{cor:sat-sentence}
If $!A$ is !!a{sentence} and $s$ a variable assignment, then
$\Sat{M}{!A}[s]$ iff $\Sat{M}{!A}[s']$ for every variable
assignment~$s'$.
\end{cor}

standard_text:
\begin{cor}
\ollabel{cor:sat-sentence}
Als $!A$ !!a{sentence} is en $s$ een bedeling, dan geldt
$\Sat{M}{!A}[s]$ dan en slechts dan als $\Sat{M}{!A}[s']$ voor elke
bedeling~$s'$.
\end{cor}

ordinary_text:
\begin{defn}
\ollabel{defn:satisfaction}
Als $!A$ !!a{sentence} is, zeggen we dat !!a{structure}~$\Struct M$
$!A$ \emph{waar maakt}. We schrijven $\Sat{M}{!A}$. Dit betekent dat
$\Sat{M}{!A}[s]$ geldt voor elke toekenning aan variabelen~$s$.
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:satisfaction}
If $!A$ is !!a{sentence}, we say that !!a{structure}~$\Struct M$
\emph{satisfies}~$!A$, $\Sat{M}{!A}$, iff $\Sat{M}{!A}[s]$ for all
variable assignments~$s$.
\end{defn}

standard_text:
\begin{defn}
\ollabel{defn:satisfaction}
Als $!A$ !!a{sentence} is, zeggen we dat !!a{structure}~$\Struct M$
$!A$ \emph{vervult}, genoteerd $\Sat{M}{!A}$, dan en slechts dan als
$\Sat{M}{!A}[s]$ voor alle bedelingen~$s$.
\end{defn}

ordinary_text:
\begin{defn}
\ollabel{defn:sat}
Neem een verzameling~$\Gamma$ van !!{sentence}s; dezelfde verzameling
noemen we verder~$\Gamma$. We zeggen dat !!a{structure}~$\Struct M$
de verzameling~$\Gamma$ \emph{waar maakt},
en schrijven $\Sat{M}{\Gamma}$, als $\Sat{M}{!A}$ geldt voor elke
$!A \in \Gamma$.
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:sat}
If $\Gamma$ is a set of !!{sentence}s~$\Gamma$, we say that
!!a{structure}~$\Struct M$ \emph{satisfies}~$\Gamma$,
$\Sat{M}{\Gamma}$, iff $\Sat{M}{!A}$ for all $!A \in \Gamma$.
\end{defn}

standard_text:
\begin{defn}
\ollabel{defn:sat}
Beschouw een verzameling~$\Gamma$ van !!{sentence}s; we blijven deze
verzameling aanduiden met~$\Gamma$. We zeggen dat
!!a{structure}~$\Struct M$ de verzameling~$\Gamma$ \emph{vervult},
genoteerd $\Sat{M}{\Gamma}$, dan en slechts dan als
$\Sat{M}{!A}$ voor alle $!A \in \Gamma$.
\end{defn}

