\begin{prop}\ollabel{prop:sat-quant}
  Stel dat in~$!A(x)$ alleen $x$ vrij voorkomt, en neem
  !!a{structure}~$\Struct M$. Dan:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$\Sat{M}{\lexists[x][!A(x)]}$ precies als
      $\Sat{M}{!A(x)}[s]$ voor minstens één toekenning~$s$.}{}
    \tagitem{prvAll}{$\Sat{M}{\lforall[x][!A(x)]}$ precies als
      $\Sat{M}{!A(x)}[s]$ voor elke toekenning~$s$.}{}
\end{tagenumerate}
\end{prop}

source_text:
\begin{prop}\ollabel{prop:sat-quant}
  Suppose $!A(x)$ only contains $x$ free, and $\Struct M$ is
  !!a{structure}. Then:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$\Sat{M}{\lexists[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
      for at least one variable assignment~$s$.}{}
    \tagitem{prvAll}{$\Sat{M}{\lforall[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
  for all variable assignments~$s$.}{}
\end{tagenumerate}
\end{prop}

