\begin{prop}
A sentence $!A$ is valid iff $\Gamma \Entails !A$ for every set of
sentences~$\Gamma$.
\end{prop}

standard_text:
\begin{prop}
Een zin $!A$ is geldig dan en slechts dan als $\Gamma \Entails !A$
voor iedere verzameling zinnen~$\Gamma$.
\end{prop}

ordinary_text:
\begin{prop}
\ollabel{prop:entails-unsat}
$\Gamma \Entails !A$ precies als
$\Gamma \cup \{\lnot !A\}$ niet waar te maken is.
\end{prop}

source_text:
\begin{prop}
\ollabel{prop:entails-unsat}
$\Gamma \Entails !A$ iff $\Gamma \cup \{\lnot !A\}$ is unsatisfiable.
\end{prop}

standard_text:
\begin{prop}
\ollabel{prop:entails-unsat}
$\Gamma \Entails !A$ dan en slechts dan als
$\Gamma \cup \{\lnot !A\}$ onvervulbaar is.
\end{prop}

source_text:
For the reverse direction, suppose $\Gamma \cup \{ \lnot !A \}$ is
unsatisfiable. So for every !!{structure}~$\Struct M$, either
$\Sat/{M}{\Gamma}$ or $\Sat{M}{!A}$. Hence, for every !!{structure}
$\Struct M$ with $\Sat{M}{\Gamma}$, $\Sat{M}{!A}$, so $\Gamma \Entails
!A$.
\end{proof}

ordinary_text:
\begin{prob}
\begin{enumerate}
\item Laat zien dat $\Gamma \Entails \bot$ precies als $\Gamma$ niet
  waar te maken is.
\item Laat zien dat $\Gamma \cup \{!A\} \Entails \bot$ precies als
  $\Gamma \Entails \lnot !A$.
\item Stel dat $c$ niet voorkomt in $!A$ of $\Gamma$. Laat zien dat
  $\Gamma \Entails \lforall[x][!A]$ precies als $\Gamma \Entails
  \Subst{!A}{c}{x}$.
\end{enumerate}
\end{prob}

source_text:
\begin{prob}
\begin{enumerate}
\item Show that $\Gamma \Entails \bot$ iff $\Gamma$ is unsatisfiable.
\item Show that $\Gamma \cup \{!A\} \Entails \bot$ iff $\Gamma \Entails \lnot !A$.
\item Suppose $c$ does not occur in $!A$ or $\Gamma$.  Show that
  $\Gamma \Entails \lforall[x][!A]$ iff $\Gamma \Entails
  \Subst{!A}{c}{x}$.
\end{enumerate}
\end{prob}

standard_text:
\begin{prob}
\begin{enumerate}
\item Toon aan dat $\Gamma \Entails \bot$ dan en slechts dan als
  $\Gamma$ onvervulbaar is.
\item Toon aan dat $\Gamma \cup \{!A\} \Entails \bot$ dan en slechts
  dan als $\Gamma \Entails \lnot !A$.
\item Veronderstel dat $c$ niet voorkomt in $!A$ of $\Gamma$. Toon aan
  dat $\Gamma \Entails \lforall[x][!A]$ dan en slechts dan als
  $\Gamma \Entails
  \Subst{!A}{c}{x}$.
\end{enumerate}
\end{prob}

ordinary_text:
\begin{prop}
Als $\Gamma \subseteq \Gamma'$ en $\Gamma \Entails !A$, dan
$\Gamma' \Entails !A$.
\end{prop}

source_text:
\begin{prop}
If $\Gamma \subseteq \Gamma'$ and $\Gamma \Entails !A$, then $\Gamma'
\Entails !A$.
\end{prop}

standard_text:
\begin{prop}
Als $\Gamma \subseteq \Gamma'$ en $\Gamma \Entails !A$, dan
$\Gamma' \Entails !A$.
\end{prop}

source_text:
\begin{proof}
Suppose that $\Gamma \subseteq \Gamma'$ and $\Gamma \Entails !A$. Let
$\Struct M$ be a structure such that $\Sat{M}{\Gamma'}$; then $\Sat{M}{\Gamma}$,
and since $\Gamma \Entails !A$, we get that $\Sat{M}{!A}$. Hence,
whenever $\Sat{M}{\Gamma'}$, $\Sat{M}{!A}$, so $\Gamma' \Entails !A$.
\end{proof}

ordinary_text:
\begin{thm}[Een aanname in de als-dan-formule zetten (semantische deductiestelling)]
\ollabel{thm:sem-deduction}
$\Gamma \cup \{!A\} \Entails !B$ iff $\Gamma \Entails !A \lif !B$.
\end{thm}

source_text:
\begin{thm}[Semantic Deduction Theorem]
\ollabel{thm:sem-deduction}
$\Gamma \cup \{!A\} \Entails !B$ iff $\Gamma \Entails !A \lif !B$.
\end{thm}

standard_text:
\begin{thm}[Semantische deductiestelling]
\ollabel{thm:sem-deduction}
$\Gamma \cup \{!A\} \Entails !B$ iff $\Gamma \Entails !A \lif !B$.
\end{thm}

source_text:
For the reverse direction, let $\Gamma \Entails !A \lif !B$ and
$\Struct M$ be !!a{structure} so that $\Sat{M}{\Gamma \cup \{ !A
  \}}$. Then $\Sat{M}{\Gamma}$, so $\Sat{M}{!A \lif !B}$, and since
$\Sat{M}{!A}$, $\Sat{M}{!B}$. Hence, whenever $\Sat{M}{\Gamma \cup \{
  !A \} }$, $\Sat{M}{!B}$, so $\Gamma \cup \{ !A \} \Entails !B$.
\end{proof}

ordinary_text:
\begin{prop}\ollabel{prop:quant-terms}
  Neem !!a{structure}~$\Struct{M}$, !!a{formula}~$!A(x)$ met precies
  één vrije variabele~$x$, en een term~$t$ zonder variabelen (een
  gesloten term). Dan geldt:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$!A(t) \Entails \lexists[x][!A(x)]$}{}
    \tagitem{prvAll}{$\lforall[x][!A(x)] \Entails !A(t)$}{}
  \end{tagenumerate}
\end{prop}

source_text:
\begin{prop}\ollabel{prop:quant-terms}
  Let $\Struct{M}$ be !!a{structure}, and $!A(x)$ !!a{formula} with
  one free variable~$x$, and $t$~a closed term. Then:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$!A(t) \Entails \lexists[x][!A(x)]$}{}
    \tagitem{prvAll}{$\lforall[x][!A(x)] \Entails !A(t)$}{}
  \end{tagenumerate}
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:quant-terms}
  Laat $\Struct{M}$ !!a{structure} zijn, $!A(x)$ !!a{formula} met één
  vrije variabele~$x$, en $t$ een gesloten term. Dan geldt:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$!A(t) \Entails \lexists[x][!A(x)]$}{}
    \tagitem{prvAll}{$\lforall[x][!A(x)] \Entails !A(t)$}{}
  \end{tagenumerate}
\end{prop}

ordinary_text:
\begin{proof}
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{%
      \iftag{probEx}{Opgave.}{Stel dat $\Sat{M}{!A(t)}$. Kies een
        toekenning aan variabelen~$s$ met
        $s(x) = \Value{t}{M}$. Dan geldt $\Sat{M}{!A(t)}[s]$, want
        $!A(t)$ is !!a{sentence}. Uit
        \olref[ext]{prop:ext-formulas} volgt $\Sat{M}{!A(x)}[s]$. Uit
        \olref[ass]{prop:sat-quant} volgt
        $\Sat{M}{\lexists[x][!A(x)]}$.}}{}
    \tagitem{prvAll}{%
      \iftag{probAll}{Opgave.}{Stel dat
        $\Sat{M}{\lforall[x][!A(x)]}$. Kies een toekenning aan
        variabelen~$s$ met $s(x) = \Value{t}{M}$. Uit
        \olref[ass]{prop:sat-quant} volgt $\Sat{M}{!A(x)}[s]$. Uit
        \olref[ext]{prop:ext-formulas} volgt $\Sat{M}{!A(t)}[s]$. Uit
        \olref[ass]{prop:sentence-sat-true} volgt
        $\Sat{M}{!A(t)}$, want $!A(t)$ is !!a{sentence}.}}{}
  \end{tagenumerate}
\end{proof}

source_text:
\begin{proof}
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{%
      \iftag{probEx}{Exercise.}{Suppose $\Sat{M}{!A(t)}$. Let $s$ be a
        variable assignment with $s(x) = \Value{t}{M}$. Then
        $\Sat{M}{!A(t)}[s]$ since $!A(t)$ is !!a{sentence}. By
        \olref[ext]{prop:ext-formulas}, $\Sat{M}{!A(x)}[s]$. By
        \olref[ass]{prop:sat-quant},
        $\Sat{M}{\lexists[x][!A(x)]}$.}}{}
    \tagitem{prvAll}{%
      \iftag{probAll}{Exercise.}{Suppose
        $\Sat{M}{\lforall[x][!A(x)]}$. Let $s$ be a variable
        assignment with $s(x) = \Value{t}{M}$. By
        \olref[ass]{prop:sat-quant}, $\Sat{M}{!A(x)}[s]$.  By
        \olref[ext]{prop:ext-formulas}, $\Sat{M}{!A(t)}[s]$. By
        \olref[ass]{prop:sentence-sat-true}, $\Sat{M}{!A(t)}$ since
        $!A(t)$ is !!a{sentence}.}}{}
  \end{tagenumerate}
\end{proof}

standard_text:
\begin{proof}
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{%
      \iftag{probEx}{Opgave.}{Neem aan dat $\Sat{M}{!A(t)}$. Laat $s$
        een bedeling zijn waarvoor $s(x) = \Value{t}{M}$. Dan geldt
        $\Sat{M}{!A(t)}[s]$, omdat $!A(t)$ !!a{sentence} is. Volgens
        \olref[ext]{prop:ext-formulas} geldt $\Sat{M}{!A(x)}[s]$.
        Volgens \olref[ass]{prop:sat-quant} geldt
        $\Sat{M}{\lexists[x][!A(x)]}$.}}{}
    \tagitem{prvAll}{%
      \iftag{probAll}{Opgave.}{Neem aan dat
        $\Sat{M}{\lforall[x][!A(x)]}$. Laat $s$ een bedeling zijn
        waarvoor $s(x) = \Value{t}{M}$. Volgens
        \olref[ass]{prop:sat-quant} geldt $\Sat{M}{!A(x)}[s]$. Volgens
        \olref[ext]{prop:ext-formulas} geldt $\Sat{M}{!A(t)}[s]$.
        Volgens \olref[ass]{prop:sentence-sat-true} geldt
        $\Sat{M}{!A(t)}$, omdat $!A(t)$ !!a{sentence} is.}}{}
  \end{tagenumerate}
\end{proof}

