\begin{prob}
Zoek !!{formula}s in $\Lang L_A$ die de volgende relaties beschrijven:
\begin{enumerate}
\item $n$ ligt tussen $i$ en $j$;
\item $n$ deelt $m$ (dus $m$ is een veelvoud van $n$);
\item $n$ is een priemgetal (dus behalve $1$ en $n$ deelt geen enkel
  getal~$n$).
\end{enumerate}
\end{prob}

