ordinary_text:
\begin{prob}
Stel dat de formule $!A(\Obj v_1, \Obj v_2)$ de relatie $R \subseteq
\Domain M^2$ in !!a{structure}~$\Struct M$ uitdrukt. Zoek formules voor
de volgende relaties:
\begin{enumerate}
\item de inverse $R^{-1}$ van $R$, die elk geordend paar omdraait;
\item de samenstelling $R \mid R$, waarbij je de relatie twee keer
  achter elkaar volgt;
\end{enumerate}
Kun je ook $R^+$ uitdrukken? Dat is de transitieve afsluiting van~$R$:
de kleinste transitieve relatie die de oorspronkelijke relatie bevat.
\end{prob}

source_text:
\begin{prob}
Suppose the formula $!A(\Obj v_1, \Obj v_2)$ expresses the relation $R
\subseteq \Domain M^2$ in !!a{structure}~$\Struct M$.  Find formulas
that express the following relations:
\begin{enumerate}
\item the inverse $R^{-1}$ of $R$;
\item the relative product $R \mid R$;
\end{enumerate}
Can you find a way to express $R^+$, the transitive closure of~$R$?
\end{prob}

standard_text:
\begin{prob}
Veronderstel dat de formule $!A(\Obj v_1, \Obj v_2)$ de relatie $R
\subseteq \Domain M^2$ in !!a{structure}~$\Struct M$ uitdrukt. Vind
formules die de volgende relaties uitdrukken:
\begin{enumerate}
\item de inverse $R^{-1}$ van $R$;
\item de samenstelling (het relatieve product) $R \mid R$;
\end{enumerate}
Kunt u ook $R^+$, de transitieve afsluiting van~$R$, uitdrukken?
\end{prob}

ordinary_text:
\begin{prob}
Neem een taal $\Lang{L}$ met alleen het tweeplaatsige predicaatsymbool
$<$. Er zijn dus geen andere !!{constant}s, !!{function}s of
!!{predicate}s---behalve natuurlijk~$\eq$. Neem de structuur
$\Struct{N}$ waarvoor $\Domain{N} = \Nat$ en
$\Assign{<}{N} = \Setabs{\tuple{n,m}}{n < m}$. Bewijs nu het volgende:
\begin{enumerate}
\item $\{ 0 \}$ is definieerbaar in $\Struct{N}$;
\item $\{ 1 \}$ is definieerbaar in $\Struct{N}$;
\item $\{ 2 \}$ is definieerbaar in $\Struct{N}$;
\item voor iedere $n \in \Nat$ is de verzameling $\{ n \}$
  definieerbaar in $\Struct{N}$;
\item iedere eindige deelverzameling van $\Domain{N}$ is definieerbaar
  in $\Struct{N}$;
\item iedere co-eindige deelverzameling van $\Domain{N}$ is
  definieerbaar in $\Struct{N}$. Hierbij is een $X \subseteq \Nat$
  co-eindig precies als $\Nat \setminus X$ eindig is.
\end{enumerate}
\end{prob}

source_text:
\begin{prob}
Let $\Lang{L}$ be the language containing a 2-place predicate symbol
$<$ only (no other !!{constant}s, !!{function}s or !!{predicate}s---
except of course~$\eq$). Let $\Struct{N}$ be the structure such that
$\Domain{N} = \Nat$, and $\Assign{<}{N} = \Setabs{\tuple{n,m}}{n <
  m}$. Prove the following:
\begin{enumerate}
\item $\{ 0 \}$ is definable in $\Struct{N}$;
\item $\{ 1 \}$ is definable in $\Struct{N}$;
\item $\{ 2 \}$ is definable in $\Struct{N}$;
\item for each $n \in \Nat$, the set $\{ n \}$ is definable in
  $\Struct{N}$;
\item every finite subset of $\Domain{N}$ is definable in
  $\Struct{N}$;
\item every co-finite subset of $\Domain{N}$ is definable in
  $\Struct{N}$ (where $X \subseteq \Nat$ is co-finite iff
  $\Nat \setminus X$ is finite).
\end{enumerate}
\end{prob}

