\begin{defn}
\ollabel{defn:substructure}
Neem !!{structure}s $\Struct M$ en $\Struct M'$ voor dezelfde
taal~$\Lang L$.  We noemen $\Struct M$ een \emph{deel!!{structure}}
(ook: substructuur) van $\Struct M'$.  Omgekeerd noemen we $\Struct M'$
een \emph{uitbreiding} van $\Struct M$.  We schrijven dit als
$\Struct M \substruct \Struct M'$.  Dat geldt precies wanneer:
\begin{enumerate}
\item $\Domain{M} \subseteq \Domain{M'}$,
\item elke constante $c \in \Lang L$ in beide structuren dezelfde
  betekenis heeft: $\Assign{c}{M} =
    \Assign{c}{M'}$;
\item elke $n$-plaatsige !!{function} $f \in \Lang L$ bij alle
  invoeren uit het kleinere domein dezelfde uitkomst geeft:
  $\Assign{f}{M}(a_1, \dots, a_n) = \Assign{f}{M'}(a_1, \dots, a_n)$
  voor alle $a_1$, \dots, $a_n \in \Domain{M}$.
\item elk $n$-plaatsig !!{predicate} $R \in \Lang L$ voor precies
  dezelfde tupels uit het kleinere domein geldt: $\langle
  a_1, \dots, a_n\rangle \in \Assign{R}{M}$ iff $\langle a_1, \dots,
  a_n\rangle \in \Assign{R}{M'}$ voor alle $a_1$, \dots, $a_n \in
  \Domain{M}$.
\end{enumerate}
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:substructure}
Given !!{structure}s $\Struct M$ and $\Struct M'$ for the same
language~$\Lang L$, we say that $\Struct M$ is a \emph{sub!!{structure}}
of $\Struct M'$, and $\Struct M'$ an \emph{extension} of $\Struct M$,
written $\Struct M \substruct \Struct M'$, iff
\begin{enumerate}
\item $\Domain{M} \subseteq \Domain{M'}$,
\item For each constant $c \in \Lang L$, $\Assign{c}{M} =
    \Assign{c}{M'}$;
\item For each $n$-place !!{function} $f \in \Lang L$
  $\Assign{f}{M}(a_1, \dots, a_n) = \Assign{f}{M'}(a_1, \dots, a_n)$
  for all $a_1$, \dots, $a_n \in \Domain{M}$.
\item For each $n$-place !!{predicate} $R \in \Lang L$, $\langle
  a_1, \dots, a_n\rangle \in \Assign{R}{M}$ iff $\langle a_1, \dots,
  a_n\rangle \in \Assign{R}{M'}$ for all $a_1$, \dots, $a_n \in
  \Domain{M}$.
\end{enumerate}
\end{defn}

standard_text:
\begin{defn}
\ollabel{defn:substructure}
Gegeven !!{structure}s $\Struct M$ en $\Struct M'$ voor dezelfde
taal~$\Lang L$ noemen we $\Struct M$ een \emph{sub!!{structure}} van
$\Struct M'$ en $\Struct M'$ een \emph{uitbreiding} van $\Struct M$,
genoteerd als $\Struct M \substruct \Struct M'$, precies dan als
\begin{enumerate}
\item $\Domain{M} \subseteq \Domain{M'}$,
\item voor elke constante $c \in \Lang L$ geldt $\Assign{c}{M} =
    \Assign{c}{M'}$;
\item voor elke $n$-plaatsige !!{function} $f \in \Lang L$ geldt
  $\Assign{f}{M}(a_1, \dots, a_n) = \Assign{f}{M'}(a_1, \dots, a_n)$
  voor alle $a_1$, \dots, $a_n \in \Domain{M}$.
\item voor elk $n$-plaatsig !!{predicate} $R \in \Lang L$ geldt $\langle
  a_1, \dots, a_n\rangle \in \Assign{R}{M}$ iff $\langle a_1, \dots,
  a_n\rangle \in \Assign{R}{M'}$ voor alle $a_1$, \dots, $a_n \in
  \Domain{M}$.
\end{enumerate}
\end{defn}

ordinary_text:
\begin{rem}
\ollabel{rem:substructure}
Als de taal geen constanten of !!{function}s bevat, is het eenvoudiger.
Neem om het even welke $N \subseteq \Domain{M}$.  Daarmee krijg je een
deel!!{structure}~$\Struct{N}$ van $\Struct M$.  Het !!{domain} daarvan
is $\Domain{N} = N$.  De relaties leggen we vast met $\Assign{R}{N} =
\Assign{R}{M} \cap N^n$.
\end{rem}

source_text:
\begin{rem}
\ollabel{rem:substructure}
If the language contains no constant or !!{function}s, then any $N
\subseteq \Domain{M}$ determines a sub!!{structure}~$\Struct{N}$ of
$\Struct M$ with !!{domain}~$\Domain{N} = N$ by putting $\Assign{R}{N} =
\Assign{R}{M} \cap N^n$.
\end{rem}

standard_text:
\begin{rem}
\ollabel{rem:substructure}
Als de taal geen constanten of !!{function}s bevat, bepaalt elke $N
\subseteq \Domain{M}$ een sub!!{structure}~$\Struct{N}$ van
$\Struct M$ met !!{domain}~$\Domain{N} = N$ door $\Assign{R}{N} =
\Assign{R}{M} \cap N^n$ te stellen.
\end{rem}

ordinary_text:
\begin{thm}
\ollabel{overspill} Als een verzameling $\Gamma$ eindige modellen heeft
die zo groot kunnen zijn als je maar wilt, dan heeft die verzameling ook
een oneindig model.
\end{thm}

source_text:
\begin{thm}
\ollabel{overspill} If a set $\Gamma$ of sentences has arbitrarily
large finite models, then it has an infinite model.
\end{thm}

standard_text:
\begin{thm}
\ollabel{overspill} Als een verzameling $\Gamma$ van zinnen willekeurig
grote eindige modellen heeft, dan heeft zij een oneindig model.
\end{thm}

ordinary_text:
\begin{prop}
\ollabel{inf-not-fo} 
Er bestaat geen zin $!A$ in om het even welke taal van de eerste orde die
in !!a{structure}~$\Struct M$ precies dan waar is als het domein
$\Domain{M}$ van de !!{structure} oneindig is.
\end{prop}

source_text:
\begin{prop}
\ollabel{inf-not-fo} 
There is no sentence $!A$ of any first-order language that is true in
!!a{structure}~$\Struct M$ if and only if the domain $\Domain{M}$ of
the !!{structure} is infinite.
\end{prop}

standard_text:
\begin{prop}
\ollabel{inf-not-fo} 
Er bestaat geen zin $!A$ van enige taal van de eerste orde die in
!!a{structure}~$\Struct M$ dan en slechts dan waar is als het domein
$\Domain{M}$ van de !!{structure} oneindig is.
\end{prop}

ordinary_text:
\begin{proof}
Stel dat zo'n $!A$ wel bestond. De negatie $\lnot !A$ zou dan precies in
de eindige !!{structure}s waar zijn. Die negatie zou dus eindige modellen
hebben die zo groot kunnen zijn als je maar wilt, maar geen oneindig
model. Dat is in tegenspraak met \olref{overspill}.
\end{proof}

source_text:
\begin{proof}
If there were such a $!A$, its negation $\lnot !A$ would be true in
all and only the finite !!{structure}s, and it would therefore have
arbitrarily large finite models but it would lack an infinite model,
contradicting \olref{overspill}.
\end{proof}

standard_text:
\begin{proof}
Als zo'n $!A$ bestond, zou de negatie $\lnot !A$ in alle en alleen de
eindige !!{structure}s waar zijn. Zij zou derhalve willekeurig grote
eindige modellen hebben, maar geen oneindig model, in tegenspraak met
\olref{overspill}.
\end{proof}

ordinary_text:
\begin{defn}
\ollabel{defn:elem-equiv} 
Neem twee !!{structure}s $\Struct{M}$ en $\Struct M'$ voor dezelfde
!!{language}~$\Lang{L}$. We zeggen dat $\Struct{M}$ \emph{elementair
equivalent} is met $\Struct M'$, geschreven als $\Struct{M} \equiv
\Struct M'$, als in beide precies dezelfde zinnen waar zijn. Formeel
betekent dit: voor elke !!{sentence}~$!A$ van~$\Lang{L}$,
$\Sat{M}{!A}$ dan en slechts dan als $\Sat{M'}{!A}$.
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:elem-equiv} 
Given two !!{structure}s $\Struct{M}$ and $\Struct M'$ for the same
!!{language}~$\Lang{L}$, we say that $\Struct{M}$ is \emph{elementarily
  equivalent to} $\Struct M'$, written $\Struct{M} \equiv \Struct M'$,
if and only if for every !!{sentence}~$!A$ of~$\Lang{L}$,
$\Sat{M}{!A}$ iff $\Sat{M'}{!A}$.
\end{defn}

standard_text:
\begin{defn}
\ollabel{defn:elem-equiv} 
Gegeven twee !!{structure}s $\Struct{M}$ en $\Struct M'$ voor dezelfde
!!{language}~$\Lang{L}$ noemen we $\Struct{M}$ \emph{elementair
  equivalent met} $\Struct M'$, genoteerd als $\Struct{M} \equiv \Struct M'$,
dan en slechts dan als voor elke !!{sentence}~$!A$ van~$\Lang{L}$ geldt:
$\Sat{M}{!A}$ dan en slechts dan als $\Sat{M'}{!A}$.
\end{defn}

ordinary_text:
\begin{defn}
\ollabel{defn:isomorphism} Neem twee !!{structure}s $\Struct{M}$ en
$\Struct M'$ voor dezelfde !!{language}~$\Lang L$. We zeggen dat
$\Struct{M}$ \emph{isomorf} is met $\Struct M'$, oftewel dat beide
structureel hetzelfde zijn. We schrijven $\Struct{M}
\simeq \Struct M'$ als er een functie $h \colon
\Domain{M} \to \Domain{M'}$ bestaat met de volgende eigenschappen:
\begin{enumerate}
\item $h$ is !!{injective}: twee verschillende objecten krijgen nooit
  hetzelfde beeld; dus als $h(x) = h(y)$, dan $x = y$; 
\item $h$ is !!{surjective}: elk object aan de andere kant wordt geraakt;
  voor elke $y \in \Domain{M'}$ is er dus een $x \in \Domain{M}$ waarvoor
  $h(x) = y$;
\item \ollabel{defn:iso-const}voor elke !!{constant} $c$ wordt het ene
  aangewezen object op het andere afgebeeld:
  $h(\Assign{c}{M}) = \Assign{c}{M'}$;
\item \ollabel{defn:iso-pred}voor elk $n$-plaatsig !!{predicate}~$P$
  geldt in beide richtingen dat een rij objecten onder het predicaat valt:
  \[
  \tuple{a_1, \dots, a_n}\in \Assign{P}{M} \quad\text{iff}\quad
  \tuple{h(a_1), \dots, h(a_n)} \in \Assign{P}{M'};
  \]
\item \ollabel{defn:iso-func}voor elke $n$-plaatsige !!{function} $f$
  maakt het niet uit of je eerst de functie in de eerste structuur
  gebruikt en de uitkomst omzet, of eerst alle invoeren omzet en daarna
  de functie in de tweede structuur gebruikt:
  \[
  h(\Assign{f}{M}(a_1, \dots, a_n)) =
  \Assign{f}{M'}(h(a_1), \dots, h(a_n)).
  \]
\end{enumerate}
\end{defn}

source_text:
\begin{defn}
\ollabel{defn:isomorphism} Given two !!{structure}s $\Struct{M}$ and
$\Struct M'$ for the same !!{language}~$\Lang L$, we say that
$\Struct{M}$ is \emph{isomorphic to}~$\Struct M'$, written $\Struct{M}
\simeq \Struct M'$, if and only if there is a function $h \colon
\Domain{M} \to \Domain{M'}$ such that:
\begin{enumerate}
\item $h$ is !!{injective}: if $h(x) =
  h(y)$ then $x = y$; 
\item $h$ is !!{surjective}: for every $y \in \Domain{M'}$ there
  is $x \in \Domain{M}$ such that $h(x) = y$;
\item \ollabel{defn:iso-const}for every !!{constant} $c$:
  $h(\Assign{c}{M}) = \Assign{c}{M'}$;
\item \ollabel{defn:iso-pred}for every $n$-place !!{predicate}~$P$:
  \[
  \tuple{a_1, \dots, a_n}\in \Assign{P}{M} \quad\text{iff}\quad
  \tuple{h(a_1), \dots, h(a_n)} \in \Assign{P}{M'};
  \]
\item \ollabel{defn:iso-func}for every $n$-place !!{function} $f$:
  \[
  h(\Assign{f}{M}(a_1, \dots, a_n)) =
  \Assign{f}{M'}(h(a_1), \dots, h(a_n)).
  \]
\end{enumerate}
\end{defn}

standard_text:
\begin{defn}
\ollabel{defn:isomorphism} Gegeven twee !!{structure}s $\Struct{M}$ en
$\Struct M'$ voor dezelfde !!{language}~$\Lang L$ noemen we
$\Struct{M}$ \emph{isomorf met}~$\Struct M'$, genoteerd als $\Struct{M}
\simeq \Struct M'$, dan en slechts dan als er een functie $h \colon
\Domain{M} \to \Domain{M'}$ bestaat waarvoor geldt:
\begin{enumerate}
\item $h$ is !!{injective}: als $h(x) =
  h(y)$, dan $x = y$; 
\item $h$ is !!{surjective}: voor elke $y \in \Domain{M'}$ bestaat
  er een $x \in \Domain{M}$ waarvoor $h(x) = y$;
\item \ollabel{defn:iso-const}voor elke !!{constant} $c$:
  $h(\Assign{c}{M}) = \Assign{c}{M'}$;
\item \ollabel{defn:iso-pred}voor elk $n$-plaatsig !!{predicate}~$P$:
  \[
  \tuple{a_1, \dots, a_n}\in \Assign{P}{M} \quad\text{iff}\quad
  \tuple{h(a_1), \dots, h(a_n)} \in \Assign{P}{M'};
  \]
\item \ollabel{defn:iso-func}voor elke $n$-plaatsige !!{function} $f$:
  \[
  h(\Assign{f}{M}(a_1, \dots, a_n)) =
  \Assign{f}{M'}(h(a_1), \dots, h(a_n)).
  \]
\end{enumerate}
\end{defn}

ordinary_text:
\begin{thm}
\ollabel{thm:isom}
Als $\Struct{M} \iso \Struct M'$, dan $\Struct{M} \elemequiv
\Struct{M'}$.
\end{thm}

source_text:
\begin{thm}
\ollabel{thm:isom}
If $\Struct{M} \iso \Struct M'$ then $\Struct{M} \elemequiv
\Struct{M'}$.
\end{thm}

standard_text:
\begin{thm}
\ollabel{thm:isom}
Als $\Struct{M} \iso \Struct M'$, dan $\Struct{M} \elemequiv
\Struct{M'}$.
\end{thm}

source_text:
If $!A$ is a sentence, the assignments~$s$ and $h \circ s$ are
irrelevant, and we have $\Sat{M}{!A}$ iff $\Sat{M'}{!A}$.
\end{proof}

standard_text:
Als $!A$ een zin is, zijn de toekenningen~$s$ en $h \circ s$
irrelevant en geldt $\Sat{M}{!A}$ dan en slechts dan als $\Sat{M'}{!A}$.
\end{proof}

ordinary_text:
\begin{prob}
Werk het bewijs van (b) van \olref[mod][bas][iso]{thm:isom} stap voor
stap uit. Geef aan waar je elk van de vijf eigenschappen uit
\olref[mod][bas][iso]{defn:isomorphism} gebruikt die samen bepalen wat
een isomorfisme is.
\end{prob}

source_text:
\begin{prob}
Carry out the proof of (b) of \olref[mod][bas][iso]{thm:isom} in
detail. Make sure to note where each of the five properties
characterizing isomorphisms of \olref[mod][bas][iso]{defn:isomorphism}
is used.
\end{prob}

standard_text:
\begin{prob}
Werk het bewijs van (b) van \olref[mod][bas][iso]{thm:isom} volledig
uit. Vermeld daarbij waar elk van de vijf eigenschappen wordt gebruikt
die de isomorfismen in \olref[mod][bas][iso]{defn:isomorphism}
karakteriseren.
\end{prob}

ordinary_text:
\begin{defn}
Een \emph{automorfisme} van een structuur $\Struct{M}$ is een
isomorfisme van $\Struct{M}$ naar zichzelf.
\end{defn}

source_text:
\begin{defn}
An \emph{automorphism} of a structure $\Struct{M}$ is an isomorphism
of $\Struct{M}$ onto itself.
\end{defn}

standard_text:
\begin{defn}
Een \emph{automorfisme} van een structuur $\Struct{M}$ is een isomorfisme
van $\Struct{M}$ op zichzelf.
\end{defn}

source_text:
\begin{prob}
Show that for any structure $\Struct{M}$, if $X$ is a definable subset
of $\Struct{M}$, and $h$ is an automorphism of $\Struct{M}$, then $X
= \Setabs{h(x)}{x \in X}$ (i.e., $X$ is fixed under $h$).
\end{prob}

standard_text:
\begin{prob}
Toon voor elke structuur $\Struct{M}$ aan dat, als $X$ een definieerbare
deelverzameling van $\Struct{M}$ is en $h$ een automorfisme van
$\Struct{M}$, dan $X = \Setabs{h(x)}{x \in X}$ (dat wil zeggen: $X$ is
invariant onder $h$).
\end{prob}

ordinary_text:
\begin{defn}
  Neem !!a{structure}~$\Struct M$. De \emph{theorie} van
  $\Struct{M}$ is de verzameling $\Theory{M}$ van alle !!{sentence}s
  die in $\Struct{M}$ waar zijn. Met symbolen: $\Theory{M} =
  \Setabs{!A}{\Sat{M}{!A}}$.
\end{defn}

source_text:
\begin{defn}
  Given !!a{structure}~$\Struct M$, the \emph{theory} of
  $\Struct{M}$ is the set $\Theory{M}$ of !!{sentence}s
  that are true in $\Struct{M}$, i.e., $\Theory{M} =
  \Setabs{!A}{\Sat{M}{!A}}$.
\end{defn}

standard_text:
\begin{defn}
  Gegeven !!a{structure}~$\Struct M$ is de \emph{theorie} van
  $\Struct{M}$ de verzameling $\Theory{M}$ van !!{sentence}s
  die in $\Struct{M}$ waar zijn, dus $\Theory{M} =
  \Setabs{!A}{\Sat{M}{!A}}$.
\end{defn}

ordinary_text:
\begin{prop}
Voor elke $\Struct{M}$ is $\Theory{M}$ compleet.
\end{prop}

source_text:
\begin{prop}
For any $\Struct{M}$, $\Theory{M}$ is complete.
\end{prop}

standard_text:
\begin{prop}
Voor elke $\Struct{M}$ is $\Theory{M}$ compleet.
\end{prop}

ordinary_text:
\begin{proof}
Neem een willekeurige !!{sentence}~$!A$. Dan geldt ofwel
$\Sat{M}{!A}$, ofwel $\Sat{M}{\lnot !A}$. Daarom staat ofwel
$!A \in \Theory{M}$, ofwel $\lnot !A \in \Theory{M}$. De theorie kiest
dus voor elke zin de zin zelf of haar ontkenning.
\end{proof}

source_text:
\begin{proof}
For any !!{sentence}~$!A$ either $\Sat{M}{!A}$ or $\Sat{M}{\lnot !A}$,
so either $!A \in \Theory{M}$ or $\lnot !A \in \Theory{M}$.
\end{proof}

standard_text:
\begin{proof}
Voor elke !!{sentence}~$!A$ geldt ofwel $\Sat{M}{!A}$, ofwel
$\Sat{M}{\lnot !A}$. Dus geldt ofwel $!A \in \Theory{M}$, ofwel
$\lnot !A \in \Theory{M}$.
\end{proof}

ordinary_text:
\begin{prop}\ollabel{prop:equiv}
  Als $\Struct{N} \models !A$ voor elke $!A \in \Theory{M}$, dan
  $\Struct{M} \elemequiv \Struct{N}$.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:equiv}
  If $\Struct{N} \models !A$ for every $!A \in \Theory{M}$, then
  $\Struct{M} \elemequiv \Struct{N}$.
\end{prop}

standard_text:
\begin{prop}\ollabel{prop:equiv}
  Als $\Struct{N} \models !A$ voor elke $!A \in \Theory{M}$, dan
  $\Struct{M} \elemequiv \Struct{N}$.
\end{prop}

source_text:
\begin{rem}\ollabel{remark:R}
  Consider $\Struct{R} = \langle\Real, <\rangle$, the !!{structure}
  whose domain is the set $\Real$ of the real numbers, in the !!{language}
  comprising only a 2-place !!{predicate} interpreted as the $<$
  relation over the reals. Clearly $\Struct{R}$ is !!{nonenumerable};
  however, since $\Theory{R}$ is obviously consistent, by the
  L\"owenheim--Skolem theorem it has !!a{enumerable} model, say
  $\Struct{S}$, and by \olref{prop:equiv}, $\Struct{R}
  \equiv \Struct{S}$. Moreover, since $\Struct{R}$ and $\Struct{S}$
  are not isomorphic, this shows that the converse of
  \olref[iso]{thm:isom} fails in general.
\end{rem}

ordinary_text:
\begin{defn}
  Neem twee !!{structure}s $\Struct{M}$ en $\Struct{N}$. Een
  \emph{partieel isomorfisme} van $\Struct{M}$ naar $\Struct{N}$ is
  een functie $p$ die maar voor eindig veel elementen van $\Domain M$
  is ingevuld en die waarden in $\Domain N$ geeft. Op dat eindige deel
  moet de functie zich houden aan de voorwaarden voor een isomorfisme uit
  \olref[iso]{defn:isomorphism}:
  \begin{enumerate}
  \item $p$ is !!{injective}: twee verschillende invoeren krijgen dus
    nooit dezelfde uitkomst;
  \item neem een !!{constant}~$c$. Als $p(\Assign{c}{M})$ is
    gedefinieerd, dan $p(\Assign{c}{M}) = \Assign{c}{N}$;
  \item neem een $n$-plaatsig !!{predicate} $P$. Als $a_1$, \dots, $a_n$
    in het domein van $p$ zitten, dan geldt
    $\langle a_1, \dots, a_n\rangle \in \Assign P M$ precies wanneer
    $\langle p(a_1), \dots, p(a_n) \rangle \in \Assign P N$;
  \item neem een $n$-plaatsige !!{function} $f$. Als $a_1$, \dots, $a_n$
    in het domein van $p$ zitten, dan $p(\Assign f M (a_1, \dots,a_n))
    = \Assign f N (p(a_1), \dots, p(a_n))$.
  \end{enumerate}
  Met ‘$p$ is eindig’ bedoelen we dus dat $\dom{p}$ eindig is.
\end{defn}

source_text:
\begin{defn}
  Given two !!{structure}s $\Struct{M}$ and $\Struct{N}$, a
  \emph{partial isomorphism} from $\Struct{M}$ to $\Struct{N}$ is a
  finite partial function $p$ taking arguments in $\Domain M$ and returning
  values in $\Domain N$, which satisfies the isomorphism conditions from
  \olref[iso]{defn:isomorphism} on its domain:
  \begin{enumerate}
  \item $p$ is !!{injective};
  \item for every !!{constant}~$c$: if $p(\Assign{c}{M})$ is defined,
    then $p(\Assign{c}{M}) = \Assign{c}{N}$;
  \item for every $n$-place !!{predicate} $P$: if $a_1$, \dots, $a_n$
    are in the domain of $p$, then $\langle a_1, \dots, a_n\rangle \in
    \Assign P M$ if and only if $\langle p(a_1), \dots, p(a_n) \rangle
    \in \Assign P N$;
  \item for every $n$-place !!{function} $f$: if $a_1$, \dots, $a_n$
    are in the domain of $p$, then $p(\Assign f M (a_1, \dots,a_n))
    = \Assign f N (p(a_1), \dots, p(a_n))$.
  \end{enumerate}
  That $p$ is finite means that $\dom{p}$ is finite.
\end{defn}

standard_text:
\begin{defn}
  Gegeven twee !!{structure}s $\Struct{M}$ en $\Struct{N}$ is een
  \emph{partieel isomorfisme} van $\Struct{M}$ naar $\Struct{N}$ een
  eindige partiële functie $p$ die argumenten uit $\Domain M$ neemt en
  waarden in $\Domain N$ oplevert, en die op haar domein voldoet aan de
  isomorfievoorwaarden uit \olref[iso]{defn:isomorphism}:
  \begin{enumerate}
  \item $p$ is !!{injective};
  \item voor elke !!{constant}~$c$: als $p(\Assign{c}{M})$ gedefinieerd is,
    dan $p(\Assign{c}{M}) = \Assign{c}{N}$;
  \item voor elk $n$-plaatsig !!{predicate} $P$: als $a_1$, \dots, $a_n$
    tot het domein van $p$ behoren, dan geldt $\langle a_1, \dots, a_n\rangle \in
    \Assign P M$ dan en slechts dan als $\langle p(a_1), \dots, p(a_n) \rangle
    \in \Assign P N$;
  \item voor elke $n$-plaatsige !!{function} $f$: als $a_1$, \dots, $a_n$
    tot het domein van $p$ behoren, dan $p(\Assign f M (a_1, \dots,a_n))
    = \Assign f N (p(a_1), \dots, p(a_n))$.
  \end{enumerate}
  Dat $p$ eindig is, betekent dat $\dom{p}$ eindig is.
\end{defn}

ordinary_text:
\begin{defn}\ollabel{defn:partialisom}
  Twee !!{structure}s $\Struct{M}$ en $\Struct{N}$ zijn
  \emph{partieel isomorf}, geschreven als $\Struct{M} \iso[p]
  \Struct{N}$, als er een niet-lege verzameling $I$ van partiële
  isomorfismen tussen $\Struct{M}$ en $\Struct{N}$ is waarmee je aan
  beide kanten steeds verder kunt gaan. Precies gezegd moet die verzameling aan de
  \emph{heen-en-weereigenschap} voldoen:
  \begin{enumerate}
  \item (\emph{Heen}) Neem een $p \in I$ en een $a \in \Domain M$.
    Dan is er een $q \in I$ met $p \subseteq q$ waarbij $a$ in het
    domein van $q$ zit;
  \item (\emph{Weer}) Neem een $p \in I$ en een $b \in \Domain N$.
    Dan is er een $q \in I$ met $p \subseteq q$ waarbij $b$ in het
    bereik van $q$ zit.
  \end{enumerate}
\end{defn}

source_text:
\begin{defn}\ollabel{defn:partialisom}
  Two !!{structure}s $\Struct{M}$ and $\Struct{N}$, are
  \emph{partially isomorphic}, written $\Struct{M} \iso[p]
  \Struct{N}$, if and only if there is a non-empty set $I$
  of partial isomorphisms between $\Struct{M}$ and $\Struct{N}$
  satisfying the \emph{back-and-forth} property:
  \begin{enumerate}
  \item (\emph{Forth}) For every $p \in I$ and $a \in \Domain M$
    there is $q \in I$ such that $p \subseteq q$ and $a$ is
    in the domain of $q$;
  \item (\emph{Back}) For every $p \in I$ and $b \in \Domain N$
    there is $q \in I$ such that $p \subseteq q$ and $b$ is
    in the range of $q$.
  \end{enumerate}
\end{defn}

standard_text:
\begin{defn}\ollabel{defn:partialisom}
  Twee !!{structure}s $\Struct{M}$ en $\Struct{N}$ zijn
  \emph{partieel isomorf}, genoteerd $\Struct{M} \iso[p]
  \Struct{N}$, dan en slechts dan als er een niet-lege verzameling $I$
  van partiële isomorfismen tussen $\Struct{M}$ en $\Struct{N}$ bestaat
  die aan de \emph{heen-en-weereigenschap} voldoet:
  \begin{enumerate}
  \item (\emph{Heen}) Voor elke $p \in I$ en $a \in \Domain M$
    bestaat er een $q \in I$ zodat $p \subseteq q$ en $a$
    tot het domein van $q$ behoort;
  \item (\emph{Weer}) Voor elke $p \in I$ en $b \in \Domain N$
    bestaat er een $q \in I$ zodat $p \subseteq q$ en $b$
    tot het bereik van $q$ behoort.
  \end{enumerate}
\end{defn}

ordinary_text:
\begin{thm}\ollabel{thm:p-isom1}
  Als $\Struct{M} \iso[p] \Struct{N}$ en $\Struct{M}$ en
  $\Struct{N}$ !!{enumerable} zijn, dan $\Struct{M} \iso
  \Struct{N}$.
\end{thm}

